<p>البروز يغيّر ما حول الجدار. إطار الباب والنافذة قد يصير أغور من الطوب فيلزمه قفلة. الأفياش تحتاج تطويلاً. والنعلة العادية الرقيقة تختفي تحته، فاختر نعلة أسمك أو أنهِ الطوب فوقها.</p>
<h3>التركيب</h3>
<p>جدار مليَّس متماسك وجاف. لاصق مناسب للفوم لا يحتوي مذيبات، يوزَّع على محيط الظهر وخطوطاً في وسطه. يُسند الصف الأول حتى يمسك لأن ما فوقه يرتكز عليه. تُرتَّب الألواح بتبديل وتدوير حتى لا تتجاور الطوبة المميزة نفسها. تُملأ خطوط الالتقاء بمعجون يُلوَّن بلون المونة. لحساب العدد اقسم مساحة الجدار على 0.73: جدار 3.5 × 2.8 م مساحته 9.8 م² يحتاج 14 لوحاً ومعها لوح احتياط للقص، أو استخدم <a href="https://texadecore.store/quantity-calculator/">الحاسبة</a>، وللتنفيذ <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
