<p>سطح مليَّس جاف نظيف. اللاصق من النوع الآمن على الفوم، بلا مذيبات. الصف السفلي يُضبط أفقياً ويُسند، ثم تُرفع الصفوف. القص بمنشار ناعم، وتُخفى الحافة المقصوصة عند الزاوية. بعد الجفاف تُعبَّأ الوصلات وتُلوَّن. <a href="https://texadecore.store/install-services/">خدمات التركيب</a> تنفذه، و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> تعطيك العدد.</p>
<h3>ما يُطلب معه</h3>
<p>معجون ولون للوصلات، رفوف خشبية أو حديد أسود تكمل الطراز (تُثبَّت في الجدار عبر اللوح)، ونعلة داكنة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. الألوان في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b7%d9%88%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%b7%d9%88%d8%a8-%d9%81%d9%8a%d9%86%d8%aa%d8%af%d8%ac/">قسم بديل طوب فينتدج</a>.</p>
<h3>العناية</h3>
<p>مكنسة بفرشاة للغبار، وقطعة قماش مبللة للبقع بالتربيت.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li><strong>قابل للاحتراق</strong> فيُبعد عن مصادر اللهب والحرارة.</li>
<li>طراز قوي الشخصية لا يوافق الديكور الكلاسيكي المذهّب.</li>
<li>مسامّه تمسك الغبار والدهون أكثر من الأسطح الملساء.</li>
<li>بروزه 3 سم يستدعي معالجة الأفياش والحلوق.</li>
<li>ينبعج بالطَّرق القوي.</li>
</ul>
<p>إن أردت طوباً أهدأ فانظر بقية أنماط <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b7%d9%88%d8%a8/">بديل الطوب</a>.</p>' ),
	'cp-strip' => array( 'دليل موكيت الشرائح', '<h3>ما هو موكيت الشرائح؟</h3>
<p>موكيت يأتي قطعاً جاهزة بدل الرول. وجهه خيوط بولي بروبيلين مستمرة (PP BCF) قصيرة الوبر، وظهره طبقة PVC ثقيلة تثبّت القطعة على الأرض. اسم القسم «شرائح»، لكن أغلب تصاميمه قطعة مربعة 50 × 50 سم بسماكة 5 ملم، وثمانية تصاميم فقط شريحة مستطيلة 25 × 100 سم. في الحالتين القطعة ربع متر مربع، فالمتر أربع قطع، ومكتب 4 × 5 أمتار يحتاج 80 قطعة تصير 88 مع هدر 10%. تصميمان يذكران سماكة 3 ملم. السعر بالمتر المربع دون تركيب.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>المكاتب وقاعات الاجتماعات</td><td>مناسب</td><td>وبر قصير يتحمل الكراسي المتحركة ويخفف الصدى</td></tr>
<tr><td>غرفة ألعاب أو سينما منزلية</td><td>مناسب</td><td>يمتص الصوت، وتُبدَّل القطعة المتسخة وحدها</td></tr>
<tr><td>المجلس وغرفة النوم</td><td>مقبول</td><td>ملمسه أقسى من الموكيت الوثير، فجرّب عيّنة</td></tr>
<tr><td>المطبخ والحمام</td><td>لا</td><td>الوبر يحتفظ بالماء والدهون</td></tr>
<tr><td>مدخل يدخله الرمل مباشرة</td><td>غير مفضّل</td><td>يتلبّد ويغمق في مسار المشي</td></tr>
<tr><td>فوق بلاط أو أرضية خرسانية ملساء</td><td>مناسب</td><td>بشرط الجفاف والاستواء</td></tr>
</tbody>
</table>
<h3>مربع 50 × 50 أم شريحة 25 × 100؟</h3>
<p>الخامة واحدة والفرق في الرسم على الأرض. المربع يعطي شكل رقعة الشطرنج إذا بُدّل اتجاه الوبر بين قطعة وأخرى، أو سطحاً شبه متصل إذا وُحّد الاتجاه. الشريحة تُرصّ كالباركيه بتخالف أو بنمط هرمي، وتُطيل الغرفة بصرياً. اسأل عن شكل التصميم الذي اخترته، فالاسم وحده لا يحدده. وبقية التصاميم في قسم <a href="https://texadecore.store/product-category/%d9%85%d9%88%d9%83%d9%8a%d8%aa/%d9%85%d9%88%d9%83%d9%8a%d8%aa-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">موكيت الشرائح</a>.</p>
<h3>التركيب: ماذا تحتاج الأرضية؟</h3>
<ul>
<li><strong>أرضية ملساء جافة ونظيفة.</strong> الغبار يمنع المثبّت من الإمساك.</li>
<li><strong>مثبّت يبقى لزجاً لا غراء دائم،</strong> حتى تُرفع القطعة وتُبدَّل دون أن تتمزق.</li>
<li><strong>البداية من منتصف الغرفة</strong> على خطّين متعامدين، فتتساوى القصّات عند الجدران.</li>
<li><strong>سهم الاتجاه في ظهر القطعة</strong> يُتبع بحسب النمط المختار.</li>
<li><strong>لا فجوة تمدد هنا:</strong> القطع تُحشر متلاصقة حتى الجدار.</li>
</ul>
<p>التنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والعدد نحسبه لك إن أرسلت المقاسات على الواتساب.</p>
<h3>ما الذي يُطلب معه؟</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> تغطي حافة القص عند الجدار، وقطع احتياطية تُخزَّن مسطّحة، لأن لون التشغيلة التالية قد يختلف.</p>
<h3>العناية والتنظيف</h3>
<p>مكنسة كهربائية مرتين أسبوعياً. البقعة تُنشَّف بالضغط لا بالفرك، ثم تُنظَّف بمنظف موكيت. والقطعة التي لا تنظف تُرفع وتُغسل وتُجفَّف أو تُستبدل. بدّل مواقع قطع المسار المزدحم مع قطع تحت الأثاث كل مدة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>الفواصل تبقى مرئية قليلاً، خصوصاً في السادة الفاتح.</li>
<li>يحتجز الغبار إن أُهمل كنسه، وهذا يهم من عنده حساسية.</li>
<li>الأطراف ترتفع فوق أرضية رطبة أو غير مستوية.</li>
<li>ليس ناعماً كموكيت غرف النوم.</li>
</ul>
<p>إن أردت أرضية تُمسح بالماء فانظر <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/">باركيه SPC</a>.</p>' ),
	'cp-tile' => array( 'دليل موكيت البلاطات', '<h3>موكيت بلاطات 50 × 50 سم</h3>
<p>أربعة تصاميم فقط: كحلي فاتح، رمادي فاتح، رمادي غامق، وبني مدرّج. البلاطة 50 × 50 سم بسماكة 3 ملم، وجهها بولي بروبيلين بخيوط مستمرة وظهرها PVC. كل أربع بلاطات تغطي متراً مربعاً. الألوان داكنة ومحايدة، وهي ألوان مكاتب وممرات عمل أكثر منها ألوان غرف نوم.</p>
<h3>ما الفرق بينه وبين موكيت الشرائح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">البند</th><th scope="col">موكيت البلاطات</th><th scope="col">موكيت الشرائح</th></tr>
</thead>
<tbody>
<tr><td>السماكة المذكورة</td><td>3 ملم</td><td>5 ملم في أغلبه</td></tr>
<tr><td>عدد التصاميم</td><td>4</td><td>38</td></tr>
<tr><td>شكل القطعة</td><td>مربع 50 × 50</td><td>مربع 50 × 50، وبعضه شريحة 25 × 100</td></tr>
<tr><td>الخامة</td><td>بولي بروبيلين على PVC</td><td>نفسها</td></tr>
</tbody>
</table>
<p>السماكة الأقل تعني وسادة أرق تحت القدم وعزل صوت أقل، ومقابلها ارتفاع أقل للأرضية تحت الأبواب وعند التقاء الموكيت ببلاط الممر. التشكيلة الأوسع في <a href="https://texadecore.store/product-category/%d9%85%d9%88%d9%83%d9%8a%d8%aa/%d9%85%d9%88%d9%83%d9%8a%d8%aa-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">موكيت الشرائح</a>.</p>
<h3>أين نضعه؟</h3>
<ul>
<li><strong>مناسب:</strong> مكتب، غرفة اجتماعات، استوديو تسجيل منزلي، مصلّى صغير في شركة.</li>
<li><strong>مقبول:</strong> غرفة أطفال أكبر سناً، مع قبول ملمسه العملي.</li>
<li><strong>لا:</strong> أي مكان يصله الماء، والمداخل المكشوفة للشارع.</li>
</ul>
<h3>التركيب</h3>
<p>بلاطة بسماكة 3 ملم تنقل ما تحتها: حبة رمل أو فاصل بلاط غائر يظهر انتفاخاً أو خطاً. فتُنظَّف الأرض جيداً، وتُعبَّأ الفواصل العميقة. تُثبَّت البلاطات بمادة تبقى لزجة وتسمح برفعها، ويُرصّ الصف الأول على خيط مشدود في وسط الغرفة. القص عند الجدار يكون من ظهر البلاطة بمشرط حاد ومسطرة معدنية. التنفيذ متاح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>الكمية</h3>
<p>اضرب المساحة في أربعة ثم أضف نحو 10% للقص، وزد بضع بلاطات احتياطاً، فأربعة تصاميم فقط تعني أن اللون قد لا يتوفر حين تحتاج بديلاً. أو أرسل لنا المقاس على الواتساب. أكّد وحدة البيع مع الطلب.</p>
<h3>يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> للمحيط، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل نهاية</a> حيث ينتهي الموكيت عند بلاط مكشوف حتى لا تتنسّل حافته.</p>
<h3>العناية</h3>
<p>كنس كهربائي منتظم. السائل المنسكب يُمتص بمنديل فوراً قبل أن يصل إلى الظهر.</p>
<h3>متى لا يناسبك؟</h3>
<ul>
<li>تريد ألواناً دافئة أو نقشات، والمعروض أربعة ألوان.</li>
<li>تبحث عن موكيت وثير تغوص فيه القدم.</li>
<li>الأرضية تحته خشنة ولن تُسوّى.</li>
</ul>
<p>كل أنواع الموكيت في قسم <a href="https://texadecore.store/product-category/%d9%85%d9%88%d9%83%d9%8a%d8%aa/">الموكيت</a>.</p>' ),
	'cs-clay' => array( 'دليل الصفائح الطينية', '<h3>ما هي الصفائح الطينية؟</h3>
<p>صفيحة رقيقة مرنة، مزيج من الطين الطبيعي والرمل وبودرة الحجر يُعالَج بالحرارة. المقاس الأشيع 120 × 60 سم، فالصفيحة تغطي 0.72 م²، وتوجد تصاميم قليلة بمقاس 120 × 290 سم. منشؤها الصين. المنتجات التي تذكر السماكة والوزن قليلة، وتقول نحو 2 ملم ونحو 2 كجم للصفيحة؛ النقشات الخشنة والمضلعة أسمك. ملمسها حجري حقيقي: جرانيتي، صخري، إسمنتي، خشن وناعم.</p>
<h3>المرونة: أين تفيدك؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">السطح</th><th scope="col">ما تفعله الصفيحة</th></tr>
</thead>
<tbody>
<tr><td>عمود دائري</td><td>تلتف حوله قطعة واحدة بلا تقطيع إلى شرائح</td></tr>
<tr><td>قوس أو جدار منحنٍ</td><td>تتبع الانحناء؛ تُدفَّأ قليلاً للانحناء الحاد</td></tr>
<tr><td>ركن خارجي</td><td>تُلف حوله أو تُقص بميل، فلا تحتاج زاوية معدنية</td></tr>
<tr><td>لوح جبس وقاطع خفيف</td><td>وزنها القليل لا يستدعي تدعيماً</td></tr>
</tbody>
</table>
<p>للقطر الصغير جداً جرّب قطعة أولاً، فالنقشة الخشنة قد تتشقق.</p>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">الملاحظة</th></tr>
</thead>
<tbody>
<tr><td>جدران المجالس والمداخل والأعمدة</td><td>مناسب</td><td>ملمس حجر بوزن خفيف</td></tr>
<tr><td>الواجهات والأسوار</td><td>راجع المواصفة</td><td>أكّد صلاحية التصميم المختار للخارج واللاصق الخارجي المناسب قبل الطلب</td></tr>
<tr><td>جدار الحمام والمطبخ</td><td>اسأل قبل الطلب</td><td>تُمسح وتتحمل الرطوبة العادية</td></tr>
<tr><td>جدار متموج أو خشن</td><td>لا قبل التسوية</td><td>رقيقة تطبع ما تحتها</td></tr>
<tr><td>الأرضيات</td><td>لا</td><td>هذا الدليل للجدران</td></tr>
</tbody>
</table>
<h3>التركيب: ليست كالألواح</h3>
<ul>
<li><strong>اللاصق يُفرد بمشط مسنّن على الجدار كاملاً</strong>، لا نقاطاً. الفراغ خلفها سبب السقوط الأول.</li>
<li>يُمسح ظهر الصفيحة من الغبار، ثم تُضغط وتُمرَّر عليها أسطوانة لإخراج الهواء.</li>
<li><strong>القص بكتر ومسطرة معدنية:</strong> حزّتان أو ثلاث ثم ثني. لا غبار ولا صاروخ إلا للنقشات السميكة.</li>
<li><strong>اخلط الصفائح من الكراتين</strong> قبل اللصق؛ درجاتها تتفاوت طبيعياً.</li>
<li>الفواصل: إمّا متلاصقة، أو خط مقصود بعرض ثابت يُعبَّأ.</li>
<li>في الخارج لا تُركَّب تحت شمس الظهيرة حتى لا يجف اللاصق قبل أن يمسك.</li>
</ul>
<p>الفنيون المتمرسون فيها أقل من فنيي الألواح، فالأسلم <a href="https://texadecore.store/install-services/">خدمات التركيب</a>. العدد من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>: جدار 4 × 2.8 م مثلاً يأخذ 16 صفيحة، وتُضاف صفيحتان للقص والخلط.</p>
<h3>ما يُطلب معها</h3>
<p>اللاصق المخصص بالكمية الكافية للفرد الكامل، مادة لتعبئة الفواصل، ونعلة للداخل من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. التصاميم في <a href="https://texadecore.store/product-category/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9-%d9%88%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9/">قسم الصفائح الطينية</a>.</p>
<h3>العناية</h3>
<p>فرشاة ناعمة للغبار في الملمس الخشن، وإسفنجة رطبة للبقع. لا أحماض ولا ضغط ماء عالٍ على الفواصل.</p>
<h3>عيوبها ومتى لا تناسبك</h3>
<ul>
<li>أغلب مشاكلها من التركيب: لاصق خاطئ أو جدار مغبر فترتفع الأطراف.</li>
<li>تُظهر نتوءات الجدار، فتسويته تُحسب ضمن تكلفة العمل ووقته.</li>
<li>تفاوت الدرجات يصير بقعاً إن لم تُخلط.</li>
<li>اسأل عن السماكة والوزن للتصميم المختار.</li>
</ul>
<p>وإن أردت بروز صخر واضح فهي أرقّ من ذلك؛ انظر <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ad%d8%ac%d8%b1/">بديل الحجر</a>.</p>' ),
	'cs-stone' => array( 'دليل الصفائح الحجرية', '<h3>ما هي الصفائح الحجرية؟</h3>
<p>صفائح تكسية بمقاس 120 × 60 سم (0.72 م² للصفيحة) بمظهر حجر طبيعي هادئ، أغلبها بدرجات الرمادي، ومنشؤها الصين. اسأل الفريق عن الخامة والسماكة والوزن قبل الطلب. وهي مدرجة مع الصفائح الطينية المرنة في قسم واحد، لكن لا تفترض أنها بالمرونة نفسها قبل أن تسأل.</p>
<h3>اسأل عن هذه قبل الطلب</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">السؤال</th><th scope="col">لماذا؟</th></tr>
</thead>
<tbody>
<tr><td>ما الخامة؟ وهل الصفيحة مرنة أم صلبة؟</td><td>يحدد هل تلتف على عمود وهل تُقص بكتر أم بصاروخ</td></tr>
<tr><td>كم السماكة والوزن؟</td><td>يحدد اللاصق وهل تصلح على لوح جبس</td></tr>
<tr><td>هل تصلح للواجهة تحت الشمس والمطر؟</td><td>يحتاج تأكيداً للتصميم المختار</td></tr>
<tr><td>هل يتطابق اللون بين الكراتين؟</td><td>الدرجات الرمادية تتفاوت بين دفعة وأخرى</td></tr>
</tbody>
</table>
<p>واطلب صورة حقيقية للوجه والظهر والحافة؛ الظهر يخبرك بالخامة أكثر من الوجه.</p>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">الملاحظة</th></tr>
</thead>
<tbody>
<tr><td>جدار مدخل، واجهة استقبال، خلفية تلفاز</td><td>مناسب</td><td>رمادي حجري هادئ يوافق الديكور الحديث</td></tr>
<tr><td>عمود مربع</td><td>مناسب</td><td>بقص عند الأركان</td></tr>
<tr><td>عمود دائري</td><td>بعد التأكد من المرونة</td><td>اسأل عنها</td></tr>
<tr><td>واجهة خارجية</td><td>راجع المواصفة</td><td>يلزم تأكيد صلاحيتها للخارج مع اللاصق المناسب</td></tr>
<tr><td>حمام ومطبخ</td><td>اسأل قبل الطلب</td><td>تُمسح وتتحمل الرطوبة العادية</td></tr>
<tr><td>الأرضيات</td><td>لا</td><td>لا نوصي بها قبل تأكيد السماكة وتحمّل المشي</td></tr>
</tbody>
</table>
<h3>اختيار الدرجة</h3>
<p>أسماء المنتجات متشابهة («رمادي هادئ») والفارق في الكود والصورة. قارن الصور جنباً إلى جنب، واطلب كمية الجدار كله في طلب واحد حتى تأتي من دفعة واحدة، واحتفظ برقم الطلب إن احتجت تكملة لاحقاً. الرمادي البارد يحتاج خشباً أو إضاءة دافئة بجانبه حتى لا يبدو المكان مكتبياً.</p>
<h3>التركيب</h3>
<p>القاعدة العامة للصفائح: جدار مستوٍ متماسك نظيف، ولاصق يُفرد على كامل المساحة لا نقاطاً، وضغط يطرد الهواء. طريقة القص ونوع اللاصق يتبعان الخامة والسماكة بعد تأكيدهما. تُرتَّب الصفائح على الأرض أولاً لتوزيع الدرجات. <a href="https://texadecore.store/install-services/">خدمات التركيب</a> تعاين وتؤكد، والعدد من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> بإدخال 120 × 60.</p>
<h3>ما يُطلب معها</h3>
<p>اللاصق الذي يحدده الفريق، مادة للفواصل، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. التصاميم في <a href="https://texadecore.store/product-category/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9-%d9%88%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/">قسم الصفائح الحجرية</a>، وقريبتها الموثّقة أكثر في <a href="https://texadecore.store/product-category/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9-%d9%88%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9/">الصفائح الطينية</a>.</p>
<h3>العناية</h3>
<p>غبارها يُنفض بفرشاة ناعمة، وتُمسح بإسفنجة رطبة. تجنّب الأحماض ومزيلات الكلس حتى تعرف الخامة.</p>
<h3>عيوبها ومتى لا تناسبك</h3>
<ul>
<li>معلوماتها المكتوبة أقل ما في القسم؛ القرار يحتاج مراسلة.</li>
<li>ألوانها محصورة في الرمادي تقريباً.</li>
<li>تطبع عيوب الجدار إن كانت رقيقة.</li>
<li>خطأ اللاصق يُسقطها.</li>
</ul>
<p>إن كنت مستعجلاً فاختر خامة مواصفاتها مكتوبة كاملة من <a href="https://texadecore.store/product-category/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9-%d9%88%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/">القسم نفسه</a>.</p>' ),
	'ex-hpl' => array( 'دليل ألواح HPL للواجهات والجدران', '<h3>ما هو لوح HPL؟</h3>
<p>لوح مسطح صلب يُصنع بكبس طبقات مشبعة بالراتنج تحت ضغط وحرارة عاليين، ومنه اسمه «عالي الضغط». ألواح هذه المجموعة بثلاثة خيارات: 244 × 122 سم بسماكة 6 ملم، والمقاس نفسه بسماكة 8 ملم، و305 × 122 سم بسماكة 6 ملم، وبألوان خشبية ورمادية. يغطي اللوح الصغير نحو 2.98 م² والكبير نحو 3.72 م². تُستخدم للتكسية الداخلية والخارجية، وتحمّلها للعوامل الجوية يُؤكَّد من مواصفة المورّد قبل اعتماد اللوح لواجهة مكشوفة.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الموضع</th><th scope="col">الحكم</th><th scope="col">الشرط</th></tr>
</thead>
<tbody>
<tr><td>واجهة أو جزء منها</td><td>مناسب</td><td>على هيكل بفراغ تهوية، وبعد تأكيد أن اللوح بدرجة خارجية</td></tr>
<tr><td>مدخل، استقبال، جدار محل</td><td>مناسب</td><td>سطح صلب يتحمل الاحتكاك اليومي</td></tr>
<tr><td>سور أو جدار حوش</td><td>مناسب</td><td>بهيكل لا يصدأ</td></tr>
<tr><td>لصق مباشر على جدار خارجي</td><td>لا</td><td>الحرارة والرطوبة تُحبسان خلف اللوح</td></tr>
<tr><td>أرضية أو سطح يُمشى عليه</td><td>لا</td><td>لوح تكسية جدارية</td></tr>
</tbody>
</table>
<h3>6 ملم أم 8 ملم؟</h3>
<p>السماكة تحدد كم يتحمل اللوح بين نقطتي تثبيت. لوح 8 ملم أصلب، فيناسب الواجهة المعرّضة للريح والمسافات الأوسع بين قطاعات الهيكل. لوح 6 ملم أخف ويكفي الجدار الداخلي والمساحات المحمية. المسافة المسموح بها لكل سماكة يحددها المصنّع، فاطلبها.</p>
<h3>الهيكل والتهوية والتمدد</h3>
<ul>
<li><strong>الهيكل:</strong> قطاعات ألمنيوم أو حديد مجلفن تُثبَّت في الجدار، ومسافاتها في الغالب بين 40 و60 سم. الخشب غير المعالج والحديد العادي يتلفان في الخارج.</li>
<li><strong>التهوية:</strong> فراغ خلف اللوح، مفتوح من الأسفل والأعلى، يخرج منه الهواء الساخن والرطوبة.</li>
<li><strong>التمدد:</strong> اللوح يتحرك مع الحرارة، فتُترك بين الألواح فواصل منتظمة، وتُثقب فتحات البراغي أوسع قليلاً من البرغي إلا نقطة ثابتة واحدة.</li>
<li><strong>التثبيت:</strong> براغٍ أو برشام ظاهر بلون اللوح، أو لصق إنشائي على الهيكل يقرره المنفّذ.</li>
<li><strong>الشمس:</strong> الواجهة الغربية والجنوبية هي الأقسى، والداكن يسخن أكثر.</li>
</ul>
<h3>التقسيم قبل الطلب</h3>
<p>ارسم الواجهة وقسّمها على مقاس اللوح قبل أن تحسب العدد، فمواضع الفواصل جزء من الشكل. اللوح 305 سم يغطي ارتفاع دور كامل بلا فاصل أفقي. والقص يحتاج منشاراً بشفرة مخصصة للمواد الصلبة. المعاينة من <a href="https://texadecore.store/install-services/">فريق التركيب</a>، والعدد نحسبه لك عند إرسال المقاسات على الواتساب.</p>
<h3>ما يُطلب معه</h3>
<p>الهيكل والبراغي غير مدرجين مع اللوح، فاسأل عنهما عند الطلب. وإن أردت جزءاً من الواجهة بمظهر الخشب المضلّع فهو في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a>.</p>
<h3>العناية</h3>
<p>ماء وصابون خفيف وقماشة. لا يحتاج دهاناً. الغبار المتراكم في الفواصل يُشطف.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>تكلفته أعلى من التكسيات الداخلية، ومعه هيكل وتنفيذ متخصص.</li>
<li>قصّه وثقبه ليسا عمل هاوٍ.</li>
<li>مظهره أملس حديث، فلا يعطي دفء الخشب المضلّع.</li>
<li>الفواصل بين الألواح ظاهرة دائماً، فهي جزء من الشكل لا شيء يُخفى.</li>
<li>الخطأ في فواصل التمدد يظهر تقوّساً.</li>
</ul>' ),
	'ex-wpc-deck' => array( 'دليل دِك WPC للأرضيات الخارجية', '<h3>ما هو دِك WPC الأرضي؟</h3>
<p>لوح أرضيات خارجية من الخشب البلاستيكي المركّب، مجوّف من الداخل وبنقش خشبي بارز على وجهه. قطاعه 146 × 23 ملم، أي عرض 14.6 سم وسماكة 2.3 سم، وطوله 290 سم، وهو بسبعة ألوان. يُستخدم لأرضيات الحدائق والأسطح وحول المسابح، ويُثبَّت على هيكل بكليبسات مخفية ويُغسل بالماء.</p>
<h3>كم لوحاً للمتر المربع؟</h3>
<p>اللوح الواحد يغطي 0.146 × 2.90 = 0.42 م² تقريباً، أي نحو 2.4 لوح لكل متر مربع قبل الهدر. جلسة 3 × 4 أمتار (12 م²) تحتاج نحو 29 لوحاً، وتُرفع إلى 31 أو 32 مع القص. الفراغات بين الألواح تنقص العدد قليلاً، فاترك الرقم النهائي لمن يرفع المقاس.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>جلسة حديقة، سطح، شرفة</td><td>مناسب</td><td>على هيكل مرفوع عن الأرض</td></tr>
<tr><td>محيط المسبح</td><td>مناسب بشرط</td><td>لون فاتح، واسأل عن خشونة السطح وهو مبلول</td></tr>
<tr><td>أرض مكشوفة لشمس الظهيرة ويُمشى عليها حافياً</td><td>بحذر</td><td>السطح يسخن، والداكن لا يُحتمل</td></tr>
<tr><td>موقف سيارة أو حمل ثقيل مركّز</td><td>لا</td><td>لوح مجوّف للمشاة</td></tr>
<tr><td>فوق تراب أو عشب مباشرة</td><td>لا</td><td>لا تصريف ولا تهوية تحته</td></tr>
</tbody>
</table>
<h3>الانحدار وتصريف الماء</h3>
<ul>
<li><strong>ميل خفيف في القاعدة</strong> باتجاه المصرف أو الحديقة، نحو 1 إلى 2 سم لكل متر، حتى لا يقف الماء تحت الدِك.</li>
<li><strong>هيكل من عوارض</strong> متعامدة على الألواح، متقاربة بما يكفي كي لا يرتخي اللوح المجوّف بينها. المسافة يحددها المصنّع وهي في الغالب بين 30 و40 سم.</li>
<li><strong>فراغ بين كل لوحين</strong> تصنعه الكليبسات، ينزل منه ماء المطر والغسيل.</li>
<li><strong>فراغ تمدد</strong> عند رؤوس الألواح وعند الجدار، فاللوح يطول في الحر.</li>
<li><strong>الأطراف المجوّفة</strong> تُغطّى بقطاع نهاية حتى لا تصير مأوى للحشرات والأتربة.</li>
</ul>
<p>التنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>العوارض والكليبسات وقطاعات الحواف: اسأل عن توفرها عند الطلب. ولجدار الجلسة ألواح WPC الجدارية بالألوان نفسها في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a>.</p>
<h3>العناية</h3>
<p>كنس وغسل بالماء والصابون. الزيت والشواء يُنظَّفان فور وقوعهما. لا دهان ولا ورنيش.</p>
<h3>عيوبه</h3>
<ul>
<li>حارّ تحت القدم صيفاً.</li>
<li>يفتح لونه قليلاً في الأشهر الأولى ثم يستقر.</li>
<li>يحتاج قاعدة مائلة وهيكلاً، فليس تركيبه لصقاً.</li>
<li>المجوّف يضعف إن تباعدت العوارض.</li>
</ul>' ),
	'ex-wpc-wall' => array( 'دليل خشب WPC الجداري الخارجي', '<h3>ما هو خشب WPC الجداري الخارجي؟</h3>
<p>ألواح طولية من الخشب البلاستيكي المركّب (WPC) مخصصة للاستخدام الخارجي: واجهات الفلل والأسوار والبرجولات وجدران الأحواش. طول اللوح 290 سم، وهو بثلاثة قطاعات:</p>
<table class="txa-family">
<thead>
<tr><th scope="col">القطاع</th><th scope="col">المقاس</th><th scope="col">شكله</th><th scope="col">ألواح لكل متر</th></tr>
</thead>
<tbody>
<tr><td>مضلع وجهين (2S)</td><td>20 × 290 سم</td><td>مضلّع من الوجهين</td><td>5</td></tr>
<tr><td>مضلع عريض (219x28Q)</td><td>20 × 290 سم، والقطاع 219 × 28 ملم</td><td>أربعة أضلاع</td><td>5</td></tr>
<tr><td>لوح ثري دي (145x19Q)</td><td>14.5 × 290 سم</td><td>مسطح بنقش خشبي بارز</td><td>نحو 7</td></tr>
</tbody>
</table>
<p>عدد الألواح لكل متر = 100 ÷ عرض اللوح بالسنتيمتر. جدار 3 أمتار يأخذ 15 لوحاً بعرض 20 سم أو 21 لوحاً بعرض 14.5 سم، ولوحاً إضافياً للقص.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الموضع</th><th scope="col">الحكم</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>سور، جدار حوش، برجولة</td><td>مناسب</td><td>الاستخدام الأول له</td></tr>
<tr><td>جزء من واجهة الفيلا</td><td>مناسب</td><td>على هيكل مثبت جيداً</td></tr>
<tr><td>مقابل واجهة زجاجية عاكسة</td><td>بحذر</td><td>الحرارة المنعكسة قد تشوّه اللوح موضعياً</td></tr>
<tr><td>أرضية جلسة أو ممر</td><td>لا</td><td>للأرض قطاع الدِك في القسم نفسه</td></tr>
<tr><td>لصق مباشر على الجدار</td><td>لا</td><td>يحتاج هيكلاً وفراغاً خلفه</td></tr>
</tbody>
</table>
<h3>الهيكل والتهوية والتمدد</h3>
<ul>
<li><strong>الهيكل:</strong> التثبيت على هيكل معدني أو خشبي بمسامير أو كليبسات مخفية. الأسلم في الخارج ألمنيوم أو حديد مجلفن، وقطاعاته متعامدة على اتجاه الألواح.</li>
<li><strong>التهوية:</strong> الفراغ الذي يصنعه الهيكل خلف الألواح يُترك مفتوحاً ليخرج الهواء الساخن.</li>
<li><strong>التمدد:</strong> اللوح يطول في الحر ويقصر في البرد. يُترك فراغ صغير عند التقاء رأسي لوحين وعند الزوايا، ولا تُشدّ البراغي شدّاً يمنع الحركة. مقدار الفراغ يُؤخذ من المصنّع.</li>
<li><strong>الشمس:</strong> اللون الداكن يسخن أكثر فيتمدد أكثر. ولون WPC عموماً يفتح قليلاً في الأشهر الأولى ثم يستقر.</li>
</ul>
<h3>أفقي أم عمودي؟</h3>
<p>الأفقي يطيل السور ويناسب الجدران المنخفضة، وتظهر فيه وصلة كل 290 سم فتُرتَّب الوصلات على خط واحد أو تُغطّى. العمودي يصرّف ماء المطر والغبار أسرع، ويغطي ارتفاع السور قطعة واحدة. والقطاع المضلّع من الوجهين ينفع حيث يُرى اللوح من الجهتين، كساتر برجولة أو سور مفتوح، أما الجدار المصمت فيكفيه وجه واحد.</p>
<h3>ما يُطلب معه</h3>
<p>الهيكل والمشابك وقطاعات النهاية والزوايا: اسأل هل هي متوفرة مع اللوح أم يؤمّنها المنفّذ. المعاينة عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والعدد نحسبه لك عند إرسال المقاسات على الواتساب، وبقية الألوان في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a>.</p>
<h3>العناية</h3>
<p>يُغسل بالماء ولا يُدهن. الأضلاع تُشطف بخرطوم بين فترة وأخرى، خاصة بعد الغبار.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يتمدد وينكمش، وسوء التركيب يظهر تقوّساً.</li>
<li>سطحه يسخن صيفاً، والداكن أشد.</li>
<li>لونه بعد سنة ليس لونه يوم التركيب تماماً.</li>
<li>يحتاج هيكلاً وفنياً يعرف نظام المشابك.</li>
</ul>
<p>للواجهة الملساء الكبيرة قارن ألواح HPL في القسم نفسه.</p>' ),
	'mb-3d' => array( 'دليل بديل الرخام الثري دي', '<h3>ما هو بديل الرخام الثري دي؟</h3>
<p>لوح جداري نقشته بارزة فعلاً لا مطبوعة: سنابل، زهور كالا، أمواج، خطوط عمودية، أشعة شمسية وغيرها. كل ألواح هذه المجموعة بمقاس 122 × 300 سم (3.66 م² للوح) ومصنوعة في السعودية. اللوح يُعامل كلوحة فنية كبيرة تُركَّب على جدار الواجهة، لا كتكسية تملأ الغرفة كلها.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">الملاحظة</th></tr>
</thead>
<tbody>
<tr><td>خلف الكنب أو السرير، صدر المدخل</td><td>مناسب</td><td>جدار يُرى من بعيد ولا يُلمس كثيراً</td></tr>
<tr><td>خلف التلفاز</td><td>بحذر</td><td>النقش الكثيف يزاحم الشاشة؛ اختر نقشة هادئة أو ضعها على الجانبين</td></tr>
<tr><td>ممر ضيق أو خلف كراسي الطعام</td><td>غير مفضّل</td><td>البروز يتعرض للاحتكاك والطَّرق</td></tr>
<tr><td>مطبخ قرب الطبخ</td><td>غير مفضّل</td><td>بخار الدهون يستقر في تجاويف النقش</td></tr>
<tr><td>حمام، خارج البيت، أرضيات</td><td>لا أو اسأل</td><td>للجدران الداخلية؛ يُمسح ويتحمل الرطوبة العادية</td></tr>
</tbody>
</table>
<h3>البروز والإضاءة والتكرار</h3>
<ul>
<li><strong>الإضاءة الجانبية تصنع النقش.</strong> ضوء يمسح الجدار من الأعلى أو من الجنب يرسم ظلالاً تُبرز العمق، أما الضوء الأمامي المباشر فيسطّحه.</li>
<li><strong>لوح واحد أم أكثر؟</strong> أغلب التصاميم رسمة مكتملة في لوح واحد. لجدار أعرض من 122 سم إمّا أن تكرر اللوح نفسه، أو تضعه في الوسط وتحيطه بألواح سادة أو لامعة من اللون نفسه، وهذا أهدأ وأوفر.</li>
<li><strong>القص يأكل من الرسمة.</strong> إن كان سقفك أقل من 3 أمتار فسيُقص من اللوح؛ اسأل من أي طرف يُقص حتى لا تضيع قمة النقشة.</li>
<li><strong>الأفياش</strong> يُفضَّل نقلها خارج مساحة النقش، فالقص وسط البروز صعب الإخفاء.</li>
</ul>
<h3>التركيب: ماذا يحتاج الجدار؟</h3>
<p>سطح مستوٍ وجاف، ولاصق يوزَّع بسخاء لأن اللوح البارز أثقل من اللوح الأملس، مع سند مؤقت حتى يمسك. يُضبط اللوح الأول بميزان الماء، وتُحمل الألواح واقفة لا مسطّحة حتى لا تنثني، ولا يُضغط على قمم النقش عند التثبيت بل على المساحات المستوية بينها. رفع المقاس عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والعدد من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>ما يُطلب معه</h3>
<p>ألواح سادة مرافقة من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/">قسم بديل الرخام</a>، فاصل معدني بين اللوح البارز وجاره، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. بقية النقشات في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d8%ab%d8%b1%d9%8a-%d8%af%d9%8a/">قسم الثري دي</a>.</p>
<h3>تنظيف النقش البارز</h3>
<p>الغبار يتجمع في التجاويف، فالتنظيف هنا خطوتان: فرشاة ناعمة أو مكنسة بفوهة فرشاة أولاً، ثم قماشة رطبة. لا تُرش المنظفات مباشرة داخل النقش حتى لا تجف فيه وتترك أثراً.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>تنظيفه أكثر جهداً من اللوح الأملس.</li>
<li>لا يُكرَّر على كل الجدران دون أن يزدحم المكان.</li>
<li>صعب القص حول الفتحات.</li>
<li>عمق البروز يختلف بين التصاميم، فاسأل عنه إن كان خلف باب يُفتح عليه.</li>
<li>يتأثر بالحرارة العالية المباشرة مثل بقية ألواح الفئة.</li>
</ul>
<p>راجع <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">مقال عيوب بديل الرخام</a> للصورة الكاملة.</p>' ),
	'mb-concrete' => array( 'دليل بديل الرخام الكونكريت', '<h3>ما هو بديل الرخام الكونكريت؟</h3>
<p>لوح PVC جداري بوجه يحاكي الخرسانة المصبوبة: درجات رمادية وبيج ورملية، مع تموجات هادئة بدل عروق الرخام الصريحة. المقاس الأشيع في هذه المجموعة 120 × 290 سم، أي 3.48 م² للوح، ومنشأ أغلبها الصين. السماكة مذكورة في جزء من المنتجات فقط وهي 5 ملم، فراجع مواصفات التصميم الذي تختاره. تنبيه: بعض ألواح هذا القسم لامعة السطح رغم وجودها تحت اسم الكونكريت، فانظر إلى صورة المنتج واسمه.</p>
<h3>الطابع الصناعي: كيف تستخدمه بلا برودة؟</h3>
<p>الرمادي الإسمنتي جميل لكنه يبرّد الغرفة إن غطّى كل جدرانها. القاعدة المجرّبة: جدار واحد أو جداران بالكونكريت، وتدفئة الباقي بخشب أو قماش أو إضاءة صفراء دافئة (نحو 3000 كلفن). الدرجات الرملية والبيج أسهل في المجالس العائلية، والرمادي الغامق يليق بالمكاتب والمقاهي والمحلات. ولأن نقشته بلا عروق متجهة، فخطوط التقاء الألواح أقل لفتاً للنظر من الرخام المعرّق.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>مكتب، مقهى، محل، خلفية تلفاز، ممر داخلي</td><td>مناسب</td><td>نقشة هادئة لا تُظهر البصمات بسهولة</td></tr>
<tr><td>غرفة صغيرة قليلة الضوء</td><td>بحذر</td><td>الرمادي الداكن يضيّقها؛ اختر درجة فاتحة</td></tr>
<tr><td>جدران المطبخ والحمام البعيدة عن الماء المباشر</td><td>مناسب بحذر</td><td>يُمسح ويتحمل الرطوبة العادية</td></tr>
<tr><td>كابينة الدش</td><td>اسأل قبل الطلب</td><td>لم تُختبر الفواصل تحت ماء دائم</td></tr>
<tr><td>واجهة خارجية، أرضية، سطح طاولة</td><td>لا</td><td>مخصص للجدران الداخلية فقط</td></tr>
</tbody>
</table>
<h3>التركيب</h3>
<ul>
<li>يُلصق على جدار جاف مستوٍ بلاصق مرن مناسب للألواح البلاستيكية؛ الإسمنت والغراء الأبيض لا يمسكان ظهره.</li>
<li>اللوح طوله 290 سم، فإن زاد ارتفاع جدارك عن ذلك فخطّط لشريط علوي أو كرنيش يغطي الفرق.</li>
<li>للحصول على مظهر «بلاطات خرسانية» يقسّم بعض المصممين الجدار بفواصل أفقية ورأسية رفيعة؛ حدّد ذلك قبل القص.</li>
<li>أبعده عن الموقد والمدفأة، فالحرارة القريبة تقوّسه.</li>
<li>ألواح الجدار الواحد تُطلب معاً، فدرجة الرمادي قد تتفاوت قليلاً بين دفعة وأخرى.</li>
</ul>
<p>المقاس والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، وعدد الألواح من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>ما يُطلب معه</h3>
<p>فواصل معدنية رفيعة (الأسود والفضي أقرب للطابع الصناعي)، قفلة للطرف المكشوف، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">قسم النعلات</a>. بقية الدرجات في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d9%83%d9%88%d9%86%d9%83%d8%b1%d9%8a%d8%aa/">قسم بديل الرخام الكونكريت</a>.</p>
<h3>العناية</h3>
<p>مسحة بقماش ناعم رطب تكفي. بقع الدهون تُزال بصابون سائل مخفف، ولا تُستعمل الإسفنجة الخشنة حتى لا تلمع بقعة من السطح المطفي دون غيرها.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>شكل خرسانة لا ملمسها: السطح أملس عند اللمس.</li>
<li>الدرجات الداكنة تُعتم المساحات الصغيرة.</li>
<li>يتبع الجدار، فالتموج الواضح يُسوّى قبله.</li>
<li>يتأثر بالحرارة المباشرة العالية.</li>
</ul>
<p>من يريد خرسانة حقيقية بمسامّها فهذا ليس بديلاً عنها. اقرأ <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام ومتى لا يناسبك</a> قبل القرار.</p>' ),
	'mb-fabric' => array( 'دليل بديل الرخام القماشي (ليزر)', '<h3>ما هو بديل الرخام القماشي (الليزر)؟</h3>
<p>لوح PVC بسماكة 3 ملم ومقاس 122 × 290 سم، يغطي 3.54 م². وجهه يحمل عروق الرخام، لكن سطحه مطفي بملمس نسيج ناعم يسمّى «تشطيب ليزر». النتيجة رخام بلا لمعة: أبيض بعروق رمادية، أسود بعروق بيضاء، كريمي، وترافرتين بيج مخطط.</p>
<h3>لمن هذا السطح؟</h3>
<p>لمن يحب عروق الرخام ويكره انعكاس الضوء. غرفة النوم مثال واضح: أباجورة بجانب السرير تنعكس على اللوح اللامع وتزعج العين، ولا تنعكس على القماشي. كذلك الجدار المقابل للشاشة، فلا يظهر عليه خيال الصورة. والتصميم الأسود هنا أسهل عيشاً من الأسود اللامع لأنه لا يفضح البصمات.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
