<h3>اللمعة والإضاءة: ثلاث ملاحظات قبل الاختيار</h3>
<ul>
<li><strong>السبوت لايت القريب من الجدار</strong> يرسم على اللوح بقع ضوء ويكشف أي تموج تحته. الإضاءة المخفية أو البعيدة عن الجدار أرحم باللمعة.</li>
<li><strong>الألوان الداكنة اللامعة</strong> (الأسود والكحلي) تُظهر بصمات الأصابع والغبار أكثر من البيج والرمادي الفاتح.</li>
<li><strong>العروق لا تتصل بين لوح وآخر</strong> إلا في تصاميم الأوبن بوك، فاطلب ألواح الجدار الواحد دفعة واحدة ورتّبها على الأرض قبل اللصق لتختار أجمل تجاور.</li>
</ul>
<h3>التركيب: ماذا يحتاج جدارك؟</h3>
<p>جدار مستوٍ وجاف ودهانه متماسك؛ فلوح بسماكة 3 ملم لا يخفي نتوءاً ولا انتفاخاً. يُثبَّت بلاصق مرن يوزَّع على ظهره، وتُقص فتحات الأفياش قبل اللصق. الغشاء الشفاف الواقي يُنزع بعد انتهاء التركيب لا قبله حتى لا ينخدش الوجه أثناء القص. تُترك مسافة عن الموقد أو يوضع حاجز زجاجي. العدد تحسبه <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما الذي يُطلب معه؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القطعة</th><th scope="col">وظيفتها</th></tr>
</thead>
<tbody>
<tr><td>شريحة فاصل معدنية</td><td>تغطي خط التقاء لوحين وتحوّله إلى تفصيل مقصود</td></tr>
<tr><td>زاوية أو قفلة طرف</td><td>تحمي الحافة المكشوفة عند نهاية الجدار وحول العمود</td></tr>
<tr><td>نعلة</td><td>تستر التقاء اللوح بالأرضية</td></tr>
</tbody>
</table>
<p>اسأل الفريق عن الفاصل المناسب لسماكة اللوح قبل الطلب، وتصفّح <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">قسم النعلات</a> وبقية تصاميم <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d9%84%d8%a7%d9%85%d8%b9/">بديل الرخام اللامع</a>.</p>
<h3>العناية والتنظيف</h3>
<p>قطعة مايكروفايبر مبللة بماء وصابون سائل، ثم تجفيف فوري حتى لا تبقى خطوط على اللمعة. لا سلك ولا بودرة كاشطة ولا أسيتون أو كلور مركّز.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يكشف عيوب الجدار والخدوش الدقيقة أكثر من الأسطح المطفية.</li>
<li>يلين إذا لاصق مصدر حرارة عالية.</li>
<li>خطوط الالتقاء تبقى ظاهرة ما لم تُغطَّ بفاصل.</li>
<li>لا يعطي برودة الرخام الطبيعي ولا عمقه عند اللمس.</li>
</ul>
<p>إن كان جدارك متموجاً أو كثير الوهج فالسطح المطفي أهدأ. التفاصيل في <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">مقالنا عن عيوب بديل الرخام</a>.</p>' ),
	'mb-openbook' => array( 'دليل بديل الرخام الأوبن بوك', '<h3>ما هو الأوبن بوك؟</h3>
<p>لوحان من بديل الرخام طُبعت عروقهما متعاكسة، فإذا تجاورا صار خط التقائهما محور تناظر كصفحتي كتاب مفتوح. الأبعاد 290 × 244 سم «قطعتان»، أي لوحين كل منهما 122 × 290 سم، بسماكة 3 ملم ومنشأ صيني. ألوانها رمادية مدرّجة وسموكي وأخضر داكن ومعدني.</p>
<h3>قواعد التناظر الأربع</h3>
<ul>
<li><strong>العدد زوجي دائماً.</strong> لوحان، أربعة، ستة. اللوح المفرد يكسر الفكرة كلها.</li>
<li><strong>خط الوسط هو البطل.</strong> ضعه على محور الشاشة أو السرير أو الكنبة، لا حيث ينتهي الجدار.</li>
<li><strong>القص من الأطراف الخارجية وبالتساوي.</strong> لجدار عرضه 220 سم يُقص 12 سم من كل جهة، ولا يُمس خط الوسط أبداً.</li>
<li><strong>يمين ويسار لا يتبادلان.</strong> علّم ظهر كل لوح قبل رفعه، وجرّب الزوج على الأرض.</li>
</ul>
<h3>كم زوجاً أحتاج؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">عرض الجدار</th><th scope="col">الحل</th></tr>
</thead>
<tbody>
<tr><td>حتى 244 سم</td><td>زوج واحد</td></tr>
<tr><td>245 إلى 370 سم</td><td>زوج في الوسط وشريط سادة أو فاصل عريض على كل جانب</td></tr>
<tr><td>نحو 488 سم</td><td>زوجان، فيتكوّن محور ثانٍ بينهما؛ وزّع الأثاث على هذا الأساس</td></tr>
</tbody>
</table>
<p>والارتفاع 290 سم، فما زاد يُكمَّل بكرنيش أو شريط علوي.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<p>يصلح لجدار واحد نظيف بلا نوافذ: خلف التلفاز، صدر المجلس، خلف السرير. لا يصلح لجدار تقطعه فتحة مكيف أو باب في منتصفه، لأن الفتحة تأكل التناظر. وهو للجدران الداخلية فقط؛ يُمسح ويتحمل الرطوبة العادية، وداخل كابينة الدش اسأل قبل الطلب. لا للأرضيات ولا للخارج.</p>
<h3>التركيب</h3>
<p>الجدار مستوٍ وجاف. يُرسم خط شاقولي عند المحور، ويُلصق اللوح الأول على حدّه تماماً ثم الثاني ملاصقاً له، وتُراجع استمرارية العروق عند الوسط قبل أن يمسك اللاصق. لا يُغطى خط الوسط بفاصل عريض حتى لا يحجب التقاء العروق. نفّذه مع <a href="https://texadecore.store/install-services/">فريق التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>قفلتان للطرفين، نعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، وألواح سادة للجانبين من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/">بديل الرخام</a> إن كان الجدار أعرض. التصاميم في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d8%a7%d9%88%d8%a8%d9%86-%d8%a8%d9%88%d9%83/">قسم الأوبن بوك</a>، واحسب المرافق في <a href="https://texadecore.store/quantity-calculator/">الحاسبة</a>.</p>
<h3>العناية</h3>
<p>قماش ناعم رطب ثم تجفيف، بلا مواد كاشطة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يُهدر أكثر عند القص لأن القص من الجهتين.</li>
<li>تلف لوح واحد يعني استبدال الزوج غالباً.</li>
<li>لا يحتمل جداراً مزدحماً بالفتحات.</li>
<li>تأكد هل السعر للّوح أم للزوج قبل الطلب.</li>
</ul>
<p>المزيد في <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام</a>.</p>' ),
	'mb-print' => array( 'دليل بديل الرخام المطبوع (اللوحات)', '<h3>ما هو بديل الرخام المطبوع؟</h3>
<p>لوح PVC لامع بسماكة 3 ملم طُبعت عليه لوحة كاملة بدل عروق الرخام: خيل، جلسة عربية، نقوش أندلسية، أشجار، ريش. منشأ ألواح هذه المجموعة الصين، ومقاسها 122 × 300 سم «قطعة واحدة». هو إذن جدارية جاهزة تُلصق، والفكرة فيه غير فكرة تكسية الجدار بلون واحد.</p>
<h3>اللوحة قبل الجدار: كيف تختار؟</h3>
<ul>
<li><strong>قِس الجزء الظاهر لا الجدار كله.</strong> الكنبة أو السرير أو طاولة المدخل تحجب السبعين سنتيمتراً السفلى تقريباً؛ تأكد أن عنصر الرسمة الرئيسي (رأس الخيل مثلاً) فوق هذا الخط.</li>
<li><strong>ارتفاع السقف.</strong> اللوح 300 سم، وأي قص يذهب بجزء من الصورة. اطلب أن يكون القص من الطرف الأقل أهمية في الرسمة.</li>
<li><strong>لوحة واحدة تكفي الغرفة.</strong> لوحتان مطبوعتان في مجال نظر واحد تتزاحمان. أكمل بقية الجدار بألواح سادة أو كونكريت من لون خلفية الرسمة.</li>
<li><strong>اتجاه الرسمة.</strong> بعض اللوحات عمودية بطبيعتها ولا تُدار أفقياً.</li>
</ul>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>صدر المجلس، المدخل، جدار نهاية الممر</td><td>مناسب</td><td>مساحة تُرى من بعيد فتظهر الرسمة كاملة</td></tr>
<tr><td>غرفة صغيرة جداً</td><td>بحذر</td><td>الرسمة الكبيرة تحتاج مسافة نظر</td></tr>
<tr><td>جدار عليه مكيف أو نافذة أو أفياش كثيرة</td><td>غير مفضّل</td><td>كل فتحة تقطع الصورة</td></tr>
<tr><td>المطبخ والحمام</td><td>اسأل قبل الطلب</td><td>يُمسح ويتحمل الرطوبة العادية، لكن مكان اللوحة الطبيعي غرف الاستقبال</td></tr>
<tr><td>الخارج والأرضيات</td><td>لا</td><td>للجدران الداخلية فقط</td></tr>
</tbody>
</table>
<h3>التركيب</h3>
<p>الجدار يُجهَّز مستوياً وجافاً، ثم يُحدَّد محور اللوحة بالقلم قبل وضع اللاصق: مركزها على مركز الكنبة أو السرير لا على مركز الجدار إن اختلفا. تُلصق بلاصق مرن ويُضغط عليها بقطعة قماش من الوسط إلى الأطراف. وإن كانت اللوحة من أكثر من قطعة فجرّب تطابق الرسمة على الأرض أولاً. يساعدك في ذلك فريق <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>إطار من فواصل معدنية أو بانوهات يحوّل اللوح إلى لوحة مؤطّرة، وألواح سادة للجانبين من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/">بديل الرخام</a>، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">قسم النعلات</a>. كل اللوحات في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d8%b7%d8%a8%d8%a7%d8%b9%d9%87/">قسم بديل الرخام طباعة</a>، وعدد الألواح المرافقة تحسبه <a href="https://texadecore.store/quantity-calculator/">الحاسبة</a>.</p>
<h3>العناية</h3>
<p>تُمسح بقماش ناعم رطب بحركة خفيفة. تجنّب المذيبات والكحول المركّز فهي تبهت الطباعة، ولا تلصق عليها شريطاً لاصقاً قوياً. وإن أضأتها بسبوت فاجعله مائلاً من الأعلى حتى لا يقع وهجه وسط الصورة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>ذوق شخصي واضح: قد تملّ الرسمة، ونزع اللوح يتلفه ويقشّر الدهان تحته.</li>
<li>الخدش في وسط الصورة لا يُرمَّم.</li>
<li>لا يُجزَّأ على جدران متفرقة.</li>
<li>يلين قرب الحرارة العالية، ولا يوضع تحت شمس مباشرة طويلة.</li>
</ul>
<p>إن كنت تغيّر ديكورك كثيراً فاللوح السادة أسلم. المزيد في <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام</a>.</p>' ),
	'mb-resin' => array( 'دليل بديل الرخام الريزن', '<h3>ما هو بديل الرخام الريزن؟</h3>
