<p>اقرأ <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام</a> قبل أن تقرر.</p>' ),
	'mb-stone' => array( 'دليل بديل الرخام الحجري', '<h3>ما هو بديل الرخام الحجري؟</h3>
<p>لوح PVC مطفي السطح، مطبوع ومحبَّب ليحاكي الحجر الطبيعي بدل الرخام المصقول: درجات بيج ورمادي وكريمي، بين «ناعم» و«صخري» و«مخطط» كما في أسماء التصاميم. كل ألواح المجموعة بمقاس 120 × 290 سم، واللوح يغطي 3.48 م². اسأل عن السماكة قبل الطلب إن كان جدارك غير مثالي.</p>
<h3>لماذا تختاره بدل اللامع؟</h3>
<p>السطح المطفي لا يعكس السبوت لايت ولا النافذة، فيصلح للجدار الذي فشل معه اللامع بسبب الوهج. وملمسه المحبَّب يخفي بصمات الأصابع والخدوش الخفيفة. في المقابل هو أهدأ حضوراً: لا يعطي «لمعة الفخامة»، ويحتاج إضاءة جيدة حتى لا يبدو باهتاً في الغرف المعتمة. التصاميم الصخرية تليق بالمداخل وواجهات الاستقبال، والناعمة بغرف النوم والمعيشة. وإن احترت بين درجتين فاطلب صورة حقيقية للّوح في ضوء النهار، فالسطح المطفي يتبدل مظهره بين الإضاءة البيضاء والصفراء.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">الملاحظة</th></tr>
</thead>
<tbody>
<tr><td>المجلس، غرفة المعيشة، المدخل، واجهة استقبال</td><td>مناسب</td><td>مظهر حجري دافئ بلا وهج</td></tr>
<tr><td>ممر كثير الحركة</td><td>مناسب</td><td>الملمس يستر آثار اللمس اليومي</td></tr>
<tr><td>عمود داخلي</td><td>مناسب</td><td>يُقص ويُلف على أضلاع العمود المربع مع زاوية عند كل ركن</td></tr>
<tr><td>مطبخ وحمام بلا ماء مباشر</td><td>مناسب بحذر</td><td>يُمسح ويتحمل الرطوبة العادية</td></tr>
<tr><td>كابينة الدش</td><td>اسأل قبل الطلب</td><td>ماء مباشر مستمر</td></tr>
<tr><td>واجهة البيت الخارجية والأرضية</td><td>لا</td><td>شكله حجري لكنه لوح داخلي</td></tr>
</tbody>
</table>
<h3>التركيب</h3>
<ul>
<li>جدار جاف مستوٍ ودهان غير متقشر، ولاصق مرن يوزَّع خطوطاً على الظهر.</li>
<li>الارتفاع المغطّى 290 سم قطعة واحدة؛ ما زاد يُكمَّل بشريط علوي.</li>
<li>رتّب التصاميم الصخرية بحيث لا تتجاور البقعة نفسها في لوحين متتاليين؛ اقلب اتجاه لوح أو بدّل ترتيبه.</li>
<li>تُفتح أماكن الأفياش قبل اللصق.</li>
<li>الدرجات الفاتحة كالأبيض الثلجي والكريمي تُظهر خط الالتقاء أكثر من الصخري الداكن، وهناك يفيد الفاصل.</li>
</ul>
<p>العدد من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتنفيذ من <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القطعة</th><th scope="col">متى تحتاجها؟</th></tr>
</thead>
<tbody>
<tr><td>فاصل بين لوحين</td><td>دائماً إن أردت خطاً نظيفاً بدل شعرة الالتقاء</td></tr>
<tr><td>زاوية خارجية</td><td>عند أركان الأعمدة ونهاية الجدار البارز</td></tr>
<tr><td>نعلة</td><td>عند الأرضية، من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">قسم النعلات</a></td></tr>
</tbody>
</table>
<p>بقية الدرجات في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d8%ad%d8%ac%d8%b1%d9%8a/">بديل الرخام الحجري</a>.</p>
<h3>العناية</h3>
<p>الملمس المحبَّب يمسك الغبار الناعم أكثر من الأملس: نفضة بقماش جاف أسبوعياً، ومسحة رطبة عند الحاجة باتجاه واحد. لا شمع ولا ملمّعات، فهي تترك بقعاً لامعة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>شكل حجر لا بروز حجر: السطح شبه مستوٍ، ومن يريد نتوءاً حقيقياً فأمامه <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ad%d8%ac%d8%b1/">ألواح بديل الحجر</a>.</li>
<li>أقل إشراقاً من اللامع في الغرف قليلة الضوء.</li>
<li>لا يُركَّب خارج البيت مهما بدا حجرياً.</li>
<li>يتقوّس قرب الحرارة العالية.</li>
</ul>
<p>وللمقارنة الصريحة اقرأ <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام</a>.</p>' ),
	'mb-veneer' => array( 'دليل بديل الرخام قشرة الشيبورد (HPL)', '<h3>ما هو بديل الرخام قشرة الشيبورد؟</h3>
<p>قشرة HPL: وجه ديكوري رقيق وصلب، يُصنع عادةً من طبقات ورق مشبّعة بالراتنج تُكبس بالحرارة. تصاميم هذه المجموعة خشبية وقماشية (بيج، رمادي، أوف وايت، خشبي هرمي) لا رخامية، وإن كانت مدرجة تحت بديل الرخام. تُباع باللوح، واطلب المقاس والسماكة قبل الشراء.</p>
<h3>بماذا تختلف عن لوح PVC؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">وجه المقارنة</th><th scope="col">قشرة HPL</th><th scope="col">لوح PVC العادي</th></tr>
</thead>
<tbody>
<tr><td>الصلابة ومقاومة الخدش</td><td>وجه أقسى</td><td>ألين وينخدش أسهل</td></tr>
<tr><td>المرونة</td><td>قليلة؛ تتشقق إن ثُنيت بحدّة</td><td>أكثر تسامحاً</td></tr>
<tr><td>القص</td><td>يحتاج أداة حادة وحافة تُصنفَر</td><td>يُقص بسهولة</td></tr>
<tr><td>الحواف</td><td>ظاهرة داكنة تحتاج قفلة</td><td>أقل وضوحاً</td></tr>
</tbody>
</table>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>جدران المجالس والمطاعم والكافيهات</td><td>مناسب</td><td>سطح يتحمل اللمس والمسح المتكرر</td></tr>
<tr><td>جدار المطبخ والمغاسل</td><td>مناسب بحذر</td><td>أبعدها عن الشعلة المباشرة واسأل عن حدّها</td></tr>
<tr><td>داخل كابينة الدش</td><td>اسأل قبل الطلب</td><td>خط الالتقاء والحواف نقطة الضعف لا الوجه</td></tr>
<tr><td>الخارج والأرضيات</td><td>لا</td><td>للجدران الداخلية فقط</td></tr>
</tbody>
</table>
<h3>التركيب: الحواف أولاً</h3>
<p>القشرة تُلصق على جدار مستوٍ تماماً وجاف، ويُفرد اللاصق على كامل الظهر لا نقاطاً، لأن أي فراغ خلف وجه صلب رقيق يُسمع طرقه ويُرى. تُترك شعرة تمدد عند الأطراف، وتُغطى كل حافة مكشوفة بقفلة أو زاوية. الهرمي يُركَّب باتجاه النقشة الصحيح، فرتّب الألواح قبل اللصق. الأفضل أن ينفذها فني متمرس عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معها</h3>
<p>قفلات للحواف، زوايا خارجية، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. التصاميم في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85-%d9%82%d8%b4%d8%b1%d8%a9-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">قسم قشرة الشيبورد</a>، والعدد يُحسب بعد معرفة مقاس اللوح في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>العناية</h3>
<p>قماش رطب وصابون سائل. السطح يتحمل المسح المتكرر، لكن السلك المعدني والمساحيق الكاشطة تخدش لمعته. جفّف خط الالتقاء والحواف بعد المسح.</p>
<h3>عيوبها ومتى لا تناسبك</h3>
<ul>
<li>المقاس والسماكة يُؤكَّدان من الفريق قبل الطلب.</li>
<li>لا تسامح الجدار المتموج ولا القص المرتجل.</li>
<li>حافتها تنكسر بالصدمة إن بقيت بلا قفلة.</li>
<li>ليست رخامية الشكل، فلا تطلبها إن كنت تبحث عن عروق الرخام.</li>
</ul>
<p>للصورة الكاملة عن الفئة: <a href="https://texadecore.store/2026/11/21/marble-alternative-disadvantages/">عيوب بديل الرخام</a>.</p>' ),
	'mo-capital' => array( 'دليل تيجان الأبواب والأعمدة', '<h3>ما هي تيجان الفوم؟</h3>
<p>التاج قطعة أفقية بارزة تعلو شيئاً فتُنهيه: فتحة باب، أو نافذة، أو رأس عمود جداري. تيجان هذه المجموعة بيضاء من الفوم، خفيفة وتُركَّب بالغراء. وهي صنفان يختلف استعمالهما:</p>
<table class="txa-family">
<thead>
<tr><th scope="col">الصنف</th><th scope="col">المقاسات المذكورة (عرض × ارتفاع)</th><th scope="col">موضعه</th></tr>
</thead>
<tbody>
<tr><td>تاج باب، سادة أو منقوش</td><td>126 × 20 سم، 108 × 21 سم، 93.5 × 25 سم</td><td>فوق فتحة الباب أو النافذة</td></tr>
<tr><td>تاج صغير</td><td>20 × 8، 24.5 × 6، 30 × 8، 30 × 10 سم</td><td>رأس عمود جداري مسطح، أو تحت طرف رف أو قوس</td></tr>
</tbody>
</table>
<h3>مطابقة تاج الباب للفتحة</h3>
<p>قِس عرض الفتحة مع إطارها الخشبي من طرفه إلى طرفه، فالتاج يجلس فوق الإطار ويبرز عنه قليلاً من الجانبين أو يساويه. باب مع إطاره 100 سم يناسبه تاج 108 سم، والباب الأعرض يناسبه 126 سم. التاج الأقصر من الإطار يبدو خطأً لا يُصلَح. ثم قِس المسافة بين أعلى الإطار والسقف أو الكرنيش: يجب أن تزيد على ارتفاع التاج بشبر على الأقل، وإلا انحشر. والتاج لا يُطال إن قصر، لكنه يُقص من طرفيه بالتساوي إن كان سادة، أما المنقوش فقصّه يقطع النقش.</p>
<h3>مطابقة التاج الصغير للعمود</h3>
<p>عرض التاج يساوي عرض العمود الجداري أو يزيد عنه قليلاً. والعمود هنا عود مسطح أو مداد مثبت على الجدار، لا عمود إنشائي: التاج لا يحمل شيئاً. يُشترى بعدد الأعمدة، ويُراعى أن يكون ارتفاعه متناسباً مع الكرنيش الذي فوقه.</p>
<h3>التركيب</h3>
<ul>
<li>خط أفقي بالميزان فوق الإطار، فالعين تلتقط ميلان التاج فوراً لأنه يجاور خط الباب.</li>
<li>لاصق تركيب يلائم الفوم على جدار مدهون وجاف، وسند مؤقت حتى يجف.</li>
<li>الفراغ بين التاج والإطار وبينه وبين الجدار يُملأ بمعجون قابل للدهان.</li>
<li>دهان مائي بلون الإطار أو بلون البانوهات. ما دام نوع الفوم غير محدد فتجنّب أي دهان فيه مذيبات.</li>
</ul>
<p>التنفيذ مع بقية أعمال الجدار عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>أين يصلح وأين لا؟</h3>
<p>يصلح فوق الأبواب الداخلية ومداخل المجالس وعلى الأعمدة الجدارية. اعتبره للداخل، فتركيبه على باب خارجي مكشوف يحتاج تأكيداً من الفريق. ولا يوضع حيث يصدمه باب يُفتح نحوه.</p>
<h3>ما يُطلب معه</h3>
<p>مدادات مسطحة من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a> تنزل على جانبي الباب فتكمل الإطار، وكرنيش من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%85%d8%af%d8%a9-%d9%88%d9%83%d8%b1%d8%a7%d9%86%d9%8a%d8%b4/">الأعمدة والكرانيش</a> بالطراز نفسه.</p>
<h3>عيوبه</h3>
<ul>
<li>ثمانية موديلات فقط بمقاسات ثابتة، فقد لا تجد ما يطابق بابك.</li>
<li>اسأل عن نوع الفوم.</li>
<li>زينة خالصة لا وظيفة لها، وتناسب الطراز الكلاسيكي دون غيره.</li>
</ul>' ),
	'mo-ceil-corner' => array( 'دليل زوايا بانوهات السقف', '<h3>ما هي أطقم زوايا بانوهات الأسقف؟</h3>
<p>قطع زاوية من فوم البولي يوريثان (PU) مخصصة لإطار يُرسم على السقف لا على الجدار: مستطيل من الأعواد حول الثريا أو على محيط السقف، وأركانه هذه القطع. مقاساتها في المجموعة من 13 × 13 سم إلى 35 × 35 سم، وموديل كبير 42 × 46.2 سم. تُسمّى «طقماً»، فاسأل عن عدد القطع فيه: هل هو أربع زوايا تكفي إطاراً كاملاً أم أقل؟</p>
<h3>لماذا يختلف السقف عن الجدار؟</h3>
<ul>
<li><strong>يُرى من بعيد ومن الأسفل،</strong> فالزاوية التي تبدو كبيرة في يدك تصغر على سقف ارتفاعه 3 أمتار. اختر مقاساً أكبر مما تختاره للجدار.</li>
<li><strong>الإضاءة تكشفه.</strong> ضوء الثريا والسبوت يمرّ بمحاذاة السقف فيُظهر كل وصلة غير معجونة.</li>
<li><strong>الجاذبية ضدك.</strong> اللاصق يحتاج سنداً حتى يجف.</li>
</ul>
<h3>اختيار المقاس</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الإطار على السقف</th><th scope="col">مقاس الزاوية المقترح</th></tr>
</thead>
<tbody>
<tr><td>إطار صغير حول ثريا، ضلعه أقل من 1.5 م</td><td>13 إلى 18 سم</td></tr>
<tr><td>إطار متوسط في غرفة نوم</td><td>18 إلى 25 سم</td></tr>
<tr><td>إطار محيطي في مجلس أو صالة</td><td>25 إلى 35 سم</td></tr>
<tr><td>سقف عالٍ أو صالة واسعة جداً</td><td>الموديل 42 × 46.2 سم</td></tr>
</tbody>
</table>
<p>هذه نسب للاستئناس، وضابطها ألا تأخذ الزاويتان أكثر من ثلث الضلع الذي تقعان عليه.</p>
<h3>التخطيط والتركيب</h3>
<p>ابدأ من مركز السقف، وهو في الغالب نقطة الثريا، وارسم الإطار متناظراً حولها بخيط مشدود، ثم تحقق من أن ضلعيه يوازيان الجدران. تُلصق الزوايا أولاً ثم تُقص الأعواد بينها. السقف يجب أن يكون مدهوناً وجافاً، وسقف الجبس المعلّق يقبل اللصق ما دام سطحه سليماً. تُسند كل قطعة بشريط ورقي أو مسمار رفيع مؤقت حتى يتماسك اللاصق. العمل فوق الرأس على سلّم متعب ويحتاج شخصين، ولذلك يطلبه أكثر الناس من <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>الدهان</h3>
<p>معجون للوصلات، ثم دهان مائي مطفي بلون السقف. اللمعة على السقف تُبرز العيوب.</p>
<h3>أين لا تصلح؟</h3>
<p>لا تصلح لسقف منخفض عن 2.6 م، ففيه يزيد الإطار الإحساس بالانخفاض. ولا لسقف فيه فتحات تكييف وسبوتات كثيرة تقطع خط الإطار، ولا لسقف رطب يتقشر دهانه.</p>
<h3>ما يُطلب معها</h3>
<p>أعواد من قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a> بنقش يوافقها، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%85%d8%af%d8%a9-%d9%88%d9%83%d8%b1%d8%a7%d9%86%d9%8a%d8%b4/">كرنيش</a> على محيط السقف إن أردت طرازاً كاملاً. وبقية الأطقم في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b7%d9%82%d9%85-%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a7%d9%84%d8%a3%d8%b3%d9%82%d9%81/">أطقم زوايا الأسقف</a>.</p>
<h3>عيوبها</h3>
<ul>
<li>عدد القطع في الطقم يُسأل عنه قبل الطلب.</li>
<li>تركيبها أصعب من زوايا الجدار.</li>
<li>تنظيفها يحتاج سلّماً.</li>
<li>تثبّت موضع الثريا، فنقلها لاحقاً يُفسد التناظر.</li>
</ul>' ),
	'mo-corner' => array( 'دليل زوايا البانوهات', '<h3>ما هي زوايا البانوهات؟</h3>
<p>قطع جاهزة تُركَّب في أركان إطار البانوه فتغنيك عن قصّ الأعواد بزاوية 45° وتعطي الركن شكلاً منحنياً أو مزخرفاً. أغلب المجموعة زوايا مزخرفة من فوم PU، مربعة في الغالب، من 15 × 15 سم إلى 25 × 25 سم وأكثرها 23 × 23 سم، ومعها زوايا منقوشة أكبر مثل 29 × 50 سم. وفي المجموعة صنف مختلف تماماً: «زاوية فايبر» بعرض 3 أو 5 سم وطول 240 سم، وهذه ليست لركن إطار، بل قطاع طولي يحمي حافة الجدار البارزة.</p>
<h3>الزاوية الجاهزة أم القصّ 45°؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المقارنة</th><th scope="col">زاوية جاهزة</th><th scope="col">قصّ 45°</th></tr>
</thead>
<tbody>
<tr><td>الشكل</td><td>ركن منحنٍ أو منقوش، كلاسيكي</td><td>ركن حادّ بسيط، حديث</td></tr>
<tr><td>التنفيذ</td><td>قصّ مستقيم للعود فقط</td><td>صندوق قصّ ودقة في كل ركن</td></tr>
<tr><td>التكلفة</td><td>أربع قطع إضافية لكل إطار</td><td>لا قطع إضافية</td></tr>
<tr><td>الخطأ</td><td>عدم تطابق النقش مع العود</td><td>فراغ في الركن يُعالَج بالمعجون</td></tr>
</tbody>
</table>
<h3>المطابقة: أهم ما في الاختيار</h3>
<ul>
<li><strong>الموديل.</strong> الزاوية تُصنع لتكمل عوداً بعينه. اسأل برمز العود عن الزاوية التي توافقه، فعرض البروز وشكله يجب أن يلتقيا تماماً عند نقطة الاتصال.</li>
<li><strong>المقاس يأكل من الإطار.</strong> زاوية 23 × 23 سم تأخذ 23 سم من كل ضلع عند كل ركن، فالإطار الذي عرضه 60 سم لا يبقى فيه إلا 14 سم للعود المستقيم. القاعدة: لا تزد الزاويتان معاً على نصف أقصر ضلع.</li>
<li><strong>العدد.</strong> أربع زوايا لكل إطار مستطيل. ستة إطارات تعني 24 زاوية، فراجع الاسم هل البيع بالحبة أم بالطقم.</li>
<li><strong>طول العود يتغير.</strong> اطرح مقاس الزاويتين من كل ضلع قبل حساب الأعواد.</li>
</ul>
<h3>أين تصلح وأين لا؟</h3>
<p>تصلح للجدران الداخلية في المجالس وغرف النوم والممرات العريضة، وتليق بالإطارات المتوسطة والكبيرة. لا تصلح للإطارات الصغيرة التي تبتلعها الزاوية، ولا للطراز الحديث ذي الخطوط المستقيمة، ولا للخارج.</p>
<h3>التركيب</h3>
<p>تُلصق الزوايا الأربع أولاً على خطوط الإطار المرسومة بالميزان، ثم يُقاس ما بينها ويُقص العود المستقيم على المقاس الفعلي. بهذا الترتيب تقع أي فروق صغيرة في طول العود لا في موضع الزاوية. يُستخدم لاصق تركيب يناسب الفوم على جدار مدهون وجاف، وتُملأ نقاط الاتصال بمعجون قابل للدهان ثم تُدهن مع الجدار بدهان مائي. المساعدة في التقسيم والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معها</h3>
<p>أعواد <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a> المطابقة لها. وللسقف زوايا خاصة في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b7%d9%82%d9%85-%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a7%d9%84%d8%a3%d8%b3%d9%82%d9%81/">أطقم زوايا الأسقف</a>.</p>
<h3>العناية</h3>
<p>نفض بفرشاة ناعمة، والدهان يُجدَّد مع دهان الجدار.</p>
<h3>عيوبها</h3>
<ul>
<li>تضيف أربع قطع إلى تكلفة كل إطار.</li>
<li>زاوية لا تطابق العود تفسد الإطار كله.</li>
<li>تفرض طرازاً كلاسيكياً، ولا يحسن خلط مقاسين منها على جدار واحد.</li>
<li>فوم طريّ ينبعج إن ضُرب.</li>
</ul>
<p>كل الأشكال في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">زوايا البانوهات</a>.</p>' ),
	'mo-cornice' => array( 'دليل كرانيش السقف', '<h3>ما هو الكرنيش؟</h3>
<p>عود زخرفي يُركَّب عند التقاء الجدار بالسقف، فيخفي خط الالتقاء والتشققات الشعرية فيه ويعطي الغرفة حداً علوياً واضحاً. أغلب كرانيش هذه المجموعة من فوم البولي يوريثان (PU)، وبعضها «فايبر» بوليسترين، و«الفوم الوطني» يُسأل عن نوعه. المقاسات من 4 × 4 سم إلى 13 × 12 سم، والطول 2 م أو 2.40 أو 2.44 م بحسب الموديل. ومنها موديلات للإضاءة المخفية، وواحد يجمع الإضاءة وبيت الستارة.</p>
<h3>أي مقاس لأي سقف؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">ارتفاع السقف</th><th scope="col">ارتفاع الكرنيش المناسب</th></tr>
</thead>
<tbody>
<tr><td>نحو 2.7 م</td><td>5 إلى 8 سم</td></tr>
<tr><td>نحو 3 م</td><td>8 إلى 12 سم</td></tr>
<tr><td>3.5 م فأكثر</td><td>12 سم فأكثر</td></tr>
</tbody>
</table>
<p>الكرنيش الكبير على سقف منخفض يُنزله بصرياً، والصغير على سقف عالٍ لا يُرى. والمقاس مكتوب برقمين: ما ينزل على الجدار وما يمتد على السقف، فاسأل أيّ الرقمين للجدار.</p>
<h3>الزوايا، وهي أصعب ما فيه</h3>
<ul>
<li><strong>الزاوية الداخلة</strong> (ركن الغرفة) والزاوية <strong>الخارجة</strong> (بروز عمود) تُقصان بميلين متعاكسين، والكرنيش يوضع في صندوق القصّ مقلوباً كما سيجلس على الجدار.</li>
<li><strong>أركان الغرف قلّما تكون 90° تماماً،</strong> فيُجرَّب القصّ على فضلة أولاً، وما يبقى من فراغ يُملأ بمعجون.</li>
<li><strong>ابدأ من الركن الأبعد عن الباب</strong> واجعل آخر وصلة حيث لا تقع عليها العين.</li>
</ul>
<h3>كم عوداً؟</h3>
<p>محيط الغرفة ÷ طول العود، ثم عود إضافي لقصّ الأركان. غرفة 4 × 5 أمتار محيطها 18 م: تسعة أعواد بطول 2 م وعاشر للقص، أو ثمانية بطول 2.44 م وتاسع للقص. كل بروز في الجدار يضيف أربع قصّات. واجعل الوصلة بين عودين قريبة من الركن لا في منتصف جدار ظاهر. والعدد نؤكده لك إن أرسلت المقاسات على الواتساب.</p>
<h3>كرنيش الإضاءة المخفية</h3>
<p>يُركَّب نازلاً عن السقف بضعة سنتيمترات فيبقى فوقه مجرى لشريط الإضاءة. يلزمه سلك كهرباء واصل إلى المجرى قبل التركيب، ومكان للمحوّل يمكن فتحه. والسقف فوقه يجب أن يكون مدهوناً جيداً، لأن الضوء المائل يكشف كل تموج.</p>
<h3>التركيب والدهان</h3>
<p>يُلصق بلاصق تركيب على الجدار والسقف معاً، ويُسند بمسامير رفيعة مؤقتة حتى يجف. الوصلات تُملأ بمعجون أكريليك قابل للدهان، ثم دهان مائي. وإن كان السقف مكسوّاً بألواح أو الجدار بورق جدران فالكرنيش يُركَّب أولاً. الفني متاح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>أين يصلح وأين لا؟</h3>
<p>يصلح في الغرف والمجالس والممرات. يُبعد عن فتحات التكييف الحارّ والمصابيح شديدة الحرارة، ولا يُركَّب في الخارج. والحمّام جيد التهوية يقبله إن دُهن.</p>
<h3>معه</h3>
<p><a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">بانوهات</a> للجدار بالطراز نفسه، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b7%d9%82%d9%85-%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a7%d9%84%d8%a3%d8%b3%d9%82%d9%81/">أطقم زوايا للسقف</a>، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> توازنه من الأسفل.</p>
<h3>عيوبه</h3>
<ul>
<li>قصّ الأركان يحتاج يداً متمرّسة.</li>
<li>الوصلات تظهر إن لم تُعجَن وتُدهن.</li>
<li>الأبيض غير المدهون يصفرّ مع السنين.</li>
<li>أطرى من الجبس، لكنه بعيد عن الأيدي.</li>
</ul>
<p>كل المقاسات في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%85%d8%af%d8%a9-%d9%88%d9%83%d8%b1%d8%a7%d9%86%d9%8a%d8%b4/">الأعمدة والكرانيش</a>.</p>' ),
	'mo-ornament' => array( 'دليل الزخارف والحليات', '<h3>ما هي الزخارف والحليات؟</h3>
<p>قطع بارزة منقوشة تُلصق على الجدار أو السقف لتكون نقطة تزيين، لا إطاراً ولا شريطاً. هي من فوم البولي يوريثان (PU) عالي الكثافة بسطح مطلي جاهز يقبل الدهان، وسماكتها بين 1.5 و3.8 سم. وهي ثلاثة أنواع:</p>
<table class="txa-family">
<thead>
<tr><th scope="col">النوع</th><th scope="col">أمثلة من المقاسات</th><th scope="col">موضعه المعتاد</th></tr>
</thead>
<tbody>
<tr><td>طقم حبتين، يمين ويسار</td><td>13.3 × 24.9 سم إلى 40 × 50 سم</td><td>متقابلتان على جانبي باب أو مرآة أو أعلى إطار</td></tr>
<tr><td>قطعة مركزية</td><td>25 × 15 سم إلى 63 × 53 سم</td><td>منتصف إطار بانوه، أو فوق فتحة باب</td></tr>
<tr><td>زخرفة زاوية صغيرة</td><td>12 × 12 و13 × 9 سم</td><td>أركان إطار أو لوحة</td></tr>
</tbody>
</table>
<h3>كيف تختار المقاس؟</h3>
<p>الزخرفة تُقاس بما حولها لا بالجدار كله. داخل إطار بانوه، اجعل عرضها بين ثلث عرض الإطار ونصفه، فالأكبر يزحم الإطار والأصغر يضيع فيه. وفوق الباب، لا تتجاوز عرض الفتحة. الطقم المتناظر يُشترى طقماً واحداً لكل موضع، فتأكد من الاسم هل البيع بالحبتين معاً أم بالحبة. وقطعة واحدة مدروسة الموضع أوقع من خمس متفرقة.</p>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الموضع</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>مجلس أو صالة بطراز كلاسيكي أو نيوكلاسيك</td><td>مناسب</td><td>تكمل البانوه والكرنيش</td></tr>
<tr><td>أعلى الباب والمرآة ورأس السرير</td><td>مناسب</td><td>فوق مستوى الأيدي</td></tr>
<tr><td>غرفة بطراز حديث بسيط</td><td>بحساب</td><td>النقش الكثيف يخالف الخطوط المستقيمة</td></tr>
<tr><td>أسفل الجدار في ممر</td><td>لا</td><td>النقش البارز ينكسر طرفه بالاحتكاك</td></tr>
<tr><td>خارج البيت وقرب الحرارة العالية</td><td>لا</td><td>للداخل فقط</td></tr>
</tbody>
</table>
<h3>التركيب</h3>
<ul>
<li>حدّد المركز أولاً: خط عمودي خفيف بالقلم في منتصف الإطار أو الفتحة، وتُعلَّم عليه حدود القطعة.</li>
<li>السطح مدهون وجاف ونظيف، واللاصق يوزَّع على الظهر كله دون أن يسيل من الأطراف.</li>
<li>القطعة الثقيلة تُسند بشريط لاصق ورقي حتى يجف اللاصق.</li>
<li>القطعة الكبيرة تحتاج جداراً مستوياً، فظهرها مسطح لا ينثني ليتبع التموج.</li>
<li>في الطقم، ثبّت الأولى ثم قِس موضع الثانية منها لا من الجدار.</li>
</ul>
<p>إن كانت ضمن جدار بانوهات كامل فالأسهل تنفيذها معه عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>الدهان</h3>
<p>تُملأ الحافة بينها وبين الجدار بخط رفيع من المعجون، ثم تُدهن مع الجدار بدهان مائي. الفرشاة الصغيرة تصل إلى تجاويف النقش أفضل من الرول، ووجهان خفيفان أحسن من وجه ثقيل يطمس التفاصيل. ومن يريد إبرازها يدهنها بدرجة أفتح أو أغمق قليلاً من الجدار.</p>
<h3>ما يُطلب معها</h3>
<p>أعواد <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a> التي ستتوسطها، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">زوايا</a> بالنقش نفسه إن وُجدت. وبقية القطع في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%af%d9%8a%d9%83%d9%88%d8%b1/">إكسسوارات الديكور</a>.</p>
<h3>العناية</h3>
<p>الغبار يتجمع في النقش، ففرشاة رسم جافة ناعمة تُخرجه. لا ماء كثير ولا فرك.</p>
<h3>عيوبها</h3>
<ul>
<li>أطراف النقش الدقيقة تنكسر إن صُدمت.</li>
<li>تثبت طرازاً بعينه، فتغيير ذوق الغرفة لاحقاً يعني نزعها وترميم الدهان.</li>
<li>الإكثار منها يثقل الجدار.</li>
</ul>' ),
	'mo-panel' => array( 'دليل البانوهات والبراويز', '<h3>ما هي البانوهات والبراويز والمدادات؟</h3>
<p>أعواد بارزة رفيعة تُلصق على الجدار فترسم عليه إطارات مستطيلة تسمى بانوهات. العود نفسه يُسمّى بروازاً أو مداداً، والمداد المسطح الأعرض يُستخدم شريطاً فاصلاً. عروض هذه المجموعة من 2 إلى 15 سم، وأطوالها بين 2 و2.40 م. الخامات ثلاث: فوم بولي يوريثان (PU)، و«فايبر» وهو بوليسترين (PS)، و«فوم وطني» و«صيني» يُسأل عن نوعهما. أغلبها بالعود، وبعض الموديلات يُباع بالمتر الطولي، فانتبه للوحدة.</p>
<h3>تقسيم الجدار إلى إطارات</h3>
<ul>
<li><strong>الهوامش أولاً.</strong> اترك 10 إلى 15 سم بين الإطار وكل من النعلة والكرنيش وزاويتي الجدار، والمسافة نفسها بين إطار وآخر.</li>
<li><strong>عدد الإطارات.</strong> اطرح الهوامش من عرض الجدار واقسم الباقي على عدد الإطارات. الإطارات الطولية ترفع السقف بصرياً، والعدد الفردي يضع إطاراً في المنتصف خلف الشاشة أو السرير.</li>
<li><strong>الأفياش والمفاتيح.</strong> عدّل التقسيم حتى لا يمرّ عود فوق مفتاح.</li>
<li><strong>جرّب قبل القص.</strong> ارسم التوزيع بشريط لاصق ورقي على الجدار وانظر إليه من الباب.</li>
</ul>
<h3>أي عرض يناسب؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">عرض العود</th><th scope="col">أين يليق</th></tr>
</thead>
<tbody>
<tr><td>2 إلى 2.4 سم</td><td>إطار داخلي ثانٍ، أو غرفة صغيرة</td></tr>
<tr><td>3 إلى 5 سم</td><td>إطارات الجدار في غرفة بارتفاع 2.7 إلى 3 أمتار</td></tr>
<tr><td>6 إلى 9 سم</td><td>إطار واحد كبير، أو مجلس واسع</td></tr>
<tr><td>12 إلى 15 سم (مداد مسطح)</td><td>شريط فاصل أو تأطير باب، لا إطار بانوه</td></tr>
</tbody>
</table>
<p>ومن أراد إطاراً مزدوجاً وضع عوداً رفيعاً داخل الإطار العريض بهامش 5 إلى 8 سم.</p>
<h3>الزوايا: قصّ 45° أم زاوية جاهزة؟</h3>
<p>القصّ المائل يعطي إطاراً بسيطاً حادّ الأركان، ويحتاج صندوق قصّ ودقة، وكل خطأ فيه يظهر فراغاً في الركن. الزاوية الجاهزة من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">زوايا البانوهات</a> تُغني عن القصّ المائل وتعطي ركناً مزخرفاً كلاسيكياً، بشرط أن يطابق عرضها ونقشها عودك.</p>
<h3>كم عوداً؟</h3>
<p>محيط الإطار = (العرض + الارتفاع) × 2. اجمع محيطات الإطارات كلها واقسمها على طول العود، وأضف عوداً للقصّ. إطار 80 × 180 سم محيطه 5.2 م، أي ثلاثة أعواد بطول 2.40 م. وأرسل لنا المقاسات على الواتساب لنحسب لك العدد.</p>
<h3>التركيب والدهان</h3>
<p>جدار مدهون وجاف، ولاصق تركيب يناسب الفوم، وخط أفقي بالميزان يُبدأ منه. بعد اللصق تُملأ الوصلات والأركان بمعجون قابل للدهان وتُصنفر، ثم يُدهن الجدار والبانوه معاً بدهان مائي وجهين. البوليسترين يذوب بالمذيبات فلا تقربه بدهان زيتي ولا بخاخ. والفوم غير المدهون يصفرّ مع الضوء. التنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>أين لا يصلح؟</h3>
<p>لا يصلح خارج البيت، ولا في أسفل جدار تصدمه الكراسي والعربات، ولا قرب مصدر حرارة عالية، فالفوم طريّ وقابل للاشتعال.</p>
<h3>عيوبه</h3>
<ul>
<li>ينبعج بالضربة.</li>
<li>الوصلة كل مترين تقريباً تحتاج معجوناً، وإلا ظهرت خطاً.</li>
<li>يُلصق لصقاً دائماً، ونزعه يقشّر الدهان.</li>
<li>الأنواع الأرخص أنعم تفصيلاً من الجبس.</li>
</ul>
<p>بقية الأشكال في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a>.</p>' ),
	'mo-sticks' => array( 'دليل أعواد الديكور المربعة', '<h3>ما هي أعواد الديكور؟</h3>
<p>أعواد مربعة المقطع، 3 × 3 سم أو 4 × 4 سم، وطول العود 240 سم. تختلف عن البرواز بأنها بلا نقش ولا انحناء: مربع بسيط يصنع خطاً مستقيماً بارزاً. في المجموعة خامتان: فوم بولي يوريثان (PU)، و«فايبر» بوليسترين (PS). وصف أعواد PS منقول عن النعلات فيتحدث عن الأرضيات، فلا تعتمد عليه في معرفة الاستخدام.</p>
<h3>بماذا تُستخدم؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الاستخدام</th><th scope="col">الطريقة</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>جدار خطوط عمودية</td><td>أعواد متوازية بفراغ ثابت بينها</td><td>بديل مدهون عن المضلع الخشبي</td></tr>
<tr><td>إطار بانوه حديث</td><td>مستطيل بأركان مقصوصة 45°</td><td>للطراز البسيط بلا زخرفة</td></tr>
<tr><td>شبكة على السقف</td><td>مربعات أو مستطيلات متكررة</td><td>تحتاج تخطيطاً بالخيط</td></tr>
<tr><td>تأطير مرآة أو لوحة أو شاشة</td><td>أربعة أضلاع</td><td>عود واحد أو اثنان يكفيان</td></tr>
</tbody>
</table>
<h3>حساب جدار الخطوط</h3>
<p>عدد الأعواد = عرض الجدار ÷ (عرض العود + الفراغ). جدار 3 أمتار بعود 4 سم وفراغ 6 سم يأخذ 30 عوداً. وبعود 3 سم وفراغ 3 سم يأخذ 50 عوداً. الفراغ هو ما يحدد التكلفة والشكل: المتقارب يعطي ملمساً، والمتباعد يعطي خطوطاً. وإن زاد ارتفاع جدارك على 240 سم لزمت وصلة في كل عود، فاجعل الوصلات كلها على ارتفاع واحد أو غطّها بعود أفقي. أرسل لنا مقاساتك على الواتساب لنراجع العدد.</p>
<h3>PU أم PS؟</h3>
<p>البولي يوريثان أصلب وحوافه أحدّ ويتحمل اللمس، فهو الأنسب لما يقع في مدى اليد. البوليسترين أخف وأطرى، ويذوب بالمذيبات، فمكانه السقف وأعلى الجدار، ولا يُدهن إلا بدهان مائي.</p>
<h3>التركيب</h3>
<ul>
<li>اقطع قطعة خشب بعرض الفراغ واستعملها مسطرة بين كل عودين، فهي أدق من القياس بالشريط كل مرة.</li>
<li>العود الأول بالميزان، ثم راجع الشاقول كل خمسة أعواد حتى لا يتراكم الخطأ.</li>
<li>لاصق تركيب مناسب للفوم على جدار مدهون وجاف.</li>
<li>دهان الجدار قبل اللصق أسهل، لأن الرول لا يدخل بين الأعواد المتقاربة. ثم وجه أخير للجميع.</li>
</ul>
<p>وللجدران الكبيرة <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>أين لا تصلح؟</h3>
<p>لا تصلح خارج البيت، ولا لجدار يستند إليه الناس أو تصدمه الأبواب، ولا قرب حرارة عالية.</p>
<h3>ما يُطلب معها</h3>
<p>للأركان المزخرفة <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%b2%d9%88%d8%a7%d9%8a%d8%a7-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">زوايا البانوهات</a>، وللإطارات المنقوشة أعواد <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">البانوهات</a>. وبقية المقاسات في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%88%d8%a7%d8%af-%d8%af%d9%8a%d9%83%d9%88%d8%b1/">أعواد الديكور</a>.</p>
<h3>عيوبها</h3>
<ul>
<li>الغبار يقف على حوافها العلوية وبينها.</li>
<li>أطول عود 240 سم، فالجدار الأعلى يحتاج وصلات.</li>
<li>كثرة العدد في الجدار المتقارب ترفع وقت اللصق والدهان.</li>
</ul>' ),
	'pq-acc' => array( 'دليل فواصل وإكسسوارات الباركيه', '<h3>فواصل وإكسسوارات الباركيه: لماذا تحتاجها؟</h3>
<p>الباركيه العائم لا يُلصق بالأرض ويحتاج أن يتمدد، فتبقى له أطراف مفتوحة عند الأبواب والعتبات والدرج. هذه القطع تغطي تلك الأطراف وتحميها. كلها أعواد بطول 2.40 متر تُباع بالقطعة، بألوان خشبية متعددة، وبثلاث خامات بحسب القطعة: PS و PVC وفايبر. تصلح مع اللامينيت ومع SPC، والمهم أن يناسب ارتفاعها سماكة أرضيتك.</p>
<h3>أي قطعة لأي مكان؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القطعة</th><th scope="col">أين تُركَّب</th><th scope="col">المقطع المذكور (مم)</th></tr>
</thead>
<tbody>
<tr><td>T</td><td>بين أرضيتين بمنسوب واحد، كباب بين غرفتين كلتاهما باركيه</td><td>40 × 12 أو 45 × 8</td></tr>
<tr><td>L</td><td>نهاية الباركيه عند جدار أو إطار لا تصله النعلة</td><td>20.5 × 11.5</td></tr>
<tr><td>نهاية R</td><td>نزول من الباركيه إلى أرضية أخفض، كسيراميك أو عتبة</td><td>52 × 13.5 أو 25 × 10</td></tr>
<tr><td>Q</td><td>ربع دائرة يسدّ الفراغ عند جدار دون فك النعلة القائمة</td><td>28 × 13</td></tr>
<tr><td>زاوية</td><td>حافة خارجية مكشوفة، كطرف درجة أو بروز</td><td>28 × 15 أو 30 × 30</td></tr>
<tr><td>درج</td><td>أنف الدرجة حين يُكسى السلّم بالباركيه</td><td>55 × 15 أو 55 × 18</td></tr>
</tbody>
</table>
<p>المقطع يختلف بين خامة وأخرى للقطعة نفسها، فطابق الرقم مع سماكة الباركيه والعازل معاً.</p>
<h3>كم قطعة تطلب؟</h3>
<p>عُدّ ولا تقدّر: فاصل لكل باب، ونهاية لكل طرف مكشوف، وقطعة درج لكل درجة. العود 240 سم يكفي بابين عرض كل منهما 90 سم ويبقى منه 60 سم. الباب المزدوج أو الفتحة الواسعة تأخذ عوداً كاملاً. لا توصل قطعتين في منتصف باب، فالوصلة تظهر وتُداس.</p>
<h3>التركيب</h3>
<ul>
<li>تُركَّب بعد انتهاء الأرضية وقبل النعلة أو معها.</li>
<li>تُثبَّت في الأرضية الأصلية تحتها أو في العتبة، لا في لوح الباركيه نفسه، حتى يبقى الباركيه حراً.</li>
<li>يُترك تحت جناح الفاصل الفراغ نفسه المتروك عند الجدران.</li>
<li>تُقص بمنشار ناعم الأسنان، وزاوية 45 درجة عند التقاء قطعتين في ركن.</li>
</ul>
<h3>PS أم PVC أم فايبر؟</h3>
<p>الثلاث خامات بلاستيكية لا تنتفخ بماء المسح، وهذا يكفي عند باب مطبخ أو حمام. الاختيار عملياً يتبع المقطع المتوفر في كل خامة ومطابقة اللون لأرضيتك، فاطلب صورة اللون بجانب لوح الباركيه. </p>
<h3>العناية</h3>
<p>تُمسح مع الأرضية. إن ارتخى فاصل وصار يتحرك تحت القدم فأعد تثبيته مبكراً قبل أن ينكسر.</p>
<h3>حدودها</h3>
<ul>
<li>ليست معدنية، والباب الذي تمرّ عليه عربات ثقيلة يحتاج حلاً آخر.</li>
<li>الدرج الخارجي ليس مكانها.</li>
<li>اللون «خشبي متعدد» في الصفحة، فالمطابقة تحتاج تأكيداً قبل الشحن.</li>
</ul>
<p>الأرضيات نفسها في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">الباركيه</a>، والنعلات في <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، والتركيب عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>' ),
	'pq-belgian' => array( 'دليل الباركيه البلجيكي 8 ملم', '<h3>الباركيه البلجيكي 8 ملم: ما الذي تشتريه؟</h3>
<p>لوح باركيه جاهز بنقشة خشبية، سماكته 8 ملم ومقاسه 126 × 19.2 سم، يُصنَّف في المتجر منشأً بلجيكياً. يأتي الكرتون بتسعة ألواح تغطي 2.179 م²، أي أن اللوح الواحد يغطي نحو 0.24 م². عرضه أكبر قليلاً من ألواح 18 سم الشائعة في الأقسام الأخرى، فتقلّ الفواصل الطولية في الغرفة. خامة القلب ودرجة الاحتكاك تُسألان من الفريق، ونعامله في هذا الدليل معاملة اللامينيت بقلب خشبي مضغوط، أي أنه يتأثر بالماء، إلى أن يؤكَّد غير ذلك.</p>
<h3>احسب بالكرتون لا باللوح</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">مساحة الغرفة</th><th scope="col">مع هدر 10%</th><th scope="col">عدد الكراتين</th></tr>
</thead>
<tbody>
<tr><td>12 م² (غرفة 3 × 4)</td><td>13.2 م²</td><td>7 كراتين</td></tr>
<tr><td>20 م² (غرفة 4 × 5)</td><td>22 م²</td><td>11 كرتوناً</td></tr>
<tr><td>30 م² (صالة 5 × 6)</td><td>33 م²</td><td>16 كرتوناً</td></tr>
</tbody>
</table>
<p>القسمة على 2.179 ثم التقريب إلى الأعلى دائماً. الغرفة كثيرة الزوايا أو التركيب المائل يرفعان الهدر، و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> تحسبها لمقاس غرفتك.</p>
<h3>أين يصلح؟</h3>
<ul>
<li><strong>مناسب:</strong> غرف النوم، غرف المعيشة، الصالات، المكاتب الهادئة.</li>
<li><strong>بشرط:</strong> فوق بلاط قائم إذا كان مستوياً وجافاً وفُرد تحت الألواح عازل.</li>
<li><strong>لا:</strong> الحمام، المطبخ الذي يُغسل بالماء، الشرفات، وأي أرضية فيها رطوبة صاعدة.</li>
<li><strong>اسأل أولاً:</strong> التدفئة الأرضية والمحلات التجارية، فدرجة تحمّله تحتاج تأكيداً.</li>
</ul>
<h3>بلجيكي أم صيني 8 ملم؟</h3>
<p>السماكة واحدة وطريقة التركيب واحدة. الفرق الثابت في المقاس والتعبئة: لوح البلجيكي أعرض وكرتونه أكبر، وألوانه 23 تصميماً أغلبها بنّي وعسلي، بينما <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b5%d9%8a%d9%86%d9%8a/">الصيني</a> أوسع ألواناً ولبعض تصاميمه درجة AC3. إن كان قرارك على المتانة فاطلب الدرجة مكتوبة للاثنين.</p>
<h3>التركيب باختصار</h3>
<p>يُرصّ عائماً فوق العازل، يبدأ الصف الأول من أطول جدار مستقيم، وتُخالَف الوصلات بين الصفوف. يُترك حول الأرضية كلها فراغ للتمدد لا يُسدّ بسيليكون ولا بمعجون، ولا تُثبَّت الألواح بمسامير أو غراء في البلاط. القص حول إطار الباب أنظف إذا قُصّ أسفل الإطار ودخل اللوح تحته. رفع المقاس والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>معه في السلة</h3>
<p>نعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a> بطول الجدران، وفاصل لكل باب من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل وإكسسوارات الباركيه</a>. اختر النعلة بعد أن تعرف هل ستُزال نعلة السيراميك القديمة أم تُغطّى.</p>
<h3>التنظيف وإصلاح العيوب الصغيرة</h3>
<p>بقعة القهوة أو العصير تُمسح في حينها بقماشة رطبة ثم جافة. الخدش الخفيف يختفي بقلم شمع قريب من لون اللوح. اللوح المتضرر قرب الجدار يُفك ويُبدَّل، والذي في وسط الغرفة يحتاج فنياً.</p>
<h3>متى لا نرشّحه؟</h3>
<ul>
<li>بيت فيه تسريب قديم أو رطوبة في الأرضية.</li>
<li>من يريد غسل الأرض بالماء والصابون.</li>
<li>من يحتاج رقماً موثّقاً لدرجة التحمّل ولا يجده في الصفحة.</li>
</ul>
<p>للأماكن الرطبة انظر <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/">باركيه SPC</a>.</p>' ),
	'pq-cn-5' => array( 'دليل الباركيه الصيني 5 ملم', '<h3>باركيه صيني 5 ملم: ما نعرفه وما لا نعرفه</h3>
<p>21 تصميماً بنقشة خشبية، أغلبها بيج ورمادي فاتح، لوحها طوله 120 سم وعرضه 18 سم وسماكته 5 ملم، أي نحو 0.22 م² للوح. المنشأ الصين. أهم ما تسأل عنه: خامة القلب. سماكة 5 ملم أقل من سماكة اللامينيت المعتادة (7 إلى 8 ملم) وقريبة من سماكة ألواح SPC، لكن هذه المنتجات غير مصنّفة في قسم SPC ولا يحمل اسمها هذه الكلمة. لذلك لا نجزم بنوعها، ونطلب منك سؤالاً واحداً قبل الشراء: هل القلب حجري بلاستيكي أم خشبي مضغوط؟</p>
<h3>لماذا يهمّ هذا السؤال؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">إن كان القلب</th><th scope="col">الماء</th><th scope="col">الأرضية تحته</th><th scope="col">المكان المناسب</th></tr>
</thead>
<tbody>
<tr><td>حجرياً بلاستيكياً (SPC)</td><td>النواة لا تمتصه</td><td>يتبع أي عيب فيها لأنه رقيق</td><td>كل الغرف الداخلية، والمطبخ بشروط</td></tr>
<tr><td>خشبياً مضغوطاً (HDF)</td><td>ينتفخ من الفواصل</td><td>لوح رقيق بهذه الخامة ضعيف التعشيق</td><td>غرف جافة قليلة الحركة فقط</td></tr>
</tbody>
</table>
<p>عبارة «مقاوم للماء والرطوبة» وحدها لا تكفي لتركيبه في مطبخ أو حمام.</p>
<h3>كيف تتحقق بنفسك عند الاستلام؟</h3>
<p>افتح كرتوناً قبل التركيب وانظر إلى مقطع اللوح من جانبه. القلب الخشبي المضغوط بني اللون ليفي الملمس ويُخدش بالظفر. القلب الحجري البلاستيكي رمادي أو فاتح، أملس، وأثقل في اليد مما يوحي به حجمه. وانظر إلى الظهر: العازل الإسفنجي الملتصق علامة شائعة في ألواح SPC. هذا فحص أولي لا يغني عن تأكيد البائع.</p>
<h3>إلى أن تتأكد: أين نضعه؟</h3>
<ul>
<li><strong>آمن:</strong> غرفة نوم، غرفة أطفال، مكتب منزلي، فوق بلاط مستوٍ وجاف.</li>
<li><strong>انتظر التأكيد:</strong> المطبخ، المدخل، محيط المغاسل.</li>
<li><strong>لا:</strong> الحمام والخارج.</li>
</ul>
<h3>التركيب</h3>
<p>اللوح الرقيق لا يسامح الأرضية. فاصل البلاط العريض أو البلاطة المرتفعة تظهر على السطح مع الوقت، فتُعبَّأ الفواصل وتُسوّى الفروق أولاً. يُسأل كذلك هل في ظهر اللوح عازل ملتصق أم يُفرد عازل منفصل، فالاثنان معاً يليّنان الأرضية أكثر مما يحتمل التعشيق. تُترك مسافة تمدد على المحيط كغيره من الأرضيات العائمة. المعاينة ورفع المقاس عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>الكمية والملحقات</h3>
<p>اطلب تغطية الكرتون ووحدة البيع مع عرض السعر ثم أدخل مساحة غرفتك في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>. يلزمه <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> للمحيط و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل</a> عند كل باب.</p>
<h3>التنظيف</h3>
<p>عامله معاملة الأضعف حتى تعرف خامته: ممسحة شبه جافة، ولا ماء راكد.</p>
<h3>لمن لا يناسب؟</h3>
<ul>
<li>من يريد مواصفات مكتوبة كاملة قبل الدفع، فاطلبها من الفريق.</li>
<li>أرضية قديمة متموجة لا تُنوى تسويتها.</li>
<li>مطبخ أو حمام، ما دام النوع غير مؤكد.</li>
</ul>
<p>البديل المعروف الخامة في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">شرائح SPC</a> للماء، وفي <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b5%d9%8a%d9%86%d9%8a/">الصيني 8 ملم</a> للغرف الجافة.</p>' ),
	'pq-cn-8' => array( 'دليل الباركيه الصيني 8 ملم', '<h3>ما هو الباركيه الصيني اللامينيت 8 ملم؟</h3>
<p>أرضية لامينيت: لوح من ألياف الخشب المضغوطة (HDF) تعلوه طبقة مطبوعة بنقشة الخشب ثم سطح شفاف يتلقى الاحتكاك، ويُقفل كل لوح بجاره بالتعشيق (كليك) دون غراء. ألواح هذه المجموعة من الصين وسماكتها 8 ملم. التصاميم الأحدث فيها لوح مقاسه 1220 × 200 مم، أي نحو ربع متر مربع، بكثافة 830 كجم/م³ ودرجة احتكاك AC3. وتصاميم أقدم مقاسها 126 × 18 سم ويغطي كرتونها 1.91 م²ا. البيع بالمتر المربع، فراجع مقاس التصميم وتغطية كرتونه في صفحته قبل الحساب.</p>
