<li>يصدر صوتاً أجوف إذا كانت الأرضية غير مستوية أو العازل رديئاً.</li>
<li>AC3 ليست لمحل تجاري ولا لحركة كثيفة.</li>
</ul>
<p>إن كانت الغرفة رطبة أو تُغسل بالماء فقارن البدائل في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pq-cn-other' => array( 'دليل باركيه صيني متنوع السماكة', '<h3>ما الذي في هذه المجموعة؟</h3>
<p>12 تصميماً صينياً لا تجمعها سماكة واحدة مكتوبة، وهي نوعان. الأول تسعة تصاميم باسم «لامينيت سيرفكس»، ألوانها بني جوزي وبني رمادي وبيج، تُباع بالمتر المربع وتُركَّب كليك دون غراء، واسأل عن مقاسها وسماكتها وتغطية كرتونها. الثاني ثلاثة تصاميم بنقشة رخامية، سماكتها تُؤكَّد من الفريق (6 أو 7 ملم)، ويغطي كرتونها مترين مربعين، واثنان منها يحملان في الاسم كلمة SPC. فالرقم الذي تعتمده هو ما يؤكده البائع للتصميم نفسه، لا ما في العنوان.</p>
