<h3>أين يصلح؟</h3>
<p>تصاميم «سيرفكس» لامينيت بحسب اسمها، فمكانها الغرف الجافة: نوم ومعيشة ومجلس ومكتب، فوق بلاط مستوٍ. لا تُركَّب في الحمام ولا في مطبخ يُغسل بالماء، لأن اللامينيت يتشرّب الماء من فواصله. التصاميم الرخامية الثلاثة تبقى على الحكم نفسه حتى تتأكد خامتها، وإن ثبت أنها SPC فمكانها الطبيعي مع <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/">باركيه SPC</a> وأحكامه.</p>
<h3>مقارنة سريعة</h3>
<p>إن أردت لامينيت صينياً بمواصفات مكتوبة (مقاس، كثافة، درجة AC3) فهي موجودة في تصاميم 8 ملم الحديثة ضمن <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b5%d9%8a%d9%86%d9%8a/">الباركيه الصيني</a>. ما يميّز هذه المجموعة هو اللون والنقشة فقط، وخصوصاً النقشة الرخامية التي لا تجدها في اللامينيت الخشبي.</p>
<h3>التركيب</h3>
<ul>
<li>الأرض تُكنس جيداً قبل فرد العازل، فحبة حصى واحدة تحته تُسمع مع كل خطوة.</li>
<li>الألواح تُخلط من أكثر من كرتون أثناء الرص حتى يتوزع تدرّج النقشة.</li>
<li>يبقى الباركيه حراً عند الجدران، وتُثبَّت النعلة في الجدار لا في الأرضية.</li>
</ul>
<p>التفاصيل يحددها الفني في الموقع عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والكمية من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلات</a> و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل أبواب ونهايات</a>.</p>
<h3>العناية</h3>
<p>قماشة مبللة قليلاً ومنظف أرضيات متعادل. لا مواد كاشطة.</p>
<h3>عيوب هذه المجموعة</h3>
<ul>
<li>مواصفاتها المكتوبة أقل من أي مجموعة باركيه أخرى في المتجر.</li>
<li>السماكة تُؤكَّد من الفريق قبل الطلب.</li>
<li>عدد محدود من الألوان.</li>
</ul>
<p>إن كان هذا يقلقك فابدأ من <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pq-german' => array( 'دليل الباركيه الألماني', '<h3>ما هو الباركيه الألماني اللامينيت؟</h3>
<p>ألواح لامينيت منشؤها ألمانيا، تُركَّب عائمة بالتعشيق دون غراء. قلب اللوح ألياف خشب مضغوطة، وما تراه على السطح نقشة خشب مطبوعة تحت طبقة حماية شفافة، لا قشرة خشب حقيقية. السماكة في هذه المجموعة 7 ملم في أغلب التصاميم و8 ملم في بعضها، ومقاس اللوح المذكور 130 × 19 سم، أي ربع متر مربع تقريباً. بعض التصاميم تحمل اسم «كايندل»، فتأكّد من سماكتها قبل الطلب لأن الفواصل والنعلات تُختار عليها.</p>
<h3>في أي غرفة تضعه؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>غرف النوم وغرف الأطفال</td><td>مناسب</td><td>دافئ تحت القدم مقارنة بالبلاط</td></tr>
<tr><td>الصالة والمجلس</td><td>مناسب</td><td>ضع لبّاداً تحت أرجل الكنب والطاولات</td></tr>
<tr><td>مكتب بكرسي متحرك</td><td>مقبول</td><td>العجلات الصلبة تترك مساراً باهتاً، فاستعمل قطعة حماية تحت الكرسي</td></tr>
<tr><td>المطبخ والحمام</td><td>لا</td><td>القلب الخشبي يتشرّب الماء من الفواصل وينتفخ</td></tr>
<tr><td>جدار زجاجي تضربه الشمس</td><td>بحذر</td><td>الحرارة تمدّد الألواح، فلا تُحشر عند الأطراف</td></tr>
<tr><td>فوق سيراميك قديم</td><td>مناسب</td><td>لا يحتاج تكسيراً إن كان البلاط ثابتاً ومستوياً</td></tr>
</tbody>
</table>
<h3>7 ملم أم 8 ملم؟ وألماني أم صيني؟</h3>
<p>الملّيمتر الزائد لا يغيّر شكل الأرضية. فائدته أن اللوح أصلب قليلاً، فيتسامح مع فرق بسيط في البلاط تحته ويكون تعشيقه أمتن، ولذلك نميل إلى 8 ملم للصالات والممرات ونكتفي بـ7 ملم لغرفة نوم أرضيتها مستوية. أما المقارنة مع <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b5%d9%8a%d9%86%d9%8a/">الباركيه الصيني</a> فلا تُحسم بالمنشأ وحده: التصاميم الصينية الحديثة عندنا تذكر درجة الاحتكاك AC3 وكثافة اللوح، ودرجة الألماني تُسأل من الفريق. فاطلب درجة AC للتصميم الذي أعجبك وقارن رقماً برقم.</p>
<h3>قبل التركيب وأثناءه</h3>
<ul>
<li>تُترك الكراتين مغلقة في الغرفة يوماً أو يومين لتأخذ حرارة المكان.</li>
<li>يُفحص استواء الأرض بمسطرة طويلة، وتُعالج الفروق بمادة تسوية.</li>
<li>يُفرد العازل، ثم تُرصّ الألواح بتخالف بين الصفوف حتى لا تتوالى الوصلات على خط واحد.</li>
<li>يُترك فراغ حرّ حول المحيط كله، وعند مواسير التكييف وإطارات الأبواب.</li>
<li>الغرفة الطويلة جداً أو المتصلة بغرفة أخرى يُقسَم امتدادها بفاصل عند الباب.</li>
</ul>
<p>الفني يرفع المقاس ويحدد ذلك في الموقع عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>القطع المكمّلة</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القطعة</th><th scope="col">وظيفتها</th><th scope="col">الكمية</th></tr>
</thead>
<tbody>
<tr><td>نعلة</td><td>تغطي الفراغ بين الباركيه والجدار</td><td>محيط الغرفة ناقص فتحات الأبواب</td></tr>
<tr><td>فاصل بين غرفتين</td><td>يغطي خط الالتقاء عند الباب</td><td>واحد لكل باب</td></tr>
<tr><td>فاصل نهاية</td><td>يُنهي الباركيه عند بلاط أو عتبة</td><td>بحسب الأطراف المكشوفة</td></tr>
</tbody>
</table>
<p>تجدها في <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a> و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل وإكسسوارات الباركيه</a>. والمساحة مع الهدر في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>العناية اليومية</h3>
<p>ارفع الأثاث عند نقله ولا تسحبه، وضع سجادة عند الباب تلتقط الرمل. يكفيه مسح بقطعة شبه جافة.</p>
<h3>ما لا يعجبك فيه</h3>
<ul>
<li>الماء عدوّه الأول، وانتفاخ الحواف لا علاج له غير تبديل اللوح.</li>
<li>الخدش العميق يُخفى بشمع ترميم ولا يُصنفر.</li>
<li>كلمة «ألماني» لا تخبرك بدرجة التحمّل، فاسأل عنها.</li>
</ul>' ),
	'pq-herringbone-lam' => array( 'دليل الباركيه الهرمي اللامينيت', '<h3>الباركيه الهرمي اللامينيت: نظامان لا نظام واحد</h3>
<p>النمط الهرمي (عظم السمكة) يُصنع في هذه المجموعة بطريقتين مختلفتين تماماً في التركيب والهدر. الأولى قطع صغيرة تُرصّ قطعة قطعة بزاوية قائمة؛ التصاميم الصينية 8 ملم منها مقاس قطعتها 60.3 × 10.5 سم وفي الكرتون 24 قطعة. الثانية «الهرمي الكبير»: لوح HDF واحد مقاسه 1205 × 407 مم بسماكة 8 ملم وكثافة 860 كجم/م³ ودرجة AC3، والنمط مطبوع على وجهه، فيُركَّب مستقيماً كأي لامينيت. وفي المجموعة أيضاً تصاميم سيرفكس وألمانية وكايندل ، فاسأل عن مقاسها وأيّ النظامين هي.</p>
<p>لوح الهرمي الكبير يغطي نحو نصف متر مربع، فتُنجز الغرفة بعدد قليل من الألواح. والقطع الصغيرة يغطي كرتونها 1.45 م².</p>
<table class="txa-family">
<thead>
<tr><th scope="col">البند</th><th scope="col">قطع صغيرة</th><th scope="col">لوح كبير مطبوع</th></tr>
</thead>
<tbody>
<tr><td>شكل الفواصل</td><td>فاصل حقيقي حول كل قطعة</td><td>فاصل مرسوم، والحقيقي بين الألواح فقط</td></tr>
<tr><td>الهدر</td><td>نحو 15% بسبب القص عند الجدران الأربعة</td><td>قريب من التركيب المستقيم</td></tr>
<tr><td>التركيب</td><td>أبطأ ويحتاج فنياً متمرساً</td><td>سريع</td></tr>
<tr><td>قطع يمين ويسار (A و B)</td><td>غالباً نعم، بعدد متساوٍ</td><td>لا</td></tr>
</tbody>
</table>
<h3>أين يصلح وأين لا؟</h3>
<ul>
<li><strong>مناسب:</strong> المجلس، الصالة، المدخل الداخلي الجاف، غرفة نوم رئيسية واسعة.</li>
<li><strong>فكّر مرتين:</strong> غرفة أصغر من 3 × 3 أمتار أو مزدحمة بأثاث منقوش، فالنمط كثير الخطوط.</li>
<li><strong>لا:</strong> الحمام والمطبخ الرطب. القلب HDF ينتفخ بالماء، وفواصل الهرمي أكثر عدداً من المستقيم، فمداخل الماء أكثر.</li>
</ul>
<h3>التركيب: ما يختلف عن المستقيم</h3>
<ul>
<li>يبدأ الفني من خط محور في وسط الغرفة لا من الجدار، حتى ينتهي النمط متماثلاً عند الطرفين.</li>
<li>رؤوس الأسهم توجَّه نحو أطول امتداد أو نحو النافذة، ويُتفق على ذلك قبل أول قطعة.</li>
<li>الأرضية تُسوّى بدقة أعلى، فالقطع القصيرة تُظهر أي ارتفاع عند طرفها.</li>
<li>الجدار المائل ينكشف مع هذا النمط، ويُعالج بالتخطيط من المحور.</li>
<li>يُفرد العازل وتُترك فجوة تمدد على المحيط كأي لامينيت.</li>
</ul>
<p>لهذا النمط يُفضَّل تنفيذ <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، واحسب بهدر 15% في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>هرمي لامينيت أم هرمي SPC؟</h3>
<p>الشكل متقارب والفرق في القلب: اللامينيت أدفأ ملمساً ومكانه الغرف الجافة، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/">SPC</a> نواته لا تمتص الماء فيدخل المطبخ. بقية تصاميم النمط في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d9%87%d8%b1%d9%85%d9%8a/">الباركيه الهرمي</a>.</p>
<h3>يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> بطول المحيط، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل</a> عند كل باب. في القطع الصغيرة اطلب الكراتين بعدد زوجي إن كان كل اتجاه في كرتون مستقل.</p>
<h3>العناية</h3>
<p>اكنس باتجاه القطع لا عكسها حتى لا يتجمع الرمل في الفواصل، وامسح بممسحة معصورة.</p>
<h3>عيوبه</h3>
<ul>
<li>هدر أعلى وأجرة تركيب أعلى في نظام القطع الصغيرة.</li>
<li>تبديل قطعة تالفة في الوسط صعب.</li>
<li>يتأثر بالماء كأي HDF.</li>
<li>خطأ في عدد قطع A و B يوقف العمل.</li>
</ul>' ),
	'pq-spc-herringbone' => array( 'دليل باركيه SPC الهرمي', '<h3>ما هو باركيه SPC الهرمي والشيفرون؟</h3>
<p>قطع قصيرة من SPC تُرصّ متعامدة فتصنع نمط عظم السمكة، بقلب حجري بلاستيكي لا يمتص الماء. المقاسات المذكورة في المجموعة: 640 × 128 مم بسماكة 4 ملم مع عازل IXPE 1 ملم في التصاميم الحديثة، و62.5 × 12.5 سم بكرتون فيه 26 قطعة تغطي 2.03 م² في تصاميم أخرى. القطعة تغطي نحو 0.08 م²، أي 12 إلى 13 قطعة للمتر. وفي المجموعة تصميمان باسم «شيفرون»، وثلاثة «شبيه الهرمي»، وهي شرائح طويلة مطبوع عليها النمط تُركَّب مستقيمة.</p>
<h3>هرمي، شيفرون، أم شبيه الهرمي؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">النوع</th><th scope="col">شكل القطعة</th><th scope="col">ما تراه على الأرض</th><th scope="col">الهدر</th></tr>
</thead>
<tbody>
<tr><td>هرمي</td><td>مستطيل كامل</td><td>خط متعرّج متدرّج</td><td>نحو 15%</td></tr>
<tr><td>شيفرون</td><td>طرفاه مقصوصان بزاوية</td><td>سهم مستقيم على شكل V</td><td>مثله أو أعلى</td></tr>
<tr><td>شبيه الهرمي</td><td>شريحة طويلة عادية</td><td>نمط مطبوع، والفواصل الحقيقية مستقيمة</td><td>نحو 10%</td></tr>
</tbody>
</table>
<p>في تصاميم «الشيفرون» اطلب صورة لالتقاء قطعتين قبل الشراء.</p>
<h3>أين يصلح؟</h3>
<ul>
<li><strong>مناسب:</strong> المدخل، الصالة، المجلس، الممر الطويل، حيث يُرى النمط كاملاً.</li>
<li><strong>مناسب:</strong> المطبخ المفتوح على الصالة، فتمتد الأرضية نفسها دون تغيير الخامة.</li>
<li><strong>بشرط:</strong> الحمام. فواصل الهرمي كثيرة، وكل فاصل طريق للماء إلى ما تحت الأرضية حيث يُحبس، فلا يُغمر بالماء.</li>
<li><strong>غير مفضّل:</strong> غرفة صغيرة مزدحمة، وأرضية لم تُسوَّ.</li>
<li><strong>لا:</strong> الخارج.</li>
</ul>
<h3>التركيب</h3>
<ul>
<li>الاستواء شرط لا يُتنازل عنه: قطعة طولها 64 سم يرتفع طرفها عند أي نتوء.</li>
<li>يُخطَّط من محور الغرفة، ويُحدَّد اتجاه الأسهم مع العميل قبل البدء.</li>
<li>قطع اليمين واليسار تُفرز قبل الرص إن كان النظام يتطلبها.</li>
<li>العازل الملتصق يغني عن عازل منفصل، ولا يُجمع بينهما.</li>
<li>تبقى فجوة تمدد عند الجدران تغطيها النعلة.</li>
</ul>
<p>هذا تركيب لفني متمرّس، فاطلبه من <a href="https://texadecore.store/install-services/">خدمات التركيب</a>. وأدخل هدر 15% في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<p>مثال: صالة 20 م² تُحسب 23 م² بعد الهدر، وبكرتون يغطي 2.03 م² تحتاج 12 كرتوناً. وإن كان النظام يميناً ويساراً فاطلب كرتوناً زائداً، حتى لا يتوقف العمل على قطع اتجاه واحد.</p>
<h3>SPC هرمي أم لامينيت هرمي؟</h3>
<p>إن كان النمط سيدخل المطبخ أو المدخل فـSPC. وإن كان لغرفة جافة وتريد ملمساً أدفأ فاللامينيت في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d9%87%d8%b1%d9%85%d9%8a/">الباركيه الهرمي</a> يؤدي الشكل نفسه.</p>
<h3>معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> للمحيط و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل</a> للأبواب، وكرتون احتياطي لأن تبديل قطعة يحتاج قطعة من الاتجاه نفسه.</p>
<h3>العناية</h3>
<p>ممسحة رطبة باتجاه الأسهم، ولا تدع الرمل يستقر في الفواصل الكثيرة.</p>
<h3>عيوبه</h3>
<ul>
<li>هدر وأجرة تركيب أعلى من الشرائح المستقيمة.</li>
<li>أي خطأ في أول صف يتضاعف عبر الغرفة.</li>
<li>صلب وبارد تحت القدم.</li>
<li>في بعض التصاميم أكّد السماكة مع الفريق قبل الطلب.</li>
</ul>' ),
	'pq-spc-plank-4mm' => array( 'دليل باركيه SPC شرائح 4 ملم', '<h3>باركيه SPC شرائح 4 ملم: المواصفة أولاً</h3>
<p>أرقّ شرائح SPC في المتجر. التصاميم الحديثة في المجموعة تذكر شريحة 1220 × 184 مم (وبعضها 183 مم) بقلب حجري بلاستيكي 4 ملم، ملتصق بظهرها عازل IXPE بسماكة 1 ملم، وفوقها طبقة حماية 0.3 ملم. الشريحة تغطي نحو 0.22 م²، والسعر بالمتر المربع، والتركيب كليك. تصاميم أقدم تذكر 126 × 18 سم، وبعضها يذكر كرتوناً يغطي 1.2 م²، فراجع صفحة التصميم نفسه.</p>
<table class="txa-family">
<thead>
<tr><th scope="col">الطبقة</th><th scope="col">السماكة المذكورة</th><th scope="col">وظيفتها</th></tr>
</thead>
<tbody>
<tr><td>طبقة الحماية الشفافة</td><td>0.3 ملم</td><td>تتلقى الخدش والاحتكاك، وهي التي تحدد عمر السطح</td></tr>
<tr><td>النقشة المطبوعة</td><td>تختلف بالتصميم</td><td>شكل الخشب ولونه</td></tr>
<tr><td>القلب الحجري البلاستيكي</td><td>4 ملم</td><td>الصلابة والتعشيق، وهو لا يمتص الماء</td></tr>
<tr><td>عازل IXPE</td><td>1 ملم</td><td>يخفف صوت الخطوات ويفصل اللوح عن البلاط</td></tr>
</tbody>
</table>
<h3>هل 0.3 ملم تكفي؟</h3>
<p>للسكن نعم: غرف النوم والمعيشة والمجلس العائلي. للمحل أو المكتب المزدحم أو مجلس يستقبل كل يوم يُبحث عن طبقة أسمك. وهذا الرقم ليس لكل تصاميم المجموعة، فلا تفترضه لتصميم لم يُكتب في صفحته. والرمل تحت الأحذية يأكل هذه الطبقة أسرع من أي شيء آخر، فسجادة المدخل جزء من المواصفة.</p>
<h3>أين نرشّحه وأين لا؟</h3>
<ul>
<li><strong>نرشّحه:</strong> تجديد شقة فوق سيراميك مستوٍ، حيث كل ملّيمتر تحت الأبواب محسوب.</li>
<li><strong>نرشّحه:</strong> المطبخ، لأن القلب لا يتشرّب ما ينسكب.</li>
<li><strong>بشرط:</strong> الحمام. اللوح نفسه لا يتضرر، لكن ما يتسرب تحت الأرضية لا يجد مخرجاً، فتُعالج الأطراف ويُسأل الفني أولاً.</li>
<li><strong>لا نرشّحه:</strong> بلاط بفواصل غائرة أو فروق منسوب، فالشريحة الرقيقة ترسم ما تحتها. الأصلح هناك <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">شريحة 5 ملم</a> بعد التسوية.</li>
<li><strong>لا:</strong> الشرفات والأسطح المكشوفة.</li>
</ul>
<h3>التركيب</h3>
<p>لأن العازل ملتصق بالشريحة لا يُفرد تحتها عازل آخر؛ طبقتان ليّنتان تجعلان التعشيق يتحرك وينكسر. تُنظَّف الأرض من الحصى، وتُملأ فواصل السيراميك العريضة، وتُرصّ الشرائح بتخالف لا يقل عن ثلث طول الشريحة بين صف وآخر. يُترك للأرضية هامش حركة عند الجدران، وهو ألزم ما يكون قرب النوافذ المشمسة. المعاينة عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والكمية من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>القطع المكمّلة</h3>
<p>نعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، وفاصل منخفض المقطع يناسب أرضية كليّتها 5 ملم من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل وإكسسوارات الباركيه</a>. تأكّد من ارتفاع الفاصل، فأغلب المقاطع مصممة لأرضيات أسمك.</p>
<h3>التنظيف</h3>
<p>المسح الرطب اليومي لا مشكلة فيه. اعصر الممسحة حتى لا ينزل الماء من الوصلات، وابتعد عن ممسحة البخار لأن حرارتها المركّزة تُضعف التعشيق.</p>
<h3>عيوبه</h3>
<ul>
<li>أقل الشرائح تسامحاً مع أرضية غير مستوية.</li>
<li>ملمسه صلب وبارد قياساً بالخشب واللامينيت.</li>
<li>لسان التعشيق الرقيق ينكسر إن فُكّ وأُعيد أكثر من مرة.</li>
<li>يتمدد تحت الشمس المباشرة خلف الزجاج.</li>
</ul>
<p>وازن بينه وبين اللامينيت في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pq-spc-plank-5mm' => array( 'دليل باركيه SPC شرائح 5 ملم', '<h3>ما هو باركيه SPC شرائح 5 ملم؟</h3>
<p>SPC اختصار لمركّب من مسحوق الحجر والبلاستيك يُضغط لوحاً صلباً، فوقه نقشة خشب مطبوعة وطبقة حماية شفافة. شرائح هذه المجموعة سماكتها 5 ملم ومنشؤها الصين، وتُركَّب بالتعشيق دون غراء. المقاس يختلف بالتصميم: 122 × 18.2 أو 18.3 سم في أكثرها، و120 × 18 سم في بعضها، أي نحو 0.22 م² للشريحة. الكرتون يغطي 1.79 م² أو 2.23 م² بحسب التصميم. وبعض التصاميم فيها عازل IXPE ملتصقاً بالظهر بسماكة 1.5 ملم، فتصير السماكة الكلية نحو 6 ملم.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>غرف النوم والمعيشة والمجلس</td><td>مناسب</td><td>سطح صلب سهل المسح</td></tr>
<tr><td>المطبخ</td><td>مناسب</td><td>نواته لا تمتص الماء، فالانسكاب اليومي لا يضره</td></tr>
<tr><td>المدخل والممر</td><td>مناسب</td><td>مع سجادة تلتقط الرمل، فهو ما يخدش طبقة السطح</td></tr>
<tr><td>الحمام</td><td>اسأل قبل الطلب</td><td>اللوح يتحمل، لكن الماء المتسرب من الأطراف يُحبس تحته</td></tr>
<tr><td>غرفة بواجهة زجاجية مشمسة</td><td>بحذر</td><td>الشمس القوية تمدّده، فتلزمه فجوة وستائر</td></tr>
<tr><td>فوق سيراميك قائم</td><td>مناسب</td><td>بعد تعبئة الفواصل العريضة ومعالجة الفروق</td></tr>
<tr><td>الخارج</td><td>لا</td><td>أرضية داخلية</td></tr>
</tbody>
</table>
<h3>ماذا يعني أن نواته لا تمتص الماء؟</h3>
<p>يعني أن قلب اللوح لا يتشرّب الماء ولا ينتفخ به. ولا تعني أن الأرضية حوض مغلق: الماء الذي ينزل من الفواصل أو من عند الجدار يبقى بين الألواح والبلاط، ولا يجف بسهولة وقد تخرج له رائحة. فامسح رطباً كما تشاء ولا تغمر الأرض.</p>
<h3>5 ملم أم 4 ملم؟</h3>
<p>الفرق ملّيمتر في القلب الحجري. شريحة 5 ملم أصلب، فتعشيقها أثبت فوق بلاط ليس مثالياً وصوتها أمتن تحت القدم. شريحة <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">4 ملم</a> تكفي أرضية مستوية في غرفة نوم، ولا ترفع المنسوب كثيراً تحت الأبواب. وللعلم: عمر السطح تحدده سماكة طبقة الحماية لا سماكة اللوح، فاسأل عن رقمها.</p>
<h3>التركيب: ماذا تحتاج أرضيتك؟</h3>
<ul>
<li><strong>استواء حقيقي.</strong> اللوح الرقيق الصلب لا يتبع التموج بل ينكسر تعشيقه فوقه.</li>
<li><strong>عازل واحد فقط.</strong> إن كان في ظهر الشريحة عازل فلا يُفرد تحتها عازل ثانٍ.</li>
<li><strong>فجوة تمدد على المحيط</strong> وعند إطارات الأبواب، يحدد مقدارها الفني وتغطيها النعلة.</li>
<li><strong>الخزائن الثقيلة المبنية</strong> تُركَّب على الأرضية الأصلية لا فوق الشرائح.</li>
</ul>
<p>احسب المساحة في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما الذي يُطلب معه؟</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> لا تتأثر بالماء للمحيط، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل</a> لكل باب ونهاية.</p>
<h3>العناية والتنظيف</h3>
<p>مكنسة ثم ممسحة رطبة بمنظف متعادل. لا بخار ولا شمع ولا سلك تنظيف.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>أقسى وأبرد تحت القدم من اللامينيت.</li>
<li>يُظهر عيوب الأرضية التي تحته إن لم تُسوَّ.</li>
<li>لا يُصنفر، والخدش العميق يبقى.</li>
<li>الشمس المباشرة الطويلة تغيّر لون الداكن منه مع السنين.</li>
</ul>
<p>للمقارنة مع اللامينيت راجع <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pq-spc-plank-8mm' => array( 'دليل باركيه SPC شرائح 8 ملم', '<h3>باركيه SPC شرائح 8 ملم</h3>
<p>ثلاثة تصاميم صينية فقط: رمادي هيز، خشبي، وبني. اسمها يقول SPC بسماكة 8 ملم، وهذه سماكة غير معتادة لهذا النوع، فشرائح SPC في بقية المتجر 4 و5 ملم. فتأكد من سماكة التصميم المختار مع الفريق قبل الطلب. تغطية الكرتون المذكورة في اثنين منها متران مربعان. لذلك أول ما تفعله أن تطلب تأكيد السماكة والخامة للتصميم الذي اخترته، وهل الرقم يشمل عازلاً ملتصقاً بالظهر.</p>
<h3>لماذا قد تريد SPC أسمك؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">ما تكسبه</th><th scope="col">ما تدفعه مقابله</th></tr>
</thead>
<tbody>
<tr><td>لوح أصلب يعبر فروق البلاط الصغيرة دون أن يرسمها</td><td>ارتفاع أكبر للأرضية، وقد تُقص الأبواب من أسفلها</td></tr>
<tr><td>تعشيق أسمك وأثبت</td><td>وزن أثقل للكرتون في الشحن والحمل</td></tr>
<tr><td>صوت أقل فراغاً تحت القدم</td><td>ثلاثة ألوان فقط تختار منها</td></tr>
</tbody>
</table>
<p>هذه مزايا السماكة إن ثبتت. أما مقاومة الخدش فتتبع طبقة الحماية، فاسأل عنها.</p>
<h3>أين يصلح؟</h3>
<p>إن تأكد أنه SPC فنواته لا تمتص الماء، ومكانه الغرف والصالات والمطبخ. وفي الحمام تبقى القاعدة العامة: الشريحة تتحمل، وما يتسرب تحتها هو المشكلة. وإن ظهر أن القلب خشبي مضغوط بسماكة 8 ملم فهو لامينيت، يتأثر بالماء ولا يدخل مطبخاً ولا حماماً. لهذا السبب لا تركّبه في مكان رطب قبل التأكيد.</p>
<h3>التركيب</h3>
<p>تعشيق عائم فوق أرضية نظيفة وثابتة، مع هامش تمدد على الأطراف. قِس الفراغ تحت أبواب الغرف وباب الشقة قبل الطلب، فثمانية ملّيمترات مع العازل تسدّ فراغاً كان كافياً. ويُراجع التقاء الأرضية الجديدة ببلاط الحمام والمطبخ، فالفرق في المنسوب يحتاج فاصل نزول. المعاينة عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>الكمية والملحقات</h3>
<p>بثلاثة تصاميم يصعب إكمال النقص لاحقاً، فاطلب الكمية كاملة بهدرها من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>. ومعه <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل</a> تناسب سماكته.</p>
<h3>العناية</h3>
<p>مسح رطب معتدل، وتجفيف ما ينسكب عند الأطراف خصوصاً. واكنس الرمل قبل المسح حتى لا يتحول تحت الممسحة إلى صنفرة على طبقة السطح. ولا تسحب فوقه أثاثاً ثقيلاً.</p>
<h3>عيوبه</h3>
<ul>
<li>السماكة تُؤكَّد من الفريق قبل الطلب.</li>
<li>أقل مجموعات SPC ألواناً.</li>
<li>يرفع منسوب الأرضية أكثر من غيره.</li>
</ul>
<p>التشكيلة الأوسع في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">شرائح SPC</a>.</p>' ),
	'pq-spc-plank-na' => array( 'دليل شرائح باركيه SPC', '<h3>شرائح SPC بلا سماكة مكتوبة</h3>
<p>37 تصميماً من شرائح SPC بنقشات بلوط وعسلي ورمادي وبني جوزي، تُباع بالمتر المربع وتُركَّب كليك دون غراء. اسأل الفريق عن السماكة والمقاس وتغطية الكرتون للتصميم المختار قبل الطلب. القلب حجري بلاستيكي كبقية SPC، فنواته لا تمتص الماء، وهذا مؤكد من التصنيف. الباقي يُسأل عنه لكل تصميم: المتجر يبيع شرائح SPC بسماكة 4 و5 ملم، وقلّة من تصاميم هذه المجموعة تذكر 6 أو 7 ملم.</p>
<h3>اطلب هذه الأرقام الأربعة</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الرقم</th><th scope="col">ما يترتب عليه</th></tr>
</thead>
<tbody>
<tr><td>سماكة القلب</td><td>تحمّل الشريحة لأرضية غير مثالية، وارتفاع المنسوب تحت الأبواب</td></tr>
<tr><td>طبقة الحماية</td><td>كم سنة يبقى السطح قبل أن يبهت مسار المشي</td></tr>
<tr><td>عازل ملتصق أم لا</td><td>هل تشتري عازلاً منفصلاً أم يُمنع فرده</td></tr>
<tr><td>تغطية الكرتون</td><td>عدد الكراتين التي تُشحن لمساحتك</td></tr>
</tbody>
</table>
<h3>أين يصلح؟</h3>
<p>حكمه حكم SPC عموماً: كل الغرف الداخلية، والمطبخ، والممرات. الحمام ممكن من جهة اللوح، لكن الخطر ليس في الشريحة بل في الماء الذي يجد طريقه إلى ما تحتها ويبقى هناك؛ فتُحكم الأطراف ولا تُغسل الأرض بالخرطوم. لا يُركَّب في الخارج. والتصميم الذي لا تعرف سماكته لا تضعه فوق بلاط متموج قبل أن تعرفها.</p>
<h3>كيف تختار السماكة حين تعرف الخيارات؟</h3>
<p>أرضيتك مستوية والغرفة غرفة نوم: 4 ملم تكفي. بلاط قديم بفواصل ظاهرة أو صالة كثيرة الحركة: 5 ملم فأكثر بعد تعبئة الفواصل. أبواب منخفضة لا تريد قصّها: اجمع سماكة اللوح وعازله قبل أن تختار. وفي كل الحالات اسأل عن طبقة الحماية، فهي التي تفرّق بين تصميمين متشابهين في السماكة.</p>
<h3>مقارنة مع المجموعات المعروفة السماكة</h3>
<p>إن أردت أن تقرّر من الصفحة دون سؤال، فتصاميم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">شرائح SPC</a> المكتوب في اسمها 4 أو 5 ملم أوضح: مقاس وعازل وطبقة حماية في بعضها. هذه المجموعة تستحق السؤال حين يعجبك لون لا تجده هناك.</p>
<h3>التركيب</h3>
<ul>
<li>يُفحص البلاط القائم: الثابت المستوي يُركَّب فوقه، والمخلخل يُعالج أولاً.</li>
<li>الصبّة الجديدة تُترك حتى تجف تماماً، فالرطوبة المحبوسة تحت الشرائح تُخرج رائحة ولو لم يتضرر اللوح.</li>
<li>تُترك مسافة للتمدد عند كل حدّ ثابت: جدار، عمود، عتبة.</li>
</ul>
<p>الفني يحدد التفاصيل بعد المعاينة عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>. المساحة والهدر في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a> و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">الفواصل</a>، ويُختار الفاصل بعد معرفة السماكة.</p>
<h3>العناية</h3>
<p>ماء ومنظف أرضيات عادي غير كاشط، وألصق لبّاداً تحت أرجل الكراسي.</p>
<h3>متى لا يناسبك؟</h3>
<ul>
<li>تريد الشراء فوراً دون مراسلة، والمواصفة ناقصة.</li>
<li>تقارن بين تصميمين بالأرقام، ولا أرقام هنا.</li>
<li>تبحث عن دفء الخشب تحت القدم، فكل SPC صلب وبارد نسبياً.</li>
</ul>
<p>نظرة أوسع في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pq-spc-tile' => array( 'دليل بلاطات SPC الرخامية', '<h3>ما هي بلاطات SPC بشكل الرخام والحجر؟</h3>
<p>الخامة نفسها التي تُصنع منها شرائح باركيه SPC، لكن بنقشة رخام أو حجر أو إسمنت أو تيرازو بدل الخشب. تأتي في هذه المجموعة بشكلين: بلاطة 30 × 60 سم بسماكة 5 ملم يغطي كرتونها 1.99 م²، وشريحة طويلة 1220 × 183 مم بسماكة 4 ملم مع عازل IXPE 1 ملم مطبوعة بنقشة رخامية. البلاطة 30 × 60 تغطي 0.18 م²، فالمتر يحتاج خمس بلاطات ونصفاً تقريباً. المنشأ الصين، والتركيب تعشيق دون غراء ولا ترويب.</p>
<h3>أين تصلح وأين لا؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>المطبخ</td><td>مناسب</td><td>النواة لا تمتص الماء، وشكل الحجر مألوف فيه</td></tr>
<tr><td>المدخل والممر والصالة</td><td>مناسب</td><td>مظهر رخام دون تكسير البلاط القائم</td></tr>
<tr><td>مكتب أو معرض</td><td>مناسب</td><td>تركيب سريع، واسأل عن طبقة الحماية للحركة الكثيفة</td></tr>
<tr><td>الحمام وغرفة الغسيل</td><td>اسأل قبل الطلب</td><td>ليست سيراميكاً مروَّباً: الماء ينفذ من الوصلات ويستقر تحتها</td></tr>
<tr><td>الجدران</td><td>لا</td><td>منتج أرضيات عائم</td></tr>
<tr><td>الحوش والسطح</td><td>لا</td><td>لا تتحمل الشمس والمطر</td></tr>
</tbody>
</table>
<h3>بلاطة SPC أم سيراميك؟ وبلاطة أم شريحة خشبية؟</h3>
<p>أمام السيراميك تكسب السرعة والنظافة: لا تكسير ولا أسمنت، وتمشي عليها يوم التركيب، وهي أدفأ قليلاً. وتخسر أنها لا تُغسل بالماء الجاري ولا تصلح لحوض الاستحمام. وأمام <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%b4%d8%b1%d8%a7%d8%a6%d8%ad/">الشرائح الخشبية</a> الفرق في الشكل فقط، والخامة والأحكام واحدة. بقية التصاميم في قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%a8%d9%84%d8%a7%d8%b7%d8%a7%d8%aa/">بلاطات SPC</a>.</p>
<h3>التركيب</h3>
<ul>
<li><strong>الرصّ:</strong> البلاطة 30 × 60 تُرصّ غالباً بتخالف النصف أو الثلث، ويُتفق على النمط قبل البدء لأن تطابق العروق يتغير معه.</li>
<li><strong>الأرضية:</strong> النقشة الرخامية الفاتحة اللامعة تكشف أي تموج تحتها أكثر من النقشة الخشبية.</li>
<li><strong>التوزيع:</strong> تُخلط البلاطات من كراتين عدة حتى لا تتكرر العروق متجاورة.</li>
<li><strong>الأطراف:</strong> يُترك فراغ للتمدد عند الجدران، ولا تُروَّب الوصلات.</li>
</ul>
<p>للتنفيذ <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، وللعدد <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>كم بلاطة تحتاج؟</h3>
<p>مطبخ 3 × 4 أمتار مساحته 12 م². مع هدر 10% تصير 13.2 م²، أي 74 بلاطة من مقاس 30 × 60، أو 7 كراتين إن كان الكرتون يغطي 1.99 م². المطبخ الذي فيه خزائن مبنية تُحسب مساحته المكشوفة فقط، فالبلاطات لا تُفرد تحت الخزائن. والرصّ المائل يرفع الهدر إلى نحو 15%.</p>
<h3>يُطلب معها</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%b3%d9%8a%d8%b1%d8%a7%d9%85%d9%8a%d9%83/">نعلة بشكل السيراميك</a> تليق بالنقشة الحجرية، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل</a> عند التقائها بأرضية أخرى.</p>
<h3>العناية</h3>
<p>اللون الفاتح يُظهر آثار الأحذية، فيُمسح بماء ومنظف متعادل. لا مبيّض مركّز ولا حمض تنظيف البلاط.</p>
<h3>عيوبها</h3>
<ul>
<li>النقشة مطبوعة تتكرر كل عدد من البلاطات، وليست عروق رخام حقيقية.</li>
<li>صوتها تحت الكعب يختلف عن الحجر.</li>
<li>لا تناسب مكاناً يُغسل بالخرطوم.</li>
<li>في بعض التصاميم اسأل: هل هو بلاطة أم شريحة؟</li>
</ul>' ),
	'pq-turkish' => array( 'دليل الباركيه التركي 8 ملم', '<h3>ما هو الباركيه التركي 8 ملم؟</h3>
<p>مجموعة صغيرة من تسعة تصاميم بنقشة خشبية، بين الأبيض الخشبي والبيج والعسلي والبني المحروق والرمادي. اللوح بسماكة 8 ملم ومقاسه 126 × 18 سم، والتصاميم التي تذكر التعبئة يغطي كرتونها مترين مربعين. يُركَّب بالتعشيق فوق الأرضية القائمة. خامة القلب ودرجة الاحتكاك تُسألان من الفريق؛ الأصل في باركيه بهذه السماكة أنه لامينيت بقلب HDF يتأثر بالماء، وهذا ما يُبنى عليه الاختيار حتى يثبت غيره.</p>
<h3>أين يُركَّب؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">لماذا</th></tr>
</thead>
<tbody>
<tr><td>غرف النوم والمعيشة</td><td>مناسب</td><td>مكان جاف وحركة منزلية عادية</td></tr>
<tr><td>شقة مؤجَّرة أو مفروشة</td><td>مناسب</td><td>يُفرد فوق البلاط دون تكسير</td></tr>
<tr><td>المدخل الداخلي</td><td>مقبول</td><td>مع سجادة تلتقط الرمل والماء من الأحذية</td></tr>
<tr><td>المطبخ والحمام</td><td>لا</td><td>لا نعِد بمقاومة ماء غير مؤكدة</td></tr>
<tr><td>الخارج</td><td>لا</td><td>للاستخدام الداخلي فقط</td></tr>
</tbody>
</table>
<h3>مجموعة صغيرة: ماذا يعني ذلك لك؟</h3>
<p>تسعة ألوان فقط تعني أن إكمال الكمية لاحقاً من اللون نفسه غير مؤكد. اطلب كل ما تحتاجه دفعة واحدة مع نسبة الهدر، واحتفظ بما يزيد لإصلاح أي لوح مستقبلاً. وإن لم تجد درجتك بين التسعة فالتشكيلة الأوسع في <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b5%d9%8a%d9%86%d9%8a/">الباركيه الصيني</a> و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%a7%d9%84%d9%85%d8%a7%d9%86%d9%8a/">الألماني</a>، وكلاهما يُركَّب بالطريقة نفسها.</p>
<h3>ما يلزم للتركيب</h3>
<ul>
<li>بلاط ثابت لا يتحرك ولا يطقطق، وفروق منسوبه معالَجة.</li>
<li>طبقة عازلة تحت الألواح.</li>
<li>مسافة تمدد على المحيط تختفي تحت النعلة.</li>
<li>قصّ أسفل الأبواب إن لزم، فارتفاع الأرضية يزيد بسماكة اللوح والعازل.</li>
</ul>
<p>هذه النقطة الأخيرة يغفل عنها كثيرون: قِس الفراغ تحت الباب قبل الطلب. المساحة تُحسب في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتركيب متاح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما تطلبه معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلات</a> للمحيط، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فواصل</a> للأبواب ولالتقاء الباركيه بالسيراميك.</p>
<h3>العناية</h3>
<p>مكنسة ناعمة مرتين في الأسبوع، وممسحة مبللة قليلاً عند الحاجة. لا تترك أصيص زرع أو وعاء ماء على الأرض مباشرة، وضع لبّاداً تحت أرجل الأثاث يحمي السطح من الخدش.</p>
<h3>عيوبه بصراحة</h3>
<ul>
<li>خامة القلب ودرجة التحمّل تُؤكَّدان من الفريق.</li>
<li>خياراته محدودة، وتوفر اللون مستقبلاً غير مؤكد.</li>
<li>مثل كل لامينيت، لا يحب الماء ولا يُصنفر.</li>
</ul>
<p>لمقارنته ببقية الأرضيات راجع <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'pt-inner' => array( 'دليل البارتيشن الداخلي الخشبي', '<h3>ما هو البارتيشن الداخلي الخشبي؟</h3>
<p>عمود فاصل ديكوري من WPC، أي مركّب الخشب والبلاستيك، بمقطع مستطيل مجوّف ومظهر خشبي، وألوانه بين البلوط الفاتح والجوزي والبني المحمر والرمادي. استخدامه المذكور: فواصل المجالس والصالات، وخلفيات الاستقبال والمداخل. اسأل الفريق قبل الطلب عن مقاس المقطع وطول العمود وهل تأتي معه القواعد. فلا تطلب قبل أن تحصل على هذه الثلاثة مكتوبة.</p>
<h3>ما تسأل عنه قبل الطلب</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">السؤال</th><th scope="col">لماذا يهمك</th></tr>
</thead>
<tbody>
<tr><td>كم عرض المقطع وعمقه؟</td><td>العرض يدخل في حساب العدد، والعمق يحدد مقدار حجب الرؤية الجانبية</td></tr>
<tr><td>كم طول العمود؟</td><td>يجب أن يزيد على ارتفاع سقفك حتى يُقص عليه</td></tr>
<tr><td>هل معه قاعدتان؟</td><td>العمود بلا قاعدة علوية وسفلية لا يُثبَّت</td></tr>
<tr><td>كم سماكة جداره؟</td><td>الجدار الرقيق ينبعج أسرع</td></tr>
</tbody>
</table>
<h3>تخطيط الفاصل</h3>
<p>ابدأ من الباب: قف عند المدخل وانظر إلى ما تريد ستره، فخط الفاصل يوضع حيث يقطع هذا النظر. اترك ممراً لا يقل عن 90 سم بين نهاية الفاصل وأقرب جدار. وبعد أن تعرف عرض العمود: العدد = طول الفاصل ÷ (عرض العمود + الفراغ بين عمودين)، والفراغ المعتاد قريب من عرض العمود نفسه. كلما ضاق الفراغ زاد الستر وزاد العدد.</p>
<h3>التثبيت والارتفاع</h3>
<ul>
<li>كل عمود يُشدّ من أعلاه وأسفله ببراغٍ، لا باللاصق وحده.</li>
<li>حدّد نوع السقف مبكراً: الخرساني يُثقب مباشرة، والجبس المعلّق يحتاج دعماً فوقه أو عارضة تجمع الأعمدة.</li>
<li>الأرضية: الباركيه والبلاط يُثقبان، فاختر موضع الفاصل نهائياً قبل التنفيذ.</li>
<li>الطرف المقصوص يُجعل في الأعلى داخل القاعدة فلا يُرى.</li>
</ul>
<p>هذه التفاصيل يحسمها <a href="https://texadecore.store/install-services/">فريق التركيب</a> في المعاينة.</p>
<h3>أين لا يصلح؟</h3>
<p>هو داخلي كما يدل اسمه، فلا يوضع في حوش أو شرفة مكشوفة. ولا يقوم مقام درابزين الدرج، ولا يعزل صوتاً ولا رائحة.</p>
<h3>ما يُطلب معه</h3>
<p>القواعد إن لم تكن مشمولة. وإن أردت مقطعاً معروف المقاس فقارن الموديلات الأخرى في <a href="https://texadecore.store/product-category/%d8%a7%d8%b9%d9%85%d8%af%d8%a9-%d8%a8%d8%a7%d8%b1%d8%aa%d8%b4%d9%86/">أعمدة البارتشن</a>، وكثيرون ينسّقون لون الفاصل مع جدار من <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">بديل الخشب المضلع</a>.</p>
<h3>العناية</h3>
<p>مسح جاف منتظم، وقماشة مبللة قليلاً عند اللزوم.</p>
<h3>عيوبه</h3>
<ul>
<li>حساب الكمية يحتاج المقاس من الفريق.</li>
<li>مجوّف لا يحمل رفاً ولا نبتة معلّقة.</li>
<li>إزالته تترك أثراً في الأرضية والسقف.</li>
</ul>' ),
	'pt-wpc' => array( 'دليل أعمدة البارتشن', '<h3>ما هي أعمدة البارتشن؟</h3>
<p>قوائم مجوّفة بمظهر الخشب تُصفّ واقفة بين الأرض والسقف، وبينها فراغات، فتفصل المدخل عن الصالة أو المجلس عن غرفة الطعام دون بناء جدار. اسأل عن خامة العمود الذي تختاره قبل الطلب. المتوفر ثلاثة أشكال:</p>
<table class="txa-family">
<thead>
<tr><th scope="col">المقطع</th><th scope="col">الطول</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>10 × 5 سم</td><td>3.90 م</td><td>يُباع العمود وحده</td></tr>
<tr><td>10 × 5 سم «شامل 2 قاعدة»</td><td>3.20 م</td><td>القاعدتان في الاسم، فأكّد أنهما للأعلى والأسفل</td></tr>
<tr><td>5 × 5 سم</td><td>3.90 م</td><td>أخف شكلاً ويمرر ضوءاً أكثر</td></tr>
</tbody>
</table>
<h3>كم عموداً؟</h3>
<p>عدد الأعمدة = طول الفاصل ÷ (عرض العمود الظاهر + الفراغ). فاصل طوله 3 أمتار بفراغ 10 سم يحتاج نحو 15 عموداً إذا واجهك الوجه العريض (10 سم)، ونحو 20 عموداً من مقطع 5 × 5 سم. وإذا أدرت العمود العريض فجعلت عمقه 10 سم ووجهه 5 سم حجب الرؤية من الجوانب أكثر، وزاد العدد إلى نحو 20. وأضف عموداً احتياطياً، فالقصّ الخاطئ لا يُصلَح.</p>
<h3>التثبيت في الأرض والسقف</h3>
<ul>
<li><strong>من الطرفين دائماً.</strong> العمود المثبت من أسفله فقط يميل ويسقط إن استند إليه أحد.</li>
<li><strong>في الأرض:</strong> قاعدة تُثبَّت ببراغٍ في البلاط أو الخرسانة. الثقب في بلاط جديد قرار لا رجعة سهلة فيه.</li>
<li><strong>في سقف خرساني:</strong> قاعدة علوية ببراغٍ وفيشر.</li>
<li><strong>في سقف جبس مستعار:</strong> لوح الجبس وحده لا يمسك. إما دعامة توضع فوقه قبل إغلاق السقف، أو وصول ببراغٍ طويلة إلى الخرسانة، أو عارضة علوية تجمع رؤوس الأعمدة وتُثبَّت في هيكل الجبس.</li>
<li><strong>القص:</strong> العمود أطول من أغلب الأسقف، فيُقص في الموقع. يُقاس الارتفاع عند موضع كل عمود لأن الأرض والسقف لا يتوازيان تماماً.</li>
</ul>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الاستخدام</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>ستر الصالة عن باب المدخل</td><td>مناسب</td><td>يحجب النظر المائل ويترك الضوء والتكييف</td></tr>
<tr><td>تقسيم صالة كبيرة</td><td>مناسب</td><td>بلا بناء ولا غبار</td></tr>
<tr><td>حاجز درج أو شرفة</td><td>لا</td><td>ليس درابزيناً ولا يتحمل الاستناد</td></tr>
<tr><td>عزل صوت أو رائحة مطبخ</td><td>لا</td><td>الفراغات تمرر كل شيء</td></tr>
<tr><td>بيت فيه أطفال صغار</td><td>بشروط</td><td>تثبيت بالبراغي من الطرفين وفراغ لا يزيد على 10 سم</td></tr>
</tbody>
</table>
<h3>ما يُطلب معه</h3>
<p>القواعد العلوية والسفلية إن لم تكن ضمن المنتج، وعارضة علوية للسقف الجبس. أخبر <a href="https://texadecore.store/install-services/">فريق التركيب</a> بنوع سقفك عند رفع المقاس، وأرسل طول الفاصل على الواتساب لنحسب لك العدد. بقية الألوان في <a href="https://texadecore.store/product-category/%d8%a7%d8%b9%d9%85%d8%af%d8%a9-%d8%a8%d8%a7%d8%b1%d8%aa%d8%b4%d9%86/">أعمدة البارتشن</a>.</p>
<h3>العناية</h3>
<p>الغبار يستقر على الأوجه الأربعة لكل عمود. منفضة أو قماشة جافة كل أسبوع، ورطبة للبقع.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>فاصل بصري فقط.</li>
<li>مجوّف، فيُخدش وينبعج بالضربة ولا يُعلَّق عليه شيء.</li>
<li>يترك ثقوباً في الأرض والسقف عند إزالته.</li>
<li>تنظيفه يأخذ وقتاً لكثرة الأعمدة.</li>
</ul>' ),
	'sb-3mm' => array( 'دليل بديل الشيبورد 3 ملم', '<h3>بديل الشيبورد 3 ملم: لوح للتجليد لا للستر</h3>
<p>أرق ألواح بديل الشيبورد: PVC بسماكة 3 ملم ومقاس 122 × 300 سم، يغطي 3.66 م²، ومصنوع في السعودية. يُستخدم بديلاً عن الشيبورد والخشب الصناعي في تجليد الجدران والخزائن والأبواب الداخلية. رقّته هي ميزته وعيبه معاً: يلتف ويُقص بسهولة، ولا يخفي شيئاً مما تحته.</p>
<h3>أين تظهر فائدة الرقّة؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الاستخدام</th><th scope="col">لماذا 3 ملم؟</th></tr>
</thead>
<tbody>
<tr><td>تلبيس ضلف الدواليب والأبواب القديمة</td><td>لا يزيد سماكة الضلفة فتبقى المفصلات والإغلاق كما هي</td></tr>
<tr><td>العمود الدائري والجدار المقوّس</td><td>ينثني حول الانحناء الواسع؛ جرّب قطعة على القطر الصغير أولاً</td></tr>
<tr><td>جوانب الخزائن والرفوف وكاونتر الاستقبال من الخارج</td><td>يُقص بالكتر على المقاس في الموقع</td></tr>
<tr><td>جدار ملساء لياسته أو لوح جبس</td><td>يعطي النتيجة نفسها بوزن أقل</td></tr>
<tr><td>سقف 3 أمتار</td><td>طوله 300 سم يغطيه بلا وصلة أفقية</td></tr>
</tbody>
</table>
<h3>وأين لا يصلح؟</h3>
<ul>
<li><strong>الجدار الخشن أو المتموج:</strong> كل حبّة رمل ونتوء معجون تطبع على وجهه.</li>
<li><strong>الممرات والأماكن المعرّضة للطَّرق:</strong> ينغمز بالضربة لأن خلفه لا شيء يسنده إلا اللاصق.</li>
<li><strong>أسطح العمل وأرفف تُسحب عليها الأغراض:</strong> ينخدش ويتقشر عند الحافة.</li>
<li><strong>قرب الموقد والفرن، وخارج البيت:</strong> الحرارة تموّجه سريعاً، وهو للاستخدام الداخلي فقط.</li>
<li><strong>كابينة الدش:</strong> يُمسح ويتحمل الرطوبة العادية، وما زاد عن ذلك اسأل قبل الطلب.</li>
</ul>
<h3>التركيب: السطح هو كل شيء</h3>
<p>السطح يُصنفَر ويُنظَّف حتى يصير أملس كالزجاج تقريباً. يُفرد اللاصق طبقة رقيقة متصلة على كامل المساحة، لأن النقاط والخطوط السميكة تظهر من الأمام كتلال صغيرة. يُضغط اللوح بأسطوانة مطاطية من الوسط إلى الخارج لطرد الهواء. على الضلف تُفك المقابض والمفصلات الظاهرة أولاً، ويُلف اللوح على الحافة أو تُغطى بشريط حافة. الأعمدة تُلبَّس من الخلف حيث تختفي الوصلة. <a href="https://texadecore.store/install-services/">خدمات التركيب</a> ترفع المقاس، و<a href="https://texadecore.store/quantity-calculator/">الحاسبة</a> تحسب ألواح الجدران.</p>
<h3>كم لوحاً لدولاب؟</h3>
<p>من لوح 122 × 300 سم تخرج ضلفتان متجاورتان بمقاس 50 × 240 سم، ويبقى شريط للجوانب. ارسم توزيع القطع على ورقة قبل القص حتى يسير اتجاه النقشة الخشبية طولياً في كل الضلف.</p>
<h3>ما يُطلب معه</h3>
<p>شريط أو قفلة للحواف المكشوفة، فواصل للجدران من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">إكسسوارات بديل الشيبورد</a> بعد التأكد من مناسبتها لسماكة 3 ملم، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. التصاميم الخشبية في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a8%d8%af%d9%8a%d9%84-%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af-%d8%ae%d8%b4%d8%a8%d9%8a/">بديل شيبورد خشبي</a>.</p>
<h3>العناية</h3>
<p>قماش ناعم رطب. على الضلف نظّف حول المقابض بلا نقع، فالماء المتسرب إلى الحافة يضعف اللاصق.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يفضح السطح الرديء تحته.</li>
<li>لا يتحمل ضربة مباشرة.</li>
<li>حوافه نقطة ضعفه إن تُركت بلا تغطية.</li>
<li>يتموّج بالحرارة القريبة.</li>
<li>لونه يتأثر إن وقعت عليه شمس النافذة ساعات كل يوم.</li>
</ul>
<p>للجدار العادي في مكان فيه حركة خذ لوحاً أسمك من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">القسم نفسه</a>.</p>' ),
	'sb-5mm' => array( 'دليل بديل الشيبورد 5 ملم', '<h3>ما هو بديل الشيبورد 5 ملم؟</h3>
<p>لوح تكسية رقيق يُلصق فوق الجدار القائم فيعطيه سطحاً جاهزاً بلون أو نقشة، سادة أو خشبية أو قماشية أو رخامية. أغلب ألواح هذه المجموعة من PVC، وكلها بسماكة 5 ملم. المقاس الأشيع 120 × 290 سم، وبعض التصاميم 122 × 290 سم، أي نحو 3.5 م² للوح الواحد. بهذا الطول يكسو اللوح الجدار من الأرض إلى السقف قطعة واحدة ما دام الارتفاع لا يزيد على 290 سم.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
