<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>خلفية التلفاز، واجهة المجلس، خلف السرير، المكاتب</td><td>مناسب</td><td>جدار داخلي جاف قليل الاحتكاك</td></tr>
<tr><td>الممرات والمداخل المزدحمة</td><td>مقبول</td><td>يتأثر بالطَّرق المتكرر أكثر من لوح 8 ملم</td></tr>
<tr><td>المطبخ وقرب المغاسل</td><td>اسأل قبل الطلب</td><td>يُبعد عن الموقد والفرن لأن الحرارة القريبة تليّنه، وراجع بند مقاومة الماء في مواصفات التصميم</td></tr>
<tr><td>جدار تضربه الشمس ساعات من واجهة زجاجية</td><td>غير مفضّل</td><td>يبهت لونه مع السنين</td></tr>
<tr><td>الجدران الخارجية والأرضيات</td><td>لا</td><td>لا يتحمل الشمس والمطر ولا المشي عليه</td></tr>
</tbody>
</table>
<h3>5 ملم أم 8 ملم؟</h3>
<p>الشكل بعد التركيب واحد والفرق في الصلابة. لوح 5 ملم أخف ويكفي جداراً مستوياً في مكان هادئ. أما الجدار غير المثالي أو الممر كثير الاحتكاك فالأنسب له لوح 8 ملم لأنه أصلب ويخفي التموج البسيط.</p>
<h3>التركيب: ماذا يحتاج جدارك؟</h3>
<ul>
<li><strong>سطح مستوٍ وجاف ونظيف.</strong> اللوح الرقيق يتبع شكل الجدار، فأي تموج تحته يظهر عليه. الجدار المتموج يُسوّى أولاً أو يُركَّب عليه هيكل.</li>
<li><strong>تثبيت باللاصق.</strong> يوزَّع لاصق مناسب للألواح على ظهر اللوح، ويُضبط أول لوح بميزان الماء لأن بقية الألواح تتبعه.</li>
<li><strong>فتحات الكهرباء تُقص قبل اللصق،</strong> فحدّد أماكن الأفياش والشاشة عند رفع المقاس.</li>
<li><strong>تعليق الشاشة والرفوف ممكن</strong> بشرط أن يمرّ الفيشر من اللوح إلى الخرسانة أو البلوك خلفه، فاللوح نفسه لا يحمل وزناً.</li>
<li><strong>التركيب شبه دائم.</strong> نزع اللوح يكسره غالباً ويقشّر الدهان تحته، وهذا يهم المستأجر.</li>
</ul>
<p>رفع المقاس والتنفيذ متاحان عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، والعدد تحسبه في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
