<tr><td>قفلة نهاية</td><td>تُنهي حافة آخر لوح عند طرف الجدار</td><td>واحدة لكل طرف مكشوف</td></tr>
<tr><td>قفلة زاوية</td><td>تغطي التقاء لوحين عند زاوية الجدار</td><td>واحدة لكل زاوية</td></tr>
