</tbody>
</table>
<p>الفواصل والقفلات في قسم <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">إكسسوارات بديل الشيبورد</a>، والنعلات في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، وكلها تُشترى منفصلة عن اللوح.</p>
<h3>العناية والتنظيف</h3>
<p>يُمسح اللوح بقطعة قماش ناعمة مبللة قليلاً ثم يُجفَّف. لا تستخدم المنظفات الكاشطة ولا المذيبات، فهي تؤثر في طبقة السطح.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>لا يُخفي تموج الجدار.</li>
<li>يبهت لونه تحت شمس مباشرة طويلة، والداكن السادة يُظهر البهتان أكثر من الفاتح والقماشي.</li>
<li>يلين إذا لاصق مصدر حرارة كالموقد والمدفأة.</li>
<li>لا يُفك ليُنقل إلى بيت آخر.</li>
<li>الفواصل والقفلات تكلفة إضافية على اللوح.</li>
</ul>
<p>فإن كنت مستأجراً ستنتقل قريباً، أو كان الجدار خارجياً، أو غير مستوٍ ولا تنوي تسويته، فقارن البدائل في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'sb-6mm' => array( 'دليل بديل الشيبورد 6 ملم', '<h3>بديل الشيبورد 6 ملم: السماكة الوسطى</h3>
<p>لوح تكسية داخلي بمقاس 120 × 290 سم في أغلب تصاميم المجموعة، ومنشؤه الصين. أكثر تصاميمه من PVC، ونحو ربعها «فوم بورد»، فراجع خانة الخامة في التصميم الذي يعجبك. يقع بين لوح 5 ملم الخفيف ولوح 8 ملم الصلب، وفيه تصاميم هرمية وسادة ومموجة.</p>
<h3>متى يكون 6 ملم هو الجواب؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">حال جدارك</th><th scope="col">الأنسب</th></tr>
</thead>
<tbody>
<tr><td>مستوٍ، وغرفة قليلة الحركة</td><td>5 أو 6 ملم، والفرق بينهما صغير</td></tr>
<tr><td>مستوٍ تقريباً، وغرفة معيشة يلعب فيها الأطفال</td><td>6 ملم</td></tr>
<tr><td>لياسة فيها تموج محسوس، أو ممر مزدحم</td><td>8 ملم</td></tr>
<tr><td>خزانة أو عمود مستدير</td><td>3 ملم</td></tr>
</tbody>
</table>
<p>بعبارة أبسط: اختره حين تريد لوحاً أمتن قليلاً من الرقيق دون وزن الثمانية وصعوبة قصّها.</p>
<h3>تقسيم الجدار قبل الشراء</h3>
<p>عرض اللوح 120 سم، فالجدار 4 أمتار يأخذ ثلاثة ألواح كاملة وقطعة 40 سم. أين تذهب هذه القطعة؟</p>
<ul>
<li><strong>في الطرف</strong> إن كان الطرف خلف ستارة أو خزانة.</li>
<li><strong>مقسومة على الجانبين</strong> (20 سم يميناً و20 يساراً) إن كان الجدار مكشوفاً، فيبدو التقسيم متناظراً.</li>
<li><strong>الفاصل على محور الشاشة أو بعيداً عنه؟</strong> اختر مسبقاً؛ فاصل يمر خلف منتصف التلفاز تماماً يبدو مقصوداً، وفاصل ينحرف عنه 15 سم يبدو خطأً.</li>
</ul>
<p>والتصاميم الهرمية تُراجَع فيها مطابقة رؤوس النقشة بين لوح وجاره قبل اللصق.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<p>يصلح لجدران المجالس وغرف النوم والمعيشة والمكاتب. في المطبخ يبتعد عن الموقد والفرن، وقرب المغاسل يُمسح ويتحمل الرطوبة العادية؛ داخل كابينة الدش اسأل قبل الطلب. لا يُركَّب على جدار خارجي ولا على أرضية، وإن ورد غير ذلك في وصف قديم فالمعتمد أنه داخلي فقط.</p>
<h3>التركيب</h3>
<p>الجدار نظيف جاف مستوٍ. اللاصق يُمَدّ على الظهر بتوزيع منتظم، ويُشدّ خيط أو ليزر شاقولي للّوح الأول. يُقص بكتر حاد على عدة مرّات أو بمنشار ناعم. التمديدات خلف الشاشة تُجهَّز قبل التكسية لا بعدها. فريق <a href="https://texadecore.store/install-services/">خدمات التركيب</a> يرفع المقاس ويقترح التقسيم، و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> تعطيك العدد.</p>
<h3>ما يُطلب معه</h3>
<p>فاصل لكل خط التقاء، قفلة لكل طرف مكشوف، وزاوية لكل ركن، من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">قسم الإكسسوارات</a>. تصاميم الهرمي في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a8%d8%af%d9%8a%d9%84-%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af-%d9%87%d8%b1%d9%85%d9%8a/">بديل شيبورد هرمي</a>، والنعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>.</p>
<h3>العناية</h3>
<p>مسح خفيف بقماش مبلول معصور. لا يُغسل بالماء الجاري ولا بالبخار. آثار الأصابع قرب المفاتيح تزول بصابون سائل مخفف.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>ليس صلباً كفاية لممر محل تجاري.</li>
<li>لا يخفي ميلاً واضحاً في الجدار.</li>
<li>خامته تختلف بين تصميم وآخر في المجموعة نفسها.</li>
<li>حساس للحرارة القريبة وللشمس المباشرة الطويلة.</li>
<li>نزعه بعد اللصق يتلفه.</li>
</ul>
<p><a href="https://texadecore.store/buying-guide/">دليل الشراء</a> يقارن لك البدائل إن لم يوافق حالتك.</p>' ),
	'sb-8mm' => array( 'دليل بديل الشيبورد 8 ملم', '<h3>ما الذي يميز بديل الشيبورد 8 ملم؟</h3>
<p>أسمك ألواح بديل الشيبورد في المتجر وأصلبها. أغلب تصاميم هذه المجموعة من PVC بمقاس 120 × 290 سم، وبعضها 122 × 290 سم، فاللوح يغطي نحو 3.5 م². منشأ أكثرها الصين، ونقشاتها قماشية وخشبية وسادة ومخططة. الزيادة في السماكة لا تُرى بعد التركيب، لكنها تُحَسّ عند الطَّرق على الجدار وتظهر في استقامة السطح.</p>
