<h3>التركيب: ما يتغير مع 8 ملم</h3>
<ul>
<li><strong>الوزن أكبر</strong>، فتُزاد كمية اللاصق ويُسند اللوح حتى يمسك، وحمله يحتاج شخصين.</li>
<li><strong>القص بمنشار</strong> ناعم الأسنان لا بالكتر، وتُنعَّم الحافة بعده.</li>
<li><strong>الأفياش تغور 8 ملم</strong> خلف الوجه الجديد؛ اطلب حلقات تطويل لعلب الكهرباء.</li>
<li><strong>حلوق الأبواب والنعلات القائمة:</strong> اللوح قد يبرز عنها، فتُخطَّط القفلة عند كل التقاء.</li>
<li><strong>تعليق الشاشة والرفوف:</strong> الفيشر يمرّ إلى الخرسانة خلف اللوح، فاختر برغياً أطول بقدر السماكة المضافة.</li>
<li><strong>الفواصل والقفلات</strong> تُختار بمجرى يناسب 8 ملم؛ تأكد من ذلك عند الطلب.</li>
</ul>
<p>للرفع والتنفيذ <a href="https://texadecore.store/install-services/">خدمات التركيب</a>، ولحساب العدد <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>ما يُطلب معه</h3>
<p>فواصل بين الألواح، قفلات نهاية وزوايا من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">إكسسوارات بديل الشيبورد</a>، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>. وإن أردت الأرق للجدران الهادئة فكل السماكات في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">قسم بديل الشيبورد</a>.</p>
<h3>العناية</h3>
<p>يُمسح بقماش رطب ويُجفَّف؛ يتحمل الرطوبة العادية. آثار الأحذية والحقائب في الممرات تزول بصابون سائل مخفف، بلا إسفنجة خشنة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>أثقل وأصعب قصاً، فتركيبه ليس عمل هاوٍ.</li>
<li>يأخذ من عمق الجدار ويُبرز مشكلة الأفياش والحلوق.</li>
<li>لا يلتف حول المنحنيات.</li>
<li>يلين قرب مصدر حرارة مباشر، ولونه يتأثر بشمس طويلة من واجهة زجاجية.</li>
<li>لا يعالج جداراً مائلاً أو رطباً.</li>
</ul>
<p>إن كان جدارك مستوياً والمكان هادئاً فلا داعي له. قارن في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'sb-acc' => array( 'دليل فواصل وقفلات بديل الشيبورد', '<h3>ما هذه القطع؟</h3>
<p>شرائح معدنية طويلة تُنهي عمل ألواح بديل الشيبورد وتستر حوافها. هي من الستيل، بطول 2.90 م للقطعة، وبألوان معدنية: فضي، ذهبي، برونزي، أسود. القطعة خفيفة (نحو نصف كيلو إلى كيلو حسب النوع). بدونها تبقى حافة اللوح المقصوصة ظاهرة مهما كان القص نظيفاً.</p>
<h3>الأنواع وكم تحتاج</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القطعة</th><th scope="col">أين تُركَّب</th><th scope="col">العدد</th></tr>
</thead>
<tbody>
<tr><td>فاصل</td><td>بين كل لوحين متجاورين</td><td>عدد ألواح الجدار ناقص واحد</td></tr>
<tr><td>فاصل ليد</td><td>مكان الفاصل العادي حيث تريد خط إضاءة</td><td>حسب التصميم؛ غالباً اثنان إلى أربعة في جدار التلفاز</td></tr>
<tr><td>قفلة نهاية</td><td>عند طرف آخر لوح إذا انتهى قبل الزاوية أو عند حلق باب</td><td>واحدة لكل طرف مكشوف</td></tr>
<tr><td>قفلة زاوية</td><td>حيث يلتف التكسية على ركن خارجي أو داخلي</td><td>واحدة لكل ركن</td></tr>
</tbody>
</table>
<p>الحساب مبني على أن القطعة 2.90 م تغطي ارتفاع لوح واحد. إن كان سقفك أعلى من ذلك احتجت وصلة، فاذكر الارتفاع عند الطلب.</p>
<h3>اختيار اللون</h3>
<ul>
<li><strong>الذهبي والبرونزي</strong> مع البيج والخشبي والقماشي الدافئ.</li>
<li><strong>الفضي</strong> مع الرمادي والأبيض.</li>
<li><strong>الأسود</strong> يرسم خطوطاً واضحة تقسّم الجدار؛ جميل مع السادة الفاتح، وثقيل مع النقشة المزدحمة.</li>
<li>وحّد اللون في الغرفة كلها، وطابقه مع مقابض الأبواب وإطار الشاشة إن أمكن.</li>
</ul>
<h3>فاصل الليد: خطّط للكهرباء قبل اللصق</h3>
<p>خط الإضاءة يحتاج مصدر تغذية ومحوّلاً ومكاناً يختبئ فيه، ومفتاحاً أو ريموت. كل هذا يُمدَّد قبل تركيب الألواح. اسأل عند الطلب: هل الشريط الضوئي والمحوّل ضمن القطعة أم يُشتريان منفصلين؟ وما لون الإضاءة؟</p>
<h3>التركيب</h3>
<p>يُثبَّت الفاصل مع الألواح لا بعدها: يُلصق اللوح الأول، ثم الفاصل على حافته، ثم اللوح الثاني. يُقص المعدن بمنشار حديد أو صاروخ بقرص رفيع وتُبرَد حافته. تأكد أن مجرى القطعة يناسب سماكة لوحك (3، 5، 6 أو 8 ملم) قبل الشراء. التنفيذ مع الألواح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>العناية</h3>
<p>قماش جاف أو رطب قليلاً. المنظفات الحمضية والكلور تبقّع الطلاء المعدني، والسلك يخدشه.</p>
<h3>ملاحظات صريحة</h3>
<ul>
<li>تُشترى منفصلة عن الألواح وتُحسب في الميزانية من البداية.</li>
<li>الخدش على السطح المصقول يظهر، فاحذر عند نقل الأثاث.</li>
<li>الفاصل الأسود والذهبي اللامع يُظهران بصمات الأصابع.</li>
<li>في المجموعة قطعة زخرفية من فوم البولي يوريثان (20 × 126 سم) تختلف عن الشرائح المعدنية؛ هي حلية جدارية تُبعد عن اللهب والحرارة.</li>
</ul>
<p>الألواح نفسها في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">قسم بديل الشيبورد</a>، وبقية القطع في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">الإكسسوارات</a>.</p>' ),
	'sb-na' => array( 'دليل ألواح بديل الشيبورد (تأكيد السماكة)', '<h3>عن هذه المجموعة</h3>
<p>ألواح بديل شيبورد تُسأل عن سماكتها قبل الطلب. أغلبها سلسلة بأكواد MF بمظهر قماشي وخشبي، وهي ألواح PVC لتكسية الجدران الداخلية تُباع باللوح. لهذا فالدليل هنا قصير، وأهم ما فيه: لا تطلب قبل أن تعرف رقمين.</p>
<h3>اسأل عن هذين الرقمين أولاً</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الرقم</th><th scope="col">لماذا يهمك؟</th><th scope="col">ماذا تفعل به؟</th></tr>
</thead>
<tbody>
<tr><td>السماكة (3، 5، 6 أو 8 ملم)</td><td>تحدد الصلابة وهل يستر اللوح تموج الجدار</td><td>طابقها مع الجدول التالي</td></tr>
<tr><td>مقاس اللوح (العرض × الطول)</td><td>يحدد عدد الألواح وهل يغطي الارتفاع قطعة واحدة</td><td>أدخله في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a></td></tr>
</tbody>
</table>
<p>أرسل كود التصميم للفريق واطلب الرقمين مع صورة حقيقية للّوح.</p>
<h3>أي سماكة تناسب جدارك؟</h3>
