<tr><td>6 ملم</td><td>حل وسط لغرف المعيشة</td></tr>
<tr><td>8 ملم</td><td>الممرات والمحلات والجدار غير المثالي</td></tr>
</tbody>
</table>
<p>فإن جاءك الرد بسماكة لا تناسب مكانك، فالنقشة القماشية والخشبية نفسها موجودة تقريباً في بقية مجموعات <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">بديل الشيبورد</a>.</p>
<h3>ما نعرفه عنها يقيناً</h3>
<p>هي ألواح للاستخدام الداخلي: مجالس، غرف نوم، خلفيات تلفاز، مداخل، مكاتب. لا تُركَّب على جدار خارجي ولا أرضية. تُمسح وتتحمل الرطوبة العادية، وما عدا ذلك (جدار المغسلة، كابينة الدش) اسأل قبل الطلب. وتُبعد عن الموقد والمدفأة كأي لوح PVC.</p>
<h3>التركيب</h3>
<p>كبقية ألواح الفئة: جدار جاف مستوٍ، لاصق مناسب للألواح على الظهر، وأول لوح على ميزان. التفاصيل الدقيقة (قص بالكتر أم بالمنشار، حلقات تطويل للأفياش أم لا) تتبع السماكة، ولهذا يسبق السؤالُ الطلبَ. <a href="https://texadecore.store/install-services/">خدمات التركيب</a> ترفع المقاس وتؤكد المواصفة معك.</p>
<h3>ما يُطلب معه</h3>
<p>فواصل وقفلات من <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">قسم الإكسسوارات</a> بمجرى يوافق السماكة بعد معرفتها، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>.</p>
<h3>العناية</h3>
<p>قماش رطب معصور ثم تجفيف، بلا منظفات كاشطة.</p>
<h3>متى لا تناسبك؟</h3>
<ul>
<li>إن كنت تريد الطلب فوراً دون مراسلة: اختر تصميماً سماكته مكتوبة.</li>
<li>إن كان الجدار متموجاً ولم يتأكد لك أن اللوح 8 ملم.</li>
<li>إن كان المكان خارجياً أو ملاصقاً لحرارة.</li>
</ul>
<p><a href="https://texadecore.store/buying-guide/">دليل الشراء</a> يساعدك في المفاضلة.</p>' ),
	'sk-ceramic' => array( 'دليل نعلات الفايبر شكل السيراميك', '<h3>ما هي نعلة الفايبر بشكل السيراميك؟</h3>
<p>نعلة من فايبر PS (بوليسترين عالي الكثافة) مقطعها مسطّح مستقيم الحافة يحاكي نعلة السيراميك أو البورسلان، بدل المقطع المزخرف للنعلات الكلاسيكية. ما يميزها سماكتها: 2 إلى 2.5 سم في أغلب التصاميم (12 × 2.5، 12.4 × 2، 15 × 2 سم)، مقابل 1.2 إلى 1.5 سم للفايبر العادي. الطول 240 سم، والارتفاعات 12 و12.4 و14 و15 و22 سم. اللون أبيض غالباً ومعه أسود، والسطح مطلي جاهز ويقبل الدهان، والظهر مضلّع ليمسك الغراء.</p>
<h3>لماذا تختارها بدل سيراميك حقيقي؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">البند</th><th scope="col">نعلة فايبر شكل سيراميك</th><th scope="col">نعلة سيراميك مقصوصة</th></tr>
</thead>
<tbody>
<tr><td>التركيب</td><td>لصق نظيف بلا أسمنت</td><td>أسمنت أو لاصق بلاط وترويب</td></tr>
<tr><td>القص</td><td>بمنشار يدوي</td><td>بقطّاعة بلاط</td></tr>
<tr><td>الوصلات</td><td>كل 240 سم</td><td>كل 60 أو 120 سم بطول البلاطة</td></tr>
<tr><td>مع أرضية باركيه عائمة</td><td>تُعلَّق على الجدار وتترك الأرضية حرة</td><td>أثقل، وأسمنتها قد يقيّد الأرضية</td></tr>
<tr><td>تحمّل الصدمات والماء الجاري</td><td>أقل</td><td>أعلى</td></tr>
</tbody>
</table>
<h3>أي مقاس؟</h3>
<p>12 و12.4 سم هما الأقرب لارتفاع نعلات البلاط المعتادة، فيُختاران حين تريد أن تبدو النعلة جزءاً من الأرضية. 15 سم للصالات والأسقف التي تبلغ 3 أمتار. و22 سم مقاس وحيد في المجموعة، يُستعمل حين يُراد خط قوي أسفل جدار طويل. الأبيض يليق بأي أرضية، والأسود يحدّد الجدار الفاتح ويحتاج مسحاً أكثر. ومثال الكمية: غرفة محيطها الصافي 17 متراً تأخذ 8 أعواد.</p>
<h3>أين تصلح؟</h3>
<ul>
<li><strong>مناسبة:</strong> مع أرضيات الرخام والبورسلان وبلاطات SPC الحجرية، حيث يبدو المقطع المسطّح امتداداً للأرضية.</li>
<li><strong>مناسبة:</strong> المطبخ والممر، فهي تتحمل الرطوبة.</li>
<li><strong>اسأل أولاً:</strong> تغطية نعلة سيراميك قديمة دون خلعها. السماكة الأكبر توحي بذلك، لكن اسأل هل الظهر مجوّف بما يكفي.</li>
<li><strong>لا:</strong> داخل حيّز الدش ولا في الخارج.</li>
</ul>
<h3>التركيب</h3>
<ul>
<li>الحافة العليا المستقيمة تُظهر أي تعرّج في الجدار، فيُعبَّأ الفراغ فوقها بخط سيليكون أبيض رفيع.</li>
<li>الزوايا الخارجية تُقص 45 درجة بدقة، لأن المقطع السميك يكشف الخطأ.</li>
<li>إطار الباب الأرفع من النعلة يحتاج أن تُشطف نهايتها عنده.</li>
<li>تُلصق على سطح نظيف جاف بعد انتهاء الأرضية.</li>
</ul>
<p>للعدد <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، وللتنفيذ <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>معها</h3>
<p>لاصق وسيليكون بلون النعلة. وتليق بها <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc/%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87-%d8%b6%d8%af-%d8%a7%d9%84%d9%85%d8%a7%d8%a1-spc-%d8%a8%d9%84%d8%a7%d8%b7%d8%a7%d8%aa/">بلاطات SPC</a> إن كنت تجدّد الأرضية أيضاً. بقية التصاميم في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%b3%d9%8a%d8%b1%d8%a7%d9%85%d9%8a%d9%83/">نعلات السيراميك</a>.</p>
<h3>العناية</h3>
<p>الحافة العليا العريضة رفّ صغير للغبار، فمرّر عليها قماشة رطبة مع كل تنظيف للأرضية.</p>
<h3>عيوبها</h3>
<ul>
<li>ليست سيراميكاً: تُخدش وتنبعج بما لا يؤثر في البلاط.</li>
<li>بروزها عن الجدار أكبر، فقد تمنع التصاق قطعة أثاث به.</li>
<li>الكراتين من 17 إلى 23 عوداً، ووحدة البيع غير مكتوبة، فأكّد هل تُباع بالعود.</li>
</ul>' ),
	'sk-ext-foam' => array( 'دليل نعلات الفوم الحجري الخارجي', '<h3>ما هي نعلة الفوم الحجري الخارجي؟</h3>
<p>شريط عريض يُركَّب أسفل الواجهة أو سور الحوش، فيرسم قاعدة للجدار ويغطي التقاءه ببلاط الأرض. يتكون من قلب بوليسترين ممدّد خفيف تكسوه طبقة خارجية صلبة بملمس حجري. اللون أبيض ويُدهن بلون الواجهة. طول العود متران، لا 240 سم كالنعلات الداخلية، والارتفاعات من 10 إلى 30 سم، وأشيعها 15 و20 و25 سم. الصناعة محلية.</p>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>أسفل واجهة الفيلا والملحق</td><td>مناسب</td><td>هذا ما صُنعت له</td></tr>
<tr><td>سور الحوش من الداخل</td><td>مناسب</td><td>مع دهان خارجي يحمي السطح</td></tr>
<tr><td>جدار ملاصق لموقف السيارة</td><td>غير مفضّل</td><td>القلب خفيف، وصدمة المصدّ أو الباب تكسر القشرة</td></tr>
<tr><td>جدار ملامس لتربة الحديقة أو ماء راكد</td><td>اسأل قبل الطلب</td><td>الرطوبة الدائمة خلف النعلة تُضعف اللاصق</td></tr>
<tr><td>قرب الشواية والمدفأة الخارجية</td><td>لا</td><td>البوليسترين يتأثر بالحرارة العالية واللهب</td></tr>
<tr><td>داخل الغرف</td><td>ممكن</td><td>لكن النعلات الداخلية أنعم سطحاً وأدق تفصيلاً</td></tr>
</tbody>
</table>
<h3>خارجي حجري أم نعلة داخلية؟</h3>
<p>لا تُستبدل إحداهما بالأخرى. <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%af%d8%a7%d8%ae%d9%84%d9%8a%d8%a9/">النعلات الداخلية</a> من فوم أو فايبر بسطح أملس مطلي لم يوضع للشمس والمطر. والخارجية أخشن ملمساً وأعرض مقطعاً، وتُدهن بدهان الواجهة. وإن كانت الواجهة كلها ستُكسى فانظر أيضاً <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a>.</p>
<h3>التركيب: ماذا يحتاج الجدار؟</h3>
<ul>
<li>لياسة سليمة جافة غير مفتّتة. الدهان القديم المتقشر يُكشط أولاً.</li>
<li>لاصق مخصص للاستخدام الخارجي يوزَّع على ظهر العود كاملاً، ويحدد نوعه الفني.</li>
<li>الوصلة بين عودين تُعبَّأ وتُدهن حتى لا يدخلها ماء المطر.</li>
<li>يُدهن المنتج خلال شهر من تركيبه، ويُبعد عن الأحماض ومنظفات البلاط القوية.</li>
<li>يُترك أسفلها فراغ صغير عن بلاط الحوش أو يُعزل، حتى لا تقف في ماء الغسيل.</li>
</ul>
<p>عدد الأعواد: طول الواجهة ناقص الأبواب، مقسوماً على 2، مع الهدر. مثال: واجهة 12 متراً فيها باب 1.2 متر وبوابة كراج 3 أمتار، صافيها 7.8 أمتار، أي 4 أعواد، وتُطلب 5 تحسّباً للقص عند الأركان. استخدم <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما الذي يُطلب معها؟</h3>
<p>دهان خارجي، ومعجون وصلات خارجي، ولاصق، وعود إضافي لقصّ الأركان الخارجية. المقاسات كلها في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d9%81%d9%88%d9%85-%d8%ad%d8%ac%d8%b1%d9%8a-%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a/">نعلات الفوم الحجري الخارجي</a>.</p>
<h3>العناية</h3>
<p>تُغسل بماء عادي وفرشاة ناعمة بعد أن يجف دهانها تماماً. لا يُستعمل عليها الفلاش ولا حمض تنظيف البلاط، ويُجدَّد دهانها مع دهان الواجهة.</p>
<h3>عيوبها ومتى لا تناسبك</h3>
<ul>
<li>لا تتحمل الصدمات القوية، والكسر يُرمَّم ولا يختفي تماماً.</li>
<li>تحتاج دهاناً بعد التركيب، وليست جاهزة اللون.</li>
<li>العود متران، فالوصلات أكثر منها في النعلة الداخلية.</li>
<li>اسأل عن سماكتها وبروزها عن الجدار إن كان بجوارها باب أو ممر ضيق.</li>
</ul>' ),
	'sk-fiber' => array( 'دليل نعلات الفايبر', '<h3>ما هي نعلات الفايبر PS؟</h3>
<p>النعلة (الوزرة) شريط يُلصق أسفل الجدار، يغطي التقاءه بالأرضية ويحميه من الممسحة وأرجل الأثاث. «الفايبر» في السوق اسم لبوليسترين مضغوط عالي الكثافة (PS)، مصمت وأصلب من الفوم. العود في هذه المجموعة طوله 240 سم. الارتفاع الأشيع 12 سم، ثم 10 و15 سم، مع مقاسات أقل انتشاراً من 7.5 إلى 20 سم، والسماكة بين 1.2 و1.5 سم في أغلبها. الألوان أبيض وأسود أساساً، ومعها رخامي ومعدني فضي وذهبي وملوّن كلاسيكي. بعض التصاميم يذكر أن ظهرها مضلّع ليمسك اللاصق.</p>
<h3>أي ارتفاع تختار؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الارتفاع</th><th scope="col">يناسب</th><th scope="col">ملاحظة</th></tr>
</thead>
<tbody>
<tr><td>7.5 إلى 10 سم</td><td>غرفاً صغيرة وسقفاً منخفضاً وطرازاً بسيطاً</td><td>لا تغطي نعلة سيراميك قديمة</td></tr>
<tr><td>12 سم</td><td>أغلب الغرف بسقف 2.8 إلى 3 أمتار</td><td>الأوسع ألواناً في المجموعة</td></tr>
<tr><td>13.5 إلى 15 سم</td><td>المجالس والصالات والجدران ذات البانوهات</td><td>تُظهر تموج الأرض إن وُجد</td></tr>
<tr><td>17 إلى 20 سم</td><td>أسقفاً عالية وطرازاً كلاسيكياً</td><td>خيارات قليلة</td></tr>
</tbody>
</table>
<h3>أين تصلح وأين لا؟</h3>
<ul>
<li><strong>مناسبة:</strong> كل الغرف الداخلية فوق باركيه أو SPC أو رخام أو بلاط.</li>
<li><strong>مناسبة:</strong> المطبخ والممر الذي يُمسح يومياً، فالخامة لا تتشرّب ماء الممسحة.</li>
<li><strong>بشرط:</strong> الحمام، مع خط سيليكون أعلى النعلة وأسفلها.</li>
<li><strong>لا:</strong> الواجهات والأحواش، ولها <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d9%81%d9%88%d9%85-%d8%ad%d8%ac%d8%b1%d9%8a-%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a/">نعلات خارجية</a>.</li>
</ul>
<h3>فايبر أم فوم؟</h3>
<p>الفايبر أصلب أمام ضربة المكنسة ولونه جاهز، والأسود والرخامي لا يحتاجان دهاناً. الفوم أعلى مقاسات وأسهل ترميماً بالمعجون، لكنه أطرى. في ممر مزدحم أو بيت فيه أطفال وألعاب بعجلات نختار الفايبر.</p>
<h3>التركيب: ماذا يحتاج الجدار؟</h3>
<ul>
<li>جدار مستقيم جاف منتهٍ دهانه. التموج يترك فراغاً خلف النعلة يُسدّ بالسيليكون.</li>
<li>تُركَّب بعد الأرضية، وتُلصق على الجدار لا على الباركيه، حتى تبقى فجوة التمدد حرة تحتها.</li>
<li>الزوايا تُقص 45 درجة وتُعبَّأ وصلتها.</li>
<li>نوع اللاصق يحدده الفني، وغالباً غراء تركيب.</li>
</ul>
<p>المحيط ناقص الأبواب، مقسوماً على 2.4، هو عدد الأعواد قبل الهدر. احسبه في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> أو اطلب <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<p>مثال: غرفة 4 × 5 أمتار محيطها 18 متراً. اطرح باباً عرضه متر فيبقى 17 متراً، أي 7.1 عود، فتطلب 8، والزائد يغطي قصّ الزوايا.</p>
<h3>ما يُطلب معها</h3>
<p>لاصق ومعجون وصلات، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/%d9%81%d9%88%d8%a7%d8%b5%d9%84-%d9%88%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a7%d9%84%d8%a8%d8%a7%d8%b1%d9%83%d9%8a%d9%87/">فاصل نهاية</a> حيث تقف النعلة عند إطار باب أعرض منها. وحدة البيع تختلف بين الموديلات (متر طولي أو قطعة)، فتأكّد منها قبل الدفع.</p>
<h3>العناية</h3>
<p>قماشة رطبة. الأسود اللامع يُظهر الغبار وبقع الماء الجافة، فيُمسح أكثر.</p>
<h3>عيوبها</h3>
<ul>
<li>تُخدش بالاحتكاك الحاد، والخدش يظهر على الداكن.</li>
<li>الوصلة كل 240 سم تبقى مرئية إن لم تُعالَج.</li>
<li>الألوان المطلية لا تُدهن بسهولة إن غيّرت رأيك.</li>
</ul>
<p>كل المقاسات في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%b9%d8%a7%d8%af%d9%8a%d9%87/">النعلات العادية</a>.</p>' ),
	'sk-foam' => array( 'دليل نعلات الفوم', '<h3>ما هي نعلات الفوم؟</h3>
<p>نعلة بيضاء خفيفة تُلصق أسفل الجدار وتُدهن، وهي التي تعطي الشكل الكلاسيكي العالي مع البانوهات والأبواب البيضاء. في المجموعة خامتان: فوم محلي الصنع، وأربعة تصاميم من فوم بولي يوريثان (PU) يصفها المورّد بأنها عالية الكثافة وسطحها مطلي جاهز. طول العود 240 سم. الارتفاعات من 9 إلى 30 سم، وأكثرها 12 و15 و20 سم. تصاميم الـPU تأتي في كراتين من 23 إلى 66 عوداً بحسب المقاس.</p>
<h3>أين تصلح وأين لا تصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>المجلس وغرف النوم والصالة</td><td>مناسب</td><td>احتكاك قليل ومظهر كلاسيكي</td></tr>
<tr><td>فوق نعلة سيراميك قديمة</td><td>اسأل قبل الطلب</td><td>يلزم أن تكون أعلى منها وأن يسمح ظهرها بتغطيتها</td></tr>
<tr><td>ممر مزدحم وغرفة أطفال</td><td>غير مفضّل</td><td>ضربة المكنسة أو اللعبة تترك انبعاجاً</td></tr>
<tr><td>المطبخ</td><td>مقبول</td><td>لا تنتفخ بالماء، لكن الدهان يتأثر بالمنظفات القوية</td></tr>
<tr><td>الحمام والأماكن التي تُغسل</td><td>لا</td><td>الأنسب هناك نعلة فايبر أو سيراميك</td></tr>
<tr><td>الخارج</td><td>لا</td><td>للداخل فقط</td></tr>
</tbody>
</table>
<h3>أي ارتفاع يناسب غرفتك؟</h3>
<p>القاعدة البصرية أن تتناسب النعلة مع السقف: 9 إلى 12 سم لسقف نحو 2.8 متر، و15 سم لسقف 3 أمتار، و20 سم فأكثر للأسقف العالية والمجالس الواسعة ذات البانوهات. النعلة العالية في غرفة صغيرة تأكل من الجدار وتقصّر السقف في العين. وإن كانت ستغطي نعلة قديمة فاجعلها أعلى منها بسنتيمترين على الأقل.</p>
<h3>فوم عادي أم PU؟ وفوم أم فايبر؟</h3>
<p>الـPU أكثف، فيتحمل الصدمة أفضل من الفوم الأخف وتكون حوافه أحدّ بعد القص. الفوم العادي يكفي جداراً خلف كنبة أو سرير لا يلمسه أحد. و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%b9%d8%a7%d8%af%d9%8a%d9%87/">الفايبر</a> أصلب من الاثنين وألوانه جاهزة، لكنه لا يصل إلى ارتفاعات 25 و30 سم.</p>
<h3>التركيب: ماذا يحتاج الجدار؟</h3>
<ul>
<li>تُركَّب بعد الأرضية وبعد الوجه الأخير من دهان الجدار أو قبله بوجه، ليُدهن خط الالتقاء معها.</li>
<li>تُلصق بلاصق مناسب دون مسامير، وقد يُستخدم السيليكون.</li>
<li>النعلة العالية تكشف ميلان الأرض: تُضبط بميزان الماء، ويُسدّ الفراغ السفلي بالسيليكون.</li>
<li>الوصلات والزوايا تُعبَّأ بمعجون ثم تُدهن، وإلا ظهرت خطاً رمادياً.</li>
<li>مع الباركيه تُثبَّت في الجدار فقط.</li>
</ul>
<p>الأعواد تُحسب من محيط الغرفة في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، والتركيب والدهان عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما الذي يُطلب معها؟</h3>
<p>معجون ودهان بلون الأبواب أو الجدار، وقد تكمّلها <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%af%d9%8a%d9%83%d9%88%d8%b1/">إكسسوارات الديكور</a> من الطراز نفسه.</p>
<h3>العناية والتنظيف</h3>
<p>مسح خفيف بقماش رطب. الخدش أو الانبعاج الصغير يُعبَّأ بمعجون ويُدهن موضعياً، وهذه ميزتها على النعلات الجاهزة اللون.</p>
<h3>عيوبها ومتى لا تناسبك</h3>
<ul>
<li>أطرى من الفايبر والخشب.</li>
<li>غير المدهون منها يصفرّ مع الوقت.</li>
<li>تحتاج معجوناً ودهاناً بعد التركيب، أي يوم عمل إضافي.</li>
<li>الدهان يتجدد كل بضع سنوات.</li>
</ul>
<p>بقية الأنواع في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>.</p>' ),
	'sk-led' => array( 'دليل نعلات الإضاءة المخفية', '<h3>ما هي نعلة الإضاءة المخفية؟</h3>
<p>نعلة في مقطعها مجرى أو حافة بارزة يختبئ خلفها شريط إضاءة LED، فيخرج الضوء خطاً ناعماً على الأرض أو على الجدار دون أن يُرى مصدره. المجموعة 14 تصميماً من خامتين: فوم أبيض محلي الصنع بارتفاعات من 12 إلى 25 سم، وفايبر PS بارتفاعات 10 و12 و15 سم. طول العود 240 سم. اسأل هل يأتي شريط الإضاءة ومحوّله مع النعلة أم يُشتريان منفصلين، واحسم هذا قبل الدفع.</p>
<h3>قبل أن تطلبها: أربعة قرارات كهربائية</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">القرار</th><th scope="col">لماذا يُحسم مبكراً؟</th></tr>
</thead>
<tbody>
<tr><td>مصدر الكهرباء</td><td>يلزم مخرج قريب من أول النعلة، وتمديده بعد الدهان يعني تكسيراً</td></tr>
<tr><td>مكان المحوّل</td><td>يُخبأ في مكان يُفتح للصيانة، لا خلف نعلة ملصوقة</td></tr>
<tr><td>لون الضوء</td><td>الأبيض الدافئ للمجالس وغرف النوم، والأبيض المحايد للممرات</td></tr>
<tr><td>طريقة التشغيل</td><td>مفتاح مستقل أو حسّاس حركة للممر ليلاً</td></tr>
</tbody>
</table>
<h3>أين تصلح وأين لا؟</h3>
<ul>
<li><strong>مناسبة:</strong> الممرات، غرف النوم (ضوء ليلي لا يوقظ)، المدخل، خلف التلفاز، الدرج الداخلي.</li>
<li><strong>بشرط:</strong> فوق أرضية لامعة. الرخام والبورسلان المصقول يعكسان نقاط الـLED نقطة نقطة، فيلزم شريط كثيف النقاط أو غطاء ناشر.</li>
<li><strong>لا:</strong> الحمام ومحيط المغاسل، ففيها كهرباء قريبة من الأرض والماء.</li>
<li><strong>لا:</strong> الخارج.</li>
</ul>
<h3>التركيب</h3>
<ul>
<li>الكهربائي أولاً: يمدّ السلك ويجرّب الشريط قبل لصق أي عود.</li>
<li>الجدار والأرض يُفحصان بالميزان، فخط الضوء يفضح أي ميلان أكثر من النعلة العادية.</li>
<li>الأعواد تُلصق على الجدار، وتُعالَج الوصلات حتى لا يتسرب منها الضوء.</li>
<li>عند الزوايا يُلحم الشريط أو يوصَّل بوصلة ركن، ولا يُثنى بحدّة.</li>
<li>مع الباركيه تبقى النعلة معلّقة بالجدار والأرضية حرة تحتها.</li>
</ul>
<p>اسأل <a href="https://texadecore.store/install-services/">خدمات التركيب</a> هل تشمل التوصيل الكهربائي أم تحتاج كهربائياً من طرفك. عدد الأعواد من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>فوم أم فايبر في النعلة المضيئة؟</h3>
<p>الفوم يأتي بارتفاعات أكبر ويُدهن بلون الجدار، فيذوب فيه ويبقى الضوء وحده ظاهراً. الفايبر أصلب وسطحه جاهز، ويناسب ممراً تمرّ فيه المكنسة كل يوم. في الحالتين اسأل عن عمق المجرى وعرضه، فعليهما يتوقف أي شريط يدخل فيه.</p>
<h3>بإضاءة أم عادية؟</h3>
<p>النعلة المضيئة تكلفتها ليست في العود وحده: معها شريط ومحوّل وعمل كهربائي وصيانة لاحقة. إن أردت خطاً نظيفاً أسفل الجدار فقط فـ<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%b9%d8%a7%d8%af%d9%8a%d9%87/">النعلات العادية</a> تكفي. كثيرون يضعون المضيئة في الممر والمدخل والعادية في بقية البيت بالارتفاع نفسه. التصاميم كلها في قسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%a7%d8%b6%d8%a7%d8%a1%d9%87-%d9%85%d8%ae%d9%81%d9%8a%d8%a9/">نعلات الإضاءة المخفية</a>.</p>
<h3>العناية</h3>
<p>يُمسح المجرى من الغبار بفرشاة جافة والكهرباء مطفأة. لا يُرشّ ماء باتجاه النعلة عند غسل الأرض.</p>
<h3>عيوبها</h3>
<ul>
<li>شريط الـLED له عمر، وتبديله يحتاج وصولاً إلى المجرى.</li>
<li>تتجمع الأتربة في المجرى وتظهر مع الضوء.</li>
<li>تصاميم الفوم منها أطرى أمام الصدمات.</li>
<li>مقاس المجرى ونوع الشريط المناسب يُسأل عنهما قبل الطلب.</li>
</ul>' ),
	'st-pu' => array( 'دليل بديل الحجر', '<h3>ما هو بديل الحجر؟</h3>
<p>لوح فوم مصبوب في قالب مأخوذ عن حجر حقيقي، فيخرج بنتوءات الصخر وشقوقه. المقاس الأشيع في هذه المجموعة 120 × 60 سم (0.72 م² للوح)، ومنشأ أغلبها الصين. فيها خطان: ألواح بولي يوريثان PU بسماكة 2.5 سم، وألواح توصف بـ«الفوم الصخري» بسماكة 5 سم. وبعض التصاميم يأتي بطول 290 سم وعرض 60.</p>
<h3>الوزن والسماكة</h3>
<p>خفّته هي سبب وجوده: اللوح يُحمل بيد واحدة ويُلصق على لياسة عادية أو لوح جبس، بلا تسليح ولا مونة ولا خوف على الجدار من الحمل. اطلب الوزن بالأرقام إن كنت ستلصق على سقف أو قاطع خفيف.</p>
