<h3>كم لوحاً؟</h3>
<p>جدار 4 × 2.8 م مساحته 11.2 م²؛ قسمتها على 0.72 تعطي 16 لوحاً، وأضف لوحين للقص وتبديل الترتيب.</p>
<h3>التركيب</h3>
<p>يُلصق على لياسة جافة متماسكة. البلوك المكشوف يُفضَّل تلييسه أولاً لأن فراغاته تقلل التماسك. اللاصق بلا مذيبات، ويوزَّع على المحيط وخطوطاً في الوسط. الألواح السميكة تُسند من الأسفل حتى يمسك اللاصق. في الخارج يُضاف تثبيت ببراغٍ تُخفى رؤوسها بالمعجون. تُدار الألواح وتُبدَّل حتى لا تتكرر الصخرة نفسها. <a href="https://texadecore.store/install-services/">خدمات التركيب</a> تنفذ، و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> تحسب.</p>
<h3>ما يُطلب معه</h3>
<p>معجون فواصل بلون الحجر، لون ترميم، وزوايا للأركان. للجدران الخارجية قارن مع <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a> و<a href="https://texadecore.store/product-category/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%b7%d9%8a%d9%86%d9%8a%d8%a9-%d9%88%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/%d8%b5%d9%81%d8%a7%d8%a6%d8%ad-%d8%ad%d8%ac%d8%b1%d9%8a%d8%a9/">الصفائح الحجرية</a>. كل الألوان في <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ad%d8%ac%d8%b1/">قسم بديل الحجر</a>.</p>
<h3>العناية</h3>
<p>فرشاة ناعمة أو هواء مضغوط خفيف للغبار في الشقوق، وقماشة رطبة للسطح. في الخارج يُشطف برفق بلا ضغط عالٍ.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li><strong>قابل للاشتعال</strong> حتى لو بدا صخراً؛ يُبعد عن اللهب والحرارة.</li>
<li>ينبعج وتتقشر طبقة لونه بضربة زاوية طاولة.</li>
<li>الفواصل تظهر إن لم تُعالَج.</li>
<li>لونه في الخارج قد يتغير مع الشمس إن لم يكن معالَجاً.</li>
<li>لا يُحمَّل برفوف.</li>
</ul>
<p>لجدار مدفأة أو مكان يُصدم كثيراً اختر خامة أصلب من <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'wd-flat-5' => array( 'دليل التكسيات الخشبية 5 ملم', '<h3>ما هي التكسيات الخشبية 5 ملم؟</h3>
<p>تكسية جدارية رفيعة من ماركة RLUX، سماكتها 5 ملم، بمظهر خشبي وألوان عدة: أبيض وأزرق وبني وبيج ورمادي، ومعها موديل واحد بمظهر جلدي. خفيفة وسهلة القص والتنظيف. اسأل الفريق عن الخامة وعرض اللوح وطوله وهل سطحه أملس أم مضلّع. فالسماكة هي المعلومة المؤكدة الوحيدة، والباقي يُسأل عنه برمز الموديل.</p>
<h3>ماذا تعني سماكة 5 ملم؟</h3>
<p>اللوح الرقيق يأخذ شكل ما تحته. على جدار مستوٍ يعطي سطحاً نظيفاً ولا يُنقص من مساحة الغرفة شيئاً يُذكر، ويمرّ خلف المفاتيح وإطارات الأبواب دون تعديل كبير. وعلى جدار متموج يُظهر التموج نفسه، وتنفتح عند التقاء الألواح فراغات. وهو أضعف أمام الضربات من الألواح الأسمك، فمكانه الجدار الذي لا تحتكّ به الكراسي والعربات.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
