</tbody>
</table>
<h3>ما تسأل عنه قبل الطلب</h3>
<ul>
<li><strong>مقاس اللوح.</strong> العرض والطول يحددان العدد وأين تقع خطوط الالتقاء. قسّم عرض جدارك على عرض اللوح وقرّب للأعلى، ثم راجع الناتج في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</li>
<li><strong>شكل الحافة.</strong> هل الألواح تتلاصق مباشرة أم يفصل بينها فاصل؟ الجواب يغيّر شكل الجدار النهائي.</li>
<li><strong>الخامة.</strong> بها يُعرف اللاصق المناسب وحدود الحرارة والرطوبة.</li>
<li><strong>الموديل الجلدي.</strong> سطحه مختلف، فاسأل عن تنظيفه على حدة.</li>
</ul>
<h3>التركيب</h3>
<p>يُجهَّز الجدار أولاً: معجون للحفر، وصنفرة للنتوءات، وإزالة للدهان المتقشر، ثم يُترك ليجف. يُلصق اللوح بلاصق يلائم خامته ويُضغط بالتساوي حتى لا تبقى تحته جيوب هواء. فتحات المفاتيح تُقص قبل اللصق. وما يُعلَّق على الجدار يُثبَّت في البناء خلف اللوح. ولمن يفضّل التنفيذ الجاهز <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>قفلة للحافة المكشوفة وأخرى للزاوية من <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a> إن وافقت سماكة 5 ملم، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> تغطي التقاءه بالأرضية.</p>
<h3>العناية</h3>
<p>قطعة قماش ناعمة ورطبة، ثم تجفيف. لا إسفنجة خشنة ولا مواد مذيبة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>المقاس والخامة يُؤكَّدان من الفريق قبل الطلب.</li>
<li>يكشف عيوب الجدار بدل أن يسترها.</li>
<li>خطوط التقاء الألواح تبقى ظاهرة ما لم يغطّها فاصل.</li>
<li>ينبعج بالضربة القوية.</li>
<li>يُلصق لصقاً دائماً، ونزعه يتلفه.</li>
</ul>
<p>إن أردت عمقاً وظلالاً فانظر <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">بديل الخشب المضلع</a>، وإن أردت لوحاً عريضاً معروف المقاس فانظر <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%b4%d9%8a%d8%a8%d9%88%d8%b1%d8%af/">بديل الشيبورد</a>.</p>' ),
	'wd-fluted-12' => array( 'دليل بديل الخشب المضلع 12 سم', '<h3>ما هو بديل الخشب المضلع عرض 12 سم؟</h3>
<p>عود تكسية طولي بسطح مضلّع، يُلصق على الجدار الداخلي عوداً بجانب عود حتى يكتمل الجدار. عرض العود في هذه المجموعة 12 سم، وهو أضيق عروض المضلع عندنا، وسطحه بثلاثة أضلاع أو أربعة حسب الموديل، والطول 2.90 م. الخامة تختلف بين الموديلات (WPC أو PVC أو بوليسترين)، فاسأل عن خامة الموديل الذي اخترته قبل الطلب.</p>
<h3>كم عوداً يحتاج جدارك؟</h3>
<p>القاعدة: 100 ÷ عرض العود بالسنتيمتر = عدد الأعواد لكل متر طولي من الجدار. مع 12 سم الناتج 8.3، أي تسعة أعواد للمتر مع قصّ الأخير.</p>
<table class="txa-family">
<thead>
<tr><th scope="col">عرض الجدار</th><th scope="col">الحساب</th><th scope="col">عدد الأعواد</th></tr>
</thead>
<tbody>
<tr><td>2 م</td><td>200 ÷ 12 = 16.7</td><td>17</td></tr>
<tr><td>3 م</td><td>300 ÷ 12 = 25</td><td>25</td></tr>
<tr><td>4 م</td><td>400 ÷ 12 = 33.3</td><td>34</td></tr>
<tr><td>6 م</td><td>600 ÷ 12 = 50</td><td>50</td></tr>
</tbody>
</table>
<p>الجدول يفترض تركيباً عمودياً وارتفاعاً لا يتجاوز 2.90 م. وإن كانت حافة العود تتعشق في جاره فالعرض الظاهر بعد التعشيق أقل قليلاً من 12 سم، فأضف عوداً أو عودين. جرّب أرقام جدارك في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>متى تختار 12 سم؟</h3>
<p>العود الضيق يعطي إيقاعاً ناعماً متقارباً يليق بخلفية الشاشة والجدار الصغير، وبجوانب الأعمدة والبروزات التي لا يتسع وجهها لعود عريض. ثمن ذلك كثرة القطع: جدار 4 أمتار يأخذ 34 عوداً من هذا العرض مقابل 20 عوداً بعرض 20 سم، فيطول التركيب وتكثر خطوط الالتقاء.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>خلفية التلفاز، خلف السرير، جدار المكتب</td><td>مناسب</td><td>جدار داخلي جاف</td></tr>
<tr><td>وجه عمود أو بروز ضيق</td><td>مناسب</td><td>العود الضيق يُوزَّع عليه بلا قصّ طولي كثير</td></tr>
<tr><td>قرب الموقد أو المدفأة</td><td>لا</td><td>الحرارة القريبة تشوّه العود</td></tr>
<tr><td>مكان يصله رذاذ الماء</td><td>اسأل قبل الطلب</td><td>يتوقف على خامة الموديل</td></tr>
<tr><td>واجهة أو سور</td><td>لا</td><td>المجموعة داخلية</td></tr>
</tbody>
</table>
<h3>التركيب: ماذا يحتاج الجدار؟</h3>
<ul>
<li><strong>جدار مستوٍ وجاف ونظيف،</strong> والدهان المتقشر يُزال قبل اللصق.</li>
<li><strong>العود الأول بميزان الماء،</strong> فكل ميلان فيه يتكرر في عشرات الأعواد بعده.</li>
<li><strong>لاصق مناسب لخامة العود</strong> يوزَّع على ظهره، ومسار الأسلاك والأفياش يُحدَّد قبل اللصق لا بعده.</li>
<li><strong>حامل الشاشة يُثبَّت في الجدار نفسه</strong> بفيشر طويل يعبر العود، فالعود لا يحمل وزناً.</li>
</ul>
<p>إن أردت من يرفع المقاس وينفّذ فاطلب <a href="https://texadecore.store/install-services/">خدمة التركيب</a>.</p>
<h3>ما الذي يُطلب معه؟</h3>
<p>قفلة تُنهي الطرف المكشوف، وقفلة للزاوية الخارجة، ونعلة عند الأرض. تجدها في <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a> وقسم <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، وتأكد من مطابقة لونها ومقاسها لعودك.</p>
<h3>العناية</h3>
<p>الأضلاع تمسك الغبار، ففرشاة ناعمة أو مكنسة بفوهة الفرشاة أنفع من المسح، ثم قماشة رطبة عند الحاجة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>أكثر العروض قطعاً ووقتاً في التركيب.</li>
<li>عن قرب لا يطابق ملمس الخشب الطبيعي.</li>
<li>اللون الداكن يُظهر الغبار والخدوش.</li>
<li>نزعه بعد اللصق يتلفه غالباً.</li>
</ul>
<p>للجدار الواسع قارن العروض الأكبر في قسم <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">بديل الخشب المضلع</a>.</p>' ),
	'wd-fluted-16' => array( 'دليل بديل الخشب المضلع 16 سم', '<h3>ما هو بديل الخشب المضلع عرض 16 سم؟</h3>
<p>هو العرض الأوسط بين أعواد المضلع: 16 سم للعود، بخمسة أضلاع في أغلب الموديلات وثلاثة أضلاع أعرض في بعضها. الطول 2.90 م، والمنشأ الصين. أما الخامة فتختلف بين الموديلات، فلا تفترضها واسأل عنها.</p>
<h3>خمسة أضلاع أم ثلاثة؟</h3>
<p>خمسة أضلاع رفيعة تعطي ملمساً متقارباً قريباً من شكل العود الضيق. وثلاثة أضلاع عريضة تعطي خطوطاً أهدأ، وتنظيفها أيسر. ولا تجمع الموديلين على جدار واحد، فخطوطهما لا تلتقي.</p>
<h3>حساب الأعواد</h3>
<p>100 ÷ 16 = 6.25 عود لكل متر طولي من الجدار.</p>
<table class="txa-family">
<thead>
<tr><th scope="col">عرض الجدار</th><th scope="col">الناتج</th><th scope="col">تطلب</th><th scope="col">القطعة الأخيرة</th></tr>
</thead>
<tbody>
<tr><td>2 م</td><td>12.5</td><td>13 عوداً</td><td>نصف عود، 8 سم</td></tr>
<tr><td>3 م</td><td>18.75</td><td>19 عوداً</td><td>12 سم</td></tr>
<tr><td>4 م</td><td>25</td><td>25 عوداً</td><td>عود كامل بلا قصّ</td></tr>
<tr><td>5 م</td><td>31.25</td><td>32 عوداً</td><td>4 سم فقط</td></tr>
</tbody>
</table>
<p>انتبه للعمود الأخير: قطعة بعرض 4 سم في طرف الجدار تبدو شريطاً نحيلاً. الحل أن تبدأ من منتصف الجدار فيتوزع القصّ على الطرفين بالتساوي. وإن كانت الأعواد تتعشق فاحسب بالعرض الظاهر بعد التعشيق.</p>
<h3>رأسي أم أفقي؟</h3>
<table class="txa-family">
<thead>
