</thead>
<tbody>
<tr><td>رأسي</td><td>يرفع السقف بصرياً</td><td>الاختيار الافتراضي، والعود يغطي الارتفاع قطعة واحدة حتى 2.90 م</td></tr>
<tr><td>أفقي</td><td>يوسّع الجدار الضيق</td><td>تظهر وصلة إذا زاد عرض الجدار على 2.90 م، ويستقر الغبار فوق الأضلاع</td></tr>
<tr><td>مائل</td><td>شكل لافت لجدار واحد</td><td>القصّ عند الأطراف يرفع الهدر كثيراً</td></tr>
</tbody>
</table>
<p>السقف المنخفض يناسبه الرأسي. والأفقي يكشف أي ميلان في الأرضية أو السقف لأن العين تقارن خطوطه بهما.</p>
<h3>التركيب وخلفية التلفاز</h3>
<p>يُلصق العود بلاصق يناسب خامته على جدار داخلي مستوٍ وجاف. ولأن أكثر استعماله خلف الشاشة، خطّط قبل اللصق لثلاثة أشياء: مجرى الأسلاك، ومكان الأفياش، وموضع حامل الشاشة الذي يُثبَّت في البلوك أو الخرسانة لا في الأعواد. إضافة أي منها بعد اللصق تعني فكّ أعواد وإتلافها. الجدار المتموج يحتاج تسوية أو هيكلاً يُبرز التكسية بضعة سنتيمترات، وهذا يُحسم عند رفع المقاس مع <a href="https://texadecore.store/install-services/">فريق التركيب</a>.</p>
<h3>القطع المكمّلة</h3>
<p>الطرف المكشوف والزاوية الخارجة يحتاجان قفلة، وأسفل الجدار نعلة. راجع <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a> و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">النعلات</a>، واحسب الكمية كلها في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>التنظيف</h3>
<p>نفض الغبار بفرشاة جافة كل فترة يغني عن الغسل. البقع تُزال بقماشة مبللة قليلاً دون مواد كاشطة.</p>
<h3>عيوبه</h3>
<ul>
<li>لا يعزل الصوت، وإن خفّف الصدى قليلاً بسطحه غير المستوي.</li>
<li>أضلاعه تجمع الغبار أكثر من اللوح الأملس.</li>
<li>لا يُركَّب في الخارج ولا ملاصقاً لمصدر حرارة.</li>
<li>لا يُنقل معك إن غيّرت السكن.</li>
</ul>
<p>بقية العروض في قسم <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">بديل الخشب المضلع</a>.</p>' ),
	'wd-fluted-20' => array( 'دليل بديل الخشب المضلع 20 سم', '<h3>ما هو بديل الخشب المضلع عرض 20 سم؟</h3>
<p>عود مضلّع عريض نسبياً، كل عود يغطي 20 سم من الجدار. العرض 20 سم، وأغلب الموديلات من ماركة DJ. اسأل الفريق عن الطول والخامة للموديل المختار. لذلك اطلب الطول والخامة مكتوبين للموديل الذي تريده. بعض الموديلات يأتي بفواصل ملوّنة بين الأضلاع، ذهبية أو رمادية، وهي جزء من العود نفسه لا قطعة تُشترى معه.</p>
<h3>أسهل العروض حساباً</h3>
<p>100 ÷ 20 = 5 أعواد بالضبط لكل متر طولي من الجدار، فلا كسور: جدار 3 أمتار يأخذ 15 عوداً، و4 أمتار 20 عوداً، و6 أمتار 30 عوداً. الجدار الذي عرضه ليس متراً كاملاً، مثل 3.5 م، يأخذ 18 عوداً وتُقص من الأخير 10 سم. أضف عوداً احتياطياً للقصّ حول الأفياش، وأكّد الرقم في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
