<tr><td>تغطية باب مخفي في مستوى الجدار</td><td>مناسب</td><td>اجعل حدّ الباب عند التقاء عودين لا في منتصف عود</td></tr>
<tr><td>جدار أقل من مترين</td><td>مقبول</td><td>عشرة أعواد أو أقل، فيقلّ التكرار الذي يصنع شكل المضلع</td></tr>
<tr><td>حمّام أو مطبخ قرب الماء والنار</td><td>لا يُنصح</td><td>يتأثر بالإفراط في الماء</td></tr>
<tr><td>خارج البيت</td><td>لا</td><td>مجموعة داخلية</td></tr>
</tbody>
</table>
<h3>الإضاءة الخطية بين الأعواد</h3>
<p>يمكن ترك شقّ بين عودين يُركَّب فيه مجرى إضاءة رفيع، فيظهر خط ضوء من الأرض إلى السقف. قراره قبل التركيب لا بعده: يُحدَّد عدد الخطوط ومواضعها، ويُمدّ لها سلك من نقطة كهرباء، ويُختار مكان يُخفى فيه المحوّل ويمكن الوصول إليه. كل خط إضاءة يأخذ من عرض الجدار، فأدخله في الحساب. والضوء الدافئ أليق بالدرجات الخشبية من الأبيض البارد.</p>
<h3>ما يحتاجه السطح</h3>
<ul>
<li>جدار داخلي جاف، خالٍ من القشور والرطوبة.</li>
<li>استواء معقول: العود الأعرض أقل تسامحاً مع التموج من الضيق، وتظهر تحته فراغات.</li>
<li>لصق بمادة تناسب الخامة، مع ضبط أول عود شاقولياً.</li>
<li>أي شيء يُعلَّق يُثبَّت في الجدار خلف العود.</li>
</ul>
<p>القياس والتنفيذ عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>معه</h3>
<p>قفلات النهاية والزاوية في <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a>، وللأرضية نعلة عادية أو من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/%d9%86%d8%b9%d9%84%d8%a7%d8%aa-%d8%a7%d8%b6%d8%a7%d8%a1%d9%87-%d9%85%d8%ae%d9%81%d9%8a%d8%a9/">نعلات الإضاءة المخفية</a> إن أردت أن يكمل ضوء الأرض خطوط الجدار.</p>
<h3>العناية</h3>
<p>مسح بقماشة شبه جافة، والغبار بين الأضلاع يخرج بفرشاة. لا تغسله بماء جارٍ.</p>
<h3>عيوبه</h3>
<ul>
<li>السؤال عن الطول والخامة قبل الطلب ضروري.</li>
<li>على جدار صغير يبدو قليل التكرار.</li>
<li>يحتاج جداراً أكثر استواءً من الأعواد الضيقة.</li>
<li>خطوط الإضاءة تضيف أعمال كهرباء تسبق التركيب.</li>
<li>تركيبه شبه دائم.</li>
</ul>
<p>إن لم يناسبك فالعروض الأخرى في <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">قسم المضلع</a>.</p>' ),
	'wd-fluted-30' => array( 'دليل بديل الخشب المضلع 30 سم', '<h3>ما هو بديل الخشب المضلع عرض 30 سم؟</h3>
<p>أعرض أعواد المضلع في المتجر: القطعة الواحدة تكسو 30 سم من الجدار. موديلات هذه المجموعة من ماركة DJ، واسأل الفريق عن نوع الخامة وطول القطعة. فقبل أن تطلب، اسأل عن أمرين: الطول، وهل الخامة WPC أم PVC أم بوليسترين.</p>
<h3>عدد القطع</h3>
<p>100 ÷ 30 = 3.3 قطعة لكل متر طولي من الجدار، وهو أقل عدد بين كل العروض.</p>
