<tr><td>صالة واسعة، مدخل عالٍ، جدار درج</td><td>الأنسب</td><td>المساحة تتحمل القطعة العريضة وتُظهر تكرارها</td></tr>
<tr><td>محل أو استقبال مكتب</td><td>مناسب</td><td>تنفيذ سريع بقطع قليلة</td></tr>
<tr><td>جدار أقل من 2.4 م</td><td>غير مفضّل</td><td>ثماني قطع أو أقل، فيضيع إيقاع المضلع</td></tr>
<tr><td>عمود أو بروز صغير</td><td>لا</td><td>القطعة أعرض من الوجه فتُقص طولياً</td></tr>
<tr><td>جدار خارجي</td><td>لا</td><td>للخارج قسم <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa/%d8%a7%d9%84%d8%aa%d9%83%d8%b3%d9%8a%d8%a7%d8%aa-%d8%a7%d9%84%d8%ae%d8%a7%d8%b1%d8%ac%d9%8a%d8%a9/">التكسيات الخارجية</a></td></tr>
</tbody>
</table>
<h3>ما يخص العرض الكبير عند التركيب</h3>
<ul>
<li><strong>الاستواء أهم هنا.</strong> القطعة العريضة لا تنحني لتتبع الجدار، فإن كان فيه بطن أو نتوء بقي تحتها فراغ أو تأرجحت. افحص الجدار بمسطرة طويلة أولاً.</li>
<li><strong>القطعة الأخيرة.</strong> إن خرج الباقي شريطاً ضيقاً فوزّع القصّ على طرفي الجدار.</li>
<li><strong>الارتفاع.</strong> قارن ارتفاع جدارك بطول القطعة: إن زاد عليه لزمت وصلة عرضية تُخفى بفاصل أو تُجعل عند مستوى واحد.</li>
<li><strong>اللصق.</strong> مادة لاصقة تلائم الخامة موزعة على كامل الظهر، لأن المساحة الملصوقة أكبر.</li>
</ul>
<p>رفع المقاس وفحص الاستواء من مهام <a href="https://texadecore.store/install-services/">فريق التركيب</a>.</p>
<h3>واقفة أم نائمة؟</h3>
<p>القطعة العريضة واقفةً تعطي أعمدة واضحة ترفع الجدار. ونائمةً تشبه كسوة الخشب العريضة وتليق خلف السرير، لكن خطوطها قليلة ومتباعدة، فأي ميلان في القطعة السفلى يظهر في كل ما فوقها. اضبطها بالميزان قبل أن يجف اللاصق.</p>
<h3>الملحقات</h3>
<p>نهاية للطرف الظاهر، وزاوية حيث ينعطف الجدار، من <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a> بعد التأكد من توافقها. وعند الأرض <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a>.</p>
<h3>العناية</h3>
<p>أضلاعه الأعرض أسهل تنظيفاً من الضيقة: قماشة ناعمة مبللة قليلاً تكفي.</p>
<h3>عيوبه بصراحة</h3>
<ul>
<li>الطول والخامة يُؤكَّدان من الفريق قبل الطلب.</li>
<li>لا يسامح الجدار المتموج.</li>
<li>ثقيل الحضور على الغرف الصغيرة.</li>
<li>الخطأ في قصّ قطعة واحدة يُهدر مساحة كبيرة.</li>
</ul>
<p>للجدران الصغيرة ارجع إلى العروض الأضيق في <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">بديل الخشب المضلع</a>.</p>' ),
	'wd-fluted-na' => array( 'دليل التحقق من عرض العود قبل الطلب', '<h3>ما الذي يجمع هذه المجموعة؟</h3>
<p>أعواد بديل خشب مضلّع للجدران الداخلية، بعروض مختلفة. والعرض هو الرقم الذي يُبنى عليه عدد الأعواد كله، فهذا الدليل يعلّمك كيف تتحقق منه قبل الدفع. العروض 12 و15 و16 و20 سم، والطول 2.90 م. والخامة تختلف بين الموديلات: بوليسترين أو PVC أو WPC أو «فوم بورد»، فاسأل عن خامة الموديل المختار.</p>
<h3>خمسة أشياء تتحقق منها قبل الطلب</h3>
<ol>
<li><strong>العرض بالسنتيمتر.</strong> ابحث عنه في جدول المواصفات داخل الصفحة، فإن لم تجده فاسأل برمز الموديل.</li>
<li><strong>العرض الظاهر بعد التركيب.</strong> إن كان العود يتعشق في جاره فجزء من حافته يختفي، والحساب يكون بما يظهر لا بالعرض الكلي.</li>
<li><strong>الطول.</strong> قارنه بارتفاع جدارك حتى تعرف هل تلزمك وصلة.</li>
<li><strong>الخامة.</strong> اسأل عنها بالاسم، لأنها تحدد اللاصق وتحمّل الحرارة والرطوبة.</li>
<li><strong>الكمية دفعة واحدة.</strong> درجة اللون قد تختلف بين شحنة وأخرى، فاطلب حاجتك كلها مع عود أو عودين احتياطاً.</li>
</ol>
<h3>من العرض إلى العدد</h3>
<p>100 ÷ عرض العود بالسنتيمتر = عدد الأعواد لكل متر طولي من الجدار. ثم اضرب في عرض جدارك وقرّب للأعلى.</p>
