<p>الفرق بين عرضين متقاربين ليس هيّناً: من ظنّ العود 16 سم وهو 12 سم نقصه ستة أعواد في جدار 3 أمتار. بعد أن تعرف العرض أدخله في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>أين تُركَّب هذه الأعواد؟</h3>
