<tr><td>جدران المجالس والغرف وخلفيات الشاشات</td><td>مناسب</td></tr>
<tr><td>الأسقف</td><td>ممكن بتثبيت إضافي غير اللاصق، ويقرره الفني</td></tr>
<tr><td>قرب الماء المباشر أو مصدر حرارة</td><td>لا يُنصح قبل معرفة الخامة</td></tr>
<tr><td>الواجهات والأسوار والحدائق</td><td>لا، حتى لو وردت كلمة «خارجية» في وصف قديم</td></tr>
</tbody>
</table>
<h3>التركيب باختصار</h3>
<p>سطح مستوٍ وجاف، وأول عود مضبوط بالميزان، ولاصق يوافق الخامة التي تأكدت منها. الأفياش ومسارات الأسلاك تُحدَّد قبل اللصق. ولا تجمع موديلين مختلفي العرض على جدار واحد، فخطوط أضلاعهما لن تتطابق. وإن لم ترد أن تقيس بنفسك فاترك المعاينة لـ<a href="https://texadecore.store/install-services/">خدمة التركيب</a>.</p>
<h3>ما يُطلب معها</h3>
<p>قفلات الأطراف والزوايا من <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a>، ونعلة من <a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">قسم النعلات</a>.</p>
<h3>العناية</h3>
<p>فرشاة للغبار بين الأضلاع، وقماشة مبللة للبقع، ولا مذيبات.</p>
<h3>متى لا تناسبك؟</h3>
<ul>
<li>إن أردت أن تطلب دون سؤال: الموديلات التي يذكر اسمها العرض، في <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-%d9%85%d8%b6%d9%84%d8%b9/">قسم المضلع</a>، أوضح لك.</li>
<li>إن كان الجدار خارجياً أو رطباً.</li>
<li>إن كنت ستنتقل قريباً، فالأعواد لا تُفك سليمة.</li>
</ul>' ),
	'wd-ps-panel' => array( 'دليل ألواح بديل الخشب PS', '<h3>ما هي ألواح بديل الخشب PS؟</h3>
<p>ألواح طولية مضلّعة من البوليسترين (PS) بسطح خشبي. تأتي بمقاسين: 12 × 290 سم و16 × 290 سم، وبتصاميم مختلفة للأضلاع: ضلعان عريضان أو ثلاثة أضلاع في عرض 12 سم، وثلاثة أضلاع عريضة أو أربعة في عرض 16 سم. تُباع باللوح، واستخدامها المذكور الجدران والأسقف الداخلية.</p>
<h3>ما الذي يميز البوليسترين؟</h3>
<p>خفّته. اللوح يُرفع بيد واحدة ويُقص بمنشار يدوي، ولذلك هو الأسهل بين المضلعات على السقف وعلى الأبواب المخفية التي لا تتحمل مفصلاتها ثقلاً. وله في المقابل حدّان واضحان: سطحه أطرى من غيره فيترك الضغط القوي أثراً فيه، والمذيبات تذيبه، فلا يُنظَّف ولا يُدهن إلا بمواد مائية.</p>
<h3>أي تصميم للأضلاع؟</h3>
<p>الضلعان العريضان أهدأ شكلاً وأقرب إلى اللوح المسطح. والثلاثة والأربعة تصنع ظلالاً أكثر وتُظهر شكل المضلع من بعيد. اختر تصميماً واحداً للسطح كله، فمواضع الأضلاع لا تتوافق بين تصميم وآخر.</p>
<h3>كم لوحاً؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">عرض الجدار</th><th scope="col">ألواح 12 سم</th><th scope="col">ألواح 16 سم</th></tr>
</thead>
<tbody>
<tr><td>المتر الواحد</td><td>100 ÷ 12 = 8.3</td><td>100 ÷ 16 = 6.25</td></tr>
<tr><td>2.5 م</td><td>21</td><td>16</td></tr>
<tr><td>3 م</td><td>25</td><td>19</td></tr>
<tr><td>4.5 م</td><td>38</td><td>29</td></tr>
