</table>
<p>أضف لوحاً للقصّ. وللسقف احسب بالطريقة نفسها على عرض السقف، واللوح يغطي 2.90 م من طوله. الأرقام النهائية من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>جدار التلفاز وخلفية السرير</td><td>مناسب</td><td>بعيد عن الاحتكاك</td></tr>
<tr><td>السقف والباب المخفي</td><td>مناسب جداً</td><td>الوزن الخفيف</td></tr>
<tr><td>أسفل جدار الممر وغرفة الأطفال</td><td>غير مفضّل</td><td>الضربات والألعاب تترك انبعاجات</td></tr>
<tr><td>مطبخ وحمّام</td><td>الجدار البعيد عن الماء فقط</td><td>يتحمل الرطوبة العادية لا الماء المباشر</td></tr>
<tr><td>قرب الموقد والمدفأة، والخارج</td><td>لا</td><td>البوليسترين يتأثر بالحرارة، والمجموعة داخلية</td></tr>
</tbody>
</table>
<h3>التركيب</h3>
<ul>
<li><strong>على الجدار:</strong> سطح مستوٍ ونظيف، ولصق مباشر بلا هيكل حامل. اختر لاصقاً خالياً من المذيبات، فبعض اللواصق تأكل ظهر اللوح.</li>
<li><strong>على السقف:</strong> اللاصق وحده لا يكفي لشيء معلّق، فتُضاف مسامير مخفية.</li>
<li><strong>عمودياً أو أفقياً:</strong> كلاهما ممكن، والعمودي يغطي الارتفاع بلوح واحد حتى 2.90 م.</li>
</ul>
<p>التنفيذ متاح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>قفلات من <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a5%d9%83%d8%b3%d8%b3%d9%88%d8%a7%d8%b1%d8%a7%d8%aa-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/">إكسسوارات بديل الخشب</a> بعد التأكد من توافقها، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> للأرض، وللسقف كرنيش من <a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%85%d8%af%d8%a9-%d9%88%d9%83%d8%b1%d8%a7%d9%86%d9%8a%d8%b4/">قسم الكرانيش</a> يغطي التقاءه بالجدار.</p>
<h3>العناية</h3>
<p>قماشة مبللة بماء فقط. لا تنر ولا أسيتون ولا بخاخات مذيبة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>أطرى سطحاً من بقية المضلعات.</li>
<li>لا يحتمل حرارة قريبة.</li>
<li>مقاسان فقط، فلا عرض 20 أو 30 سم للجدار الواسع.</li>
<li>لا يُفك بعد اللصق.</li>
</ul>
<p>بقية الألوان في قسم <a href="https://texadecore.store/product-category/%d8%b9%d8%b1%d9%88%d8%b6-%d8%a8%d8%af%d9%8a%d9%84-%d8%a7%d9%84%d8%ae%d8%b4%d8%a8/%d8%a3%d9%84%d9%88%d8%a7%d8%ad-%d8%a8%d8%af%d9%8a%d9%84-%d8%ae%d8%b4%d8%a8-ps/">ألواح بديل خشب PS</a>.</p>' ),
	'wp-classic' => array( 'دليل ورق الجدران الكلاسيك', '<h3>ما هو الكلاسيك في ورق الجدران؟</h3>
<p>أغلب هذه المجموعة دمشقي: وحدة زخرفية متناظرة تشبه الميدالية تتكرر صفوفاً، ومعها تصاميم بإطارات وزخارف وأعمدة وتقليم كلاسيكي. الألوان رمادي وبيج وذهبي، وفيها عنابي وكحلي وأسود على أبيض. المصدر كوري، واللفة 15.6 م بعرض 106 سم. طابعه رسمي، فهو ورق مجالس وصالات استقبال قبل أن يكون ورق غرف يومية. وهو أبطأ النقشات تقادماً، لكنه يطلب مساحة وأثاثاً من طرازه.</p>
<h3>أين يصلح وأين يثقل؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">الملاحظة</th></tr>
</thead>
<tbody>
<tr><td>مجلس واسع وصالة استقبال</td><td>مناسب</td><td>مسافة الجلوس تسمح بقراءة الزخرفة كاملة</td></tr>
<tr><td>غرفة طعام، وجدار خلف كنبة رئيسية</td><td>مناسب</td><td>يُوسَّط محور الزخرفة على قطعة الأثاث</td></tr>
<tr><td>غرفة نوم رئيسية</td><td>جدار واحد</td><td>درجات هادئة كالبيج على العاجي</td></tr>
<tr><td>غرفة صغيرة أو منخفضة السقف</td><td>غير مفضّل</td><td>الوحدة الكبيرة تُقطع عند السقف وتُشعر بالضيق</td></tr>
<tr><td>غرفة أثاثها عصري بسيط</td><td>غير مفضّل</td><td>الطرازان يتنافران</td></tr>
<tr><td>جدار رطب، مطبخ، دورة مياه</td><td>اسأل قبل الطلب</td><td>يُنصح بهذه التصاميم للجدران الجافة</td></tr>
</tbody>
</table>
<h3>كيف تختاره؟</h3>
<ul>
<li><strong>حجم الوحدة مقابل الارتفاع.</strong> يحسن أن تظهر الوحدة الدمشقية كاملة ثلاث مرات على الأقل من الأرض إلى السقف. اسأل عن ارتفاعها، قبل الطلب.</li>
<li><strong>التباين يحدد الرسمية.</strong> أسود على أبيض أو عنابي مسرحي يليق بجدار واحد، ولون على درجته يحتمل المجلس كله.</li>
<li><strong>الذهبي واللمعة.</strong> يتوهّجان تحت الثريا والإضاءة الصفراء ويبهتان تحت الأبيض البارد، فاحكم عليهما بإضاءة مجلسك.</li>
<li><strong>لا يُترك وحده.</strong> يكتمل مع ستائر ثقيلة وخشب داكن أو أثاث منحوت، وعلى جدار فارغ بأثاث خفيف يبدو غريباً.</li>
</ul>
<h3>الكمية والمطابقة</h3>
<p>الدمشقي يُطابَق صفاً بصف، فجزء من رأس كل شريحة يُقص ليستوي مع جارتها. قاعدة المتجر العامة خمس شرائح في اللفة للجدار الذي لا يزيد على 3 م، وأربع لفات لغرفة 4 × 4 م مع إبقاء مساحة الأبواب والنوافذ في الحساب. ومع وحدة كبيرة وارتفاع قريب من 3 م اطلب من الفريق تأكيد العدد قبل الدفع. انظر <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات لكل غرفة</a> و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>التركيب</h3>
<p>التناظر هو الأصل: يبدأ الفني من منتصف الجدار ليقع محور الميدالية في الوسط وتتساوى القصّتان عند الطرفين. وإن وُضع الورق داخل إطارات بانوه قُصّت كل قطعة بحيث تتوسط الوحدةُ الإطار. والجدار مستوٍ، جاف، معجون ومؤسَّس. التنسيق مع <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d9%85%d8%af%d8%a7%d8%af%d8%a7%d8%aa-%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa/">بانوهات</a> تؤطّر الورق، و<a href="https://texadecore.store/product-category/%d8%a7%d9%84%d8%a8%d8%a7%d9%86%d9%88%d9%87%d8%a7%d8%aa-%d9%88%d8%a7%d9%84%d8%b2%d8%ae%d8%a7%d8%b1%d9%81/%d8%a3%d8%b9%d9%85%d8%af%d8%a9-%d9%88%d9%83%d8%b1%d8%a7%d9%86%d9%8a%d8%b4/">كرانيش</a> عند السقف، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> عريضة. ومعها لفات من تشغيلة واحدة.</p>
<h3>العناية</h3>
<p>نفضٌ بفرشاة ناعمة أو قماشة جافة. الأجزاء المذهّبة واللامعة أرقّ من غيرها، فلا تُفرك ولا يقربها منظف، وتكفيها مسحة خفيفة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يصغّر الغرفة الصغيرة ويثقلها.</li>
<li>هدره في المطابقة أعلى من السادة والمقلّم.</li>
<li>يفرض طرازاً كاملاً على الأثاث والستائر.</li>
<li>أي خلل في التوسيط يُرى فوراً لأن الزخرفة متناظرة.</li>
</ul>' ),
	'wp-floral' => array( 'دليل ورق الجدران المورّد', '<h3>ورق الجدران المورّد: ماذا تشمل المجموعة؟</h3>
<p>تصاميم كورية رسمتها الأساسية ورد: ورود صغيرة متفرقة، باقات كبيرة، أغصان وزهور متسلقة، وورد فوق أرضية مقلّمة. اللفة 15.6 م في عرض 106 سم (وبعضها مكتوب 15.5 م). وأكثر ألوانها حضوراً الزهري والبيج والعاجي والسماوي، فهي أقرب إلى الغرف الهادئة منها إلى المجالس الرسمية. والورد أصعب النقشات تنسيقاً وأجملها حين يُضبط، لأنه لون ورسمة واتجاه في آن واحد.</p>
<h3>حجم الوردة يحدد المكان</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">حجم الرسمة</th><th scope="col">أثرها في الغرفة</th><th scope="col">أين توضع</th></tr>
</thead>
<tbody>
<tr><td>ورود صغيرة متفرقة</td><td>تبدو من بعيد ملمساً ناعماً ولا تصغّر الغرفة</td><td>جدران غرفة النوم كلها، وغرف البنات</td></tr>
<tr><td>ورود متوسطة أو أغصان متسلقة</td><td>حركة واضحة تشدّ النظر إلى أعلى</td><td>جدار خلف السرير أو ركن الجلوس</td></tr>
<tr><td>باقات كبيرة</td><td>تملأ الجدار وتقرّبه</td><td>جدار واحد في غرفة واسعة، والباقي لون هادئ</td></tr>
<tr><td>ورد على مقلّم</td><td>طابع ريفي كلاسيكي</td><td>غرف النوم وغرف الضيوف</td></tr>
</tbody>
</table>
<p>ولا يوضع خلف مغسلة ولا في مطبخ دون سؤال الفريق أولاً، فهو للجدران الجافة.</p>
<h3>كيف تنسّقه دون ازدحام؟</h3>
<ul>
<li><strong>الورد هو النقشة الوحيدة.</strong> ستارة ومفرش بلون واحد مأخوذ من لون ثانوي في الرسمة، كأخضر الأوراق أو بيج الأرضية، لا من لون الوردة نفسها.</li>
<li><strong>أرضية الورق أهم من الورد.</strong> الخلفية العاجية تدفئ الغرفة، والرمادية والسماوية تبرّدانها، وعليها تُختار درجة الأثاث.</li>
<li><strong>الأثاث المزخرف يتصارع معه.</strong> سرير بظهر منقوش أمام جدار مورّد يضيّع الاثنين.</li>
<li><strong>اسأل نفسك عن المدة.</strong> الورد الهادئ على أرضية فاتحة يعيش معك سنوات، والصارخ تملّه بسرعة.</li>
</ul>
<h3>الكمية والمطابقة</h3>
<p>للورد اتجاه: الساق إلى أسفل والزهرة إلى أعلى، فلا تُقلب شريحة لتوفير قصاصة. الورود المتفرقة الصغيرة سهلة المطابقة، والباقات الكبيرة تأكل من طول اللفة أكثر. الأصل المعتمد في المتجر خمس شرائح من كل لفة ما لم يتجاوز الارتفاع 3 م، ولا تُخصم فتحات الأبواب والنوافذ. اسأل عن تكرار الرسمة إن كانت الباقة كبيرة، واستعن بـ<a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات لكل غرفة</a> و<a href="https://texadecore.store/quantity-calculator/">الحاسبة</a>.</p>
<h3>التركيب</h3>
<p>على جدار جاف معجون ومؤسَّس. والمهم هنا موضع الرسمة: يوسَّط الفني الباقة على محور السرير أو الكنبة لا على طرف الجدار، ويتفادى أن يقع نصف وردة عند خط السقف. الحجز من <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>لبقية الجدران <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">سادة</a> بلون أرضية الورق، أو تصفّح الدرجات في <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d9%88%d8%b1%d9%82-%d8%ac%d8%af%d8%b1%d8%a7%d9%86-%d9%88%d8%b1%d8%af%d9%8a/">الوردي</a> و<a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d9%88%d8%b1%d9%82-%d8%ac%d8%af%d8%b1%d8%a7%d9%86-%d8%a8%d9%8a%d8%ac/">البيج</a>. واشترِ لفاتك دفعة واحدة.</p>
<h3>العناية</h3>
<p>نفض الغبار بفرشاة ناعمة، ومسحة خفيفة بقماشة شبه جافة عند الحاجة. الخلفيات الفاتحة تُظهر أثر الأصابع حول المفاتيح، فامسحها أولاً بأول.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>ذوقه محدد، فلا يرضي كل أهل البيت ولا كل مشترٍ لو عُرض المنزل للبيع.</li>
<li>يقيّد اختيار الستائر والمفارش بعده.</li>
<li>الباقات الكبيرة ترفع عدد اللفات.</li>
<li>لا يلائم الأثاث العصري الحادّ الخطوط.</li>
</ul>' ),
	'wp-kids' => array( 'دليل ورق جدران غرف الأطفال', '<h3>ورق جدران غرف الأطفال</h3>
<p>تصاميم كورية مرسومة للصغار: أشكال وألوان، سيارات، مناطيد، حيوانات، كواكب، حروف، ومقلّم بألوان طفولية. اللفة بالمقاس المعتاد، 15.6 م طولاً و106 سم عرضاً. وما يميز هذا النوع ليس الخامة بل ظرف الغرفة: ساكنها يكبر، ويلمس الجدار ويكتب عليه.</p>
<h3>اختر بحسب العمر</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">عمر الطفل</th><th scope="col">ما يناسبه</th><th scope="col">لماذا</th></tr>
</thead>
<tbody>
<tr><td>رضيع إلى 3 سنوات</td><td>ألوان هادئة وأشكال بسيطة متباعدة</td><td>الغرفة للنوم أولاً، والرسمة المزدحمة لا تساعد على الهدوء</td></tr>
<tr><td>4 إلى 8 سنوات</td><td>سيارات، حيوانات، مناطيد، كواكب</td><td>سنّ الشخصيات والحكايات، ورأي الطفل هنا مهم</td></tr>
<tr><td>9 إلى 12 سنة</td><td>مقلّم، أشكال هندسية، حروف</td><td>يرفض قريباً كل ما يراه طفولياً</td></tr>
<tr><td>غرفة مشتركة</td><td>رسمة محايدة لا تخص ولداً أو بنتاً</td><td>تبقى صالحة للاثنين</td></tr>
</tbody>
</table>
<h3>اعتبارات تخص غرفة الطفل</h3>
<ul>
<li><strong>جدار واحد للرسمة.</strong> اجعل التصميم الطفولي خلف السرير أو في ركن اللعب، والباقي <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">سادة</a>. حين يكبر تبدّل جداراً لا غرفة.</li>
<li><strong>المتر الأول من الأرض منطقة خطر.</strong> هناك الأقلام والأيدي والألعاب، فالخلفية البيضاء الصافية أسوأ اختيار لها، والرسمة الكثيفة تستر أثر الاستعمال أكثر.</li>
<li><strong>الأقلام.</strong> يُمسح بقطعة قماش، وهذا للغبار والبقع الخفيفة. أما الحبر والألوان الشمعية فلا نعدك بزوالها.</li>
<li><strong>الرائحة والتهوية.</strong> ركّب الورق قبل سكن الغرفة بأيام وهوِّها جيداً، فللغراء رائحة تخفّ مع التهوية.</li>
<li><strong>غرفة رضيع أو طفل حسّاس؟</strong> اسأل الفريق عما يتوفر من شهادات فحص قبل الطلب.</li>
</ul>
<h3>الكمية</h3>
<p>جدار الرسمة يُحسب وحده: اقسم عرضه على 1.06 م لتعرف عدد الشرائح، واللفة الواحدة فيها خمس ما دام السقف عند 3 م أو دونها. وللغرفة كاملة بقياس 4 × 4 م أربع لفات، ولا داعي لخصم الباب والنافذة. الرسوم الكبيرة كالسيارات والمناطيد تُطابَق بين الشرائح، فاسأل عن تكرارها. جرّب أرقام غرفتك في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a> أو <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات</a>.</p>
<h3>التركيب</h3>
<p>يُثبَّت الورق جيداً عند الحافة السفلية والزوايا، فهي أول ما تمتد إليه يد الطفل ليقشّره. تُبعَد الأسرّة والخزائن قبل الموعد، ويُعالَج الجدار بالمعجون والأساس كالعادة. الموعد من <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> أعلى قليلاً تحمي أسفل الورق من عجلات الألعاب، ولفة احتياط لأن الإصلاح في هذه الغرفة متوقع. وكل التصاميم في <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d9%88%d8%b1%d9%82-%d8%ac%d8%af%d8%b1%d8%a7%d9%86-%d8%a7%d8%b7%d9%81%d8%a7%d9%84/">قسم ورق جدران الأطفال</a>.</p>
<h3>العناية</h3>
<p>امسح البقعة فور حدوثها بقماشة رطبة معصورة، وجرّب أي منظف في زاوية مخفية. ولا تلصق عليه ملصقات ولا شريطاً لاصقاً، فنزعها يسلخ وجه الورق. واحتفظ بقصاصات التركيب، فقد تنفع الفني في ترقيع موضع صغير بدل تبديل شريحة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>عمره من عمر ذوق الطفل، لا من عمر الورق.</li>
<li>أكثر غرف البيت تعرضاً للخدش والكتابة والتقشير.</li>
<li>تبديل شريحة مرسومة يحتاج لفة من التشغيلة نفسها.</li>
<li>جدار رطب أو يلاصق دورة مياه: اسأل قبل الطلب.</li>
</ul>' ),
	'wp-marble' => array( 'دليل ورق الجدران الرخامي', '<h3>ما هو ورق الجدران الرخامي؟</h3>
<p>ورق كوري مطبوع عليه شكل الرخام: عروق واضحة، أو تموّج ناعم كالسحاب، أو تدرّج بين درجتين. يأتي في لفة 15.6 م × 106 سم كبقية ورق المتجر. هو صورة الرخام لا مادته، فيعطيك لونه وحركته دون برودته وصلابته ووزنه، ويُعامَل معاملة الورق لا معاملة الحجر.</p>
<h3>ورق رخامي أم ألواح بديل الرخام؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">البند</th><th scope="col">ورق الجدران الرخامي</th><th scope="col">ألواح بديل الرخام</th></tr>
</thead>
<tbody>
<tr><td>الشكل</td><td>لفة مرنة تُلصق بالغراء</td><td>لوح صلب يُثبَّت على الجدار</td></tr>
<tr><td>الملمس عند اللمس</td><td>ورق، لا يوحي بالحجر</td><td>سطح صلب أقرب إلى الحجر</td></tr>
<tr><td>الطَّرق والاحتكاك</td><td>يتأثر بهما</td><td>أكثر تحملاً</td></tr>
<tr><td>قرب الماء</td><td>اسأل قبل الطلب</td><td>راجع مواصفات اللوح نفسه</td></tr>
<tr><td>التغيير لاحقاً</td><td>تُنزع الشرائح ويُعاد تجهيز الجدار</td><td>تثبيته أقرب إلى الدائم</td></tr>
<tr><td>أنسب استعمال</td><td>جدار غرفة نوم أو مجلس أو مكتب</td><td>خلف التلفاز، المداخل، الجدران المعرّضة للّمس</td></tr>
</tbody>
</table>
<p>الألواح في قسم <a href="https://texadecore.store/product-category/%d8%a8%d8%af%d9%8a%d9%84-%d8%b1%d8%ae%d8%a7%d9%85/">بديل الرخام</a>.</p>
<h3>كيف تختار العِرق واللون؟</h3>
<ul>
<li><strong>المموّج أهدأ من المعرَّق.</strong> التموّج الناعم يحتمل جدارين أو أكثر، والعروق الحادة الداكنة مكانها جدار واحد.</li>
<li><strong>العِرق المميّز يتكرر.</strong> على جدار طويل ترى الخط نفسه يعود كل مسافة، فيُعرف أنه مطبوع. كلما كانت الرسمة أنعم وأقل تبايناً خفي التكرار.</li>
<li><strong>لا تجاوره برخام حقيقي.</strong> أرضية رخام أو سطح طاولة حجري بجانبه يكشف الفرق، والأفضل أن يجاور الخشب والقماش.</li>
<li><strong>الرمادي والبيج أغلب المجموعة.</strong> الرمادي مع أثاث أبيض ومعدني، والبيج والبني مع الخشب الدافئ.</li>
</ul>
<h3>الكمية</h3>
<p>تُعدّ بالشرائح لا بالمتر المربع: خمس من اللفة الواحدة لجدار ارتفاعه حتى 3 م، وغرفة 4 × 4 م كاملة تأخذ أربع لفات من غير أن تطرح الأبواب والنوافذ. وهل تتصل العروق بين شريحة وأخرى أم لا؟ اسأل عنه لأنه يحدد الهدر. المرجع <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات لكل غرفة</a> ثم <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>التركيب</h3>
<p>الفواصل هي نقطة الضعف هنا، فالرخام الحقيقي يُرى ألواحاً كبيرة، وخط فاصل ظاهر كل 106 سم يفسد الإيهام. لذلك يُسوّى الجدار جيداً ويُؤسَّس، وتُضغط الحواف بإحكام، ويُتجنَّب كشاف يمسح الجدار من الجانب فيُبرز كل التقاء. وتُعلَّق الشرائح كلها باتجاه واحد حتى لا ينقلب ميل العروق. التنفيذ لدى <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> بيضاء أو بلون العِرق، ولفة زائدة من الدفعة ذاتها.</p>
<h3>العناية</h3>
<p>لا يُنظَّف كما يُنظَّف الرخام: لا ماء جارٍ ولا ملمّع. قماشة ناعمة جافة، أو مبللة معصورة للبقعة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>لا يقنع من يلمسه بأنه حجر.</li>
<li>تكرار العِرق والفواصل يظهران على الجدران الطويلة.</li>
<li>لا يصلح للأرضيات ولا لأسطح المطابخ ولا لما حول الموقد.</li>
<li>لا يتحمل ما يتحمله اللوح الصلب في مدخل مزدحم.</li>
</ul>
<p>إن كان الجدار معرّضاً للّمس أو قريباً من الماء فابدأ من <a href="https://texadecore.store/buying-guide/">دليل الشراء</a> للمقارنة.</p>' ),
	'wp-modern' => array( 'دليل ورق الجدران المودرن', '<h3>ما المقصود بالمودرن والمموّج؟</h3>
<p>تصاميم كورية بخطوط هندسية أو رسوم معاصرة بدل الزخرفة التقليدية، وكلها في لفة طولها 15.6 م وعرضها 106 سم. تحت هذا الاسم أربعة أنواع تختلف في الاستعمال اختلافاً كبيراً، فاعرف نوع تصميمك أولاً.</p>
<table class="txa-family">
<thead>
<tr><th scope="col">النوع</th><th scope="col">أمثلة من المجموعة</th><th scope="col">يصلح له</th><th scope="col">انتبه</th></tr>
</thead>
<tbody>
<tr><td>هندسي</td><td>أقواس، مربعات، هرمي</td><td>خلف التلفاز، المكتب، المدخل</td><td>يفضح ميل الجدار والسقف</td></tr>
<tr><td>مموّج</td><td>تموّجات ناعمة متدرجة</td><td>غرف المعيشة والنوم، وجدران متجاورة</td><td>اتجاه الموجة واحد في كل الشرائح</td></tr>
<tr><td>مطبوع برسوم</td><td>نيويورك، أبراج، شوارع، كتابة، قهوة</td><td>غرفة شاب، مقهى، ركن قهوة منزلي</td><td>يحتاج جداراً خالياً من الفتحات</td></tr>
<tr><td>بمظهر جلد أو معدن</td><td>جلد ثلاثي الأبعاد، معدني صناعي</td><td>جدار واحد في مكتب أو مجلس رجال</td><td>يتغير شكله بتغير الإضاءة</td></tr>
</tbody>
</table>
<h3>كيف تختار؟</h3>
<ul>
<li><strong>ابدأ بالجدار لا بالتصميم.</strong> الرسمة المطبوعة تضيع خلف خزانة أو بين نافذتين. قس المساحة المكشوفة فعلاً بعد وضع الأثاث.</li>
<li><strong>«ثلاثي الأبعاد» أثر بصري.</strong> ظلّ مطبوع يوهم بالعمق، والسطح نفسه مستوٍ، فلا تتوقع بروزاً يُلمس.</li>
<li><strong>الهندسي يحبّ الخطوط البسيطة.</strong> كنبة مستقيمة وطاولة بلا زخارف، ولون أو لونان لا أكثر في بقية الغرفة.</li>
<li><strong>المموّج لمن يريد حركة بلا رسمة.</strong> أهدأ الأنواع الأربعة، ويحتمل جدارين متجاورين دون أن يُتعب.</li>
<li><strong>الرمادي الغالب بارد.</strong> أكثر هذه التصاميم رمادي وبيج، فأدفئ الغرفة بخشب أو إضاءة صفراء إن كانت قليلة الشمس.</li>
<li><strong>الكتابة والمدن عمرها أقصر.</strong> تناسب مرحلة أو نشاطاً تجارياً أكثر مما تناسب غرفة تريدها عشر سنين.</li>
</ul>
<h3>الكمية</h3>
<p>القاعدة المنشورة في المتجر: كل لفة خمس شرائح إذا كان الارتفاع 3 م فأقل، وغرفة 4 × 4 م أربع لفات، بلا خصم للأبواب والنوافذ. المودرن يُشترى غالباً لجدار واحد، فاحسب: عرض الجدار ÷ 1.06 م = عدد الشرائح، ثم قرّبه إلى أعلى. الأشكال الهندسية الكبيرة تحتاج مطابقة، فأكّد مسافة تكرارها مع الفريق. الأرقام في <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات</a> و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>التركيب</h3>
<p>الخط المستقيم لا يرحم: يُضبط أول شريط بالشاقول، وتُراجَع استقامة السقف قبل القص، لأن صف المربعات إذا لامس سقفاً مائلاً ظهر الميل للعين. وفي الرسوم المطبوعة يُتفق قبل القص على الجزء الذي يتوسط الجدار، برجاً كان أو عبارة. وأخبر الفني بأماكن الأفياش ومخارج الشاشة مسبقاً. الجدار جاف، معجون، وعليه أساس. الحجز عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">سادة</a> من درجة الرسمة الأفتح للجدران الثلاثة الباقية، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> بلون محايد. واللفات كلها من تشغيلة واحدة.</p>
<h3>العناية</h3>
<p>مسح جاف دوري، وقماشة رطبة للبقع دون منظفات قوية. السطح الداكن واللامع يُظهر الغبار وأثر المسح، فجفّفه بحركة واحدة من أعلى إلى أسفل.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يكشف أي ميل في البناء.</li>
<li>الرسوم الصريحة تُملّ وتقيّد الأثاث.</li>
<li>لا ينسجم مع غرفة أثاثها كلاسيكي مذهّب.</li>
<li>الأماكن الرطبة: اسأل قبل الطلب.</li>
</ul>' ),
	'wp-pattern' => array( 'دليل ورق الجدران المنقوش', '<h3>ما الذي يدخل تحت «النقشات»؟</h3>
<p>كل ورق تتكرر عليه رسمة: أوراق نبات وسعف نخيل وموز، زخارف، شيفرون، كابيتونيه، ضربات فرشاة، جبال وأشجار. المجموعة كلها كورية، ولفتها 15.6 م بعرض 106 سم. والذي يفرقها عن السادة أمران: الرسمة تُطابَق بين كل شريحة وجارتها، وجزء من اللفة يذهب هدراً في هذه المطابقة.</p>
<h3>المطابقة والهدر: اعرف نوع نقشتك</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">نوع المطابقة</th><th scope="col">كيف تعرفه</th><th scope="col">أثره على الكمية</th></tr>
</thead>
<tbody>
<tr><td>حرة</td><td>رسمة عشوائية أو صغيرة جداً لا يلزم ضبطها</td><td>لا هدر إضافي يُذكر</td></tr>
<tr><td>مستقيمة</td><td>الرسمة تكتمل أفقياً على الارتفاع نفسه في كل شريحة</td><td>يُقص من رأس كل شريحة حتى تتطابق</td></tr>
<tr><td>منزاحة</td><td>الرسمة تنزل نصف تكرار في الشريحة التالية</td><td>أعلى الأنواع هدراً</td></tr>
</tbody>
</table>
<p>اسأل عن مسافة تكرار الرسمة ونوع مطابقتها قبل الطلب. حساب المتجر المنشور خمس شرائح للفة حتى ارتفاع 3 م، وغرفة 4 × 4 م بأربع لفات دون خصم الأبواب والنوافذ. وكلما كبرت الرسمة واقترب جدارك من 3 م ضاق هامش القص، فاطلب تأكيد العدد من الفريق أو من <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>، وقارن بـ<a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات حسب الغرفة</a>.</p>
<h3>كيف تختار النقشة؟</h3>
<p>يوضع على جدار جاف في المجلس أو غرفة النوم أو المدخل، وأما المطبخ ودورة المياه فاسأل قبل الطلب.</p>
<ul>
<li><strong>حجم الرسمة على قدر مسافة النظر.</strong> الورقة الكبيرة تحتاج أن تتراجع عنها ثلاثة أمتار لتُقرأ، والصغيرة تذوب من بعيد فتبدو ملمساً.</li>
<li><strong>جدار واحد أم الغرفة كلها؟</strong> الرسمة الكبيرة عالية التباين لجدار واحد، والهادئة القريبة ألوانها من بعض تحتمل الجدران الأربعة.</li>
<li><strong>عُدّ ما في الغرفة من نقوش.</strong> سجاد منقوش وستارة منقوشة وجدار منقوش أكثر مما تحتمله غرفة واحدة.</li>
<li><strong>لون الأرضية.</strong> خذ من النقشة لونها الثانوي للستارة أو الوسائد، واترك الأرضية محايدة.</li>
</ul>
<h3>التركيب</h3>
<p>تُعلَّق الشريحة الأولى على خط شاقولي مرسوم، فأي ميل فيها يتراكم حتى تظهر الرسمة مائلة عند السقف. ويبدأ الفني من منتصف الجدار الرئيسي أو من أوضح زاوية للداخل، ويجعل آخر التقاء، وهو الوحيد الذي لا تتطابق فيه الرسمة، في أقل الزوايا ظهوراً. الجدار نفسه يلزمه ما يلزم أي ورق: جفاف ومعجون وأساس. التفاصيل مع <a href="https://texadecore.store/install-services/">فريق التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>اطلب اللفات كلها من تشغيلة واحدة، وزد لفة إن كان الجدار مليئاً بالنوافذ أو الرسمة كبيرة. وللجدران الباقية <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">سادة</a> بلون مأخوذ من النقشة.</p>
<h3>العناية</h3>
<p>تكفي فرشاة ناعمة للغبار، وقطعة قماش رطبة معصورة للبقعة. النقشة تُخفي أثر اللمس اليومي أكثر من اللون الواحد، لكنها لا تحتمل الفرك ولا المنظفات القوية.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يستهلك لفات أكثر من السادة للمساحة نفسها.</li>
<li>السقف المائل أو الزاوية غير القائمة يظهران فوراً مقابل رسمة منتظمة.</li>
<li>تبديل شريحة تالفة يحتاج لفة من التشغيلة نفسها وبداية الرسمة نفسها.</li>
<li>تملّ منه أسرع مما تملّ من لون هادئ.</li>
</ul>' ),
	'wp-plain' => array( 'دليل ورق الجدران السادة', '<h3>ما هو ورق الجدران السادة؟</h3>
<p>لفة بلون واحد بلا رسمة، تؤدي دور الدهان لكن بسطح أنعم ملمساً وأهدأ مظهراً. تصاميم هذه المجموعة كورية المنشأ، واللفة 15.6 م طولاً في 106 سم عرضاً (وقليل منها 15.5 م)، وتغطي اللفة نحو 16.5 م². العرض القريب من المتر يعني فواصل أقل على الجدار. وبعض ما يُسمّى هنا سادة فيه تنقيط أو تخطيط خافت لا يُرى إلا من قرب.</p>
<h3>أين يصلح وأين لا يصلح؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">المكان</th><th scope="col">الحكم</th><th scope="col">السبب</th></tr>
</thead>
<tbody>
<tr><td>غرف النوم والمجالس والمكاتب</td><td>مناسب</td><td>جدران جافة قليلة الاحتكاك</td></tr>
<tr><td>جدران الغرفة كلها خلفيةً للأثاث</td><td>مناسب</td><td>لا رسمة تزاحم الستائر والسجاد</td></tr>
<tr><td>الممرات وخلف الكراسي</td><td>مقبول بحذر</td><td>الاحتكاك يترك لمعة وخدوشاً تظهر على اللون الواحد</td></tr>
<tr><td>المطبخ والحمام وأي جدار فيه رطوبة</td><td>اسأل قبل الطلب</td><td>هو للجدران الجافة</td></tr>
<tr><td>جدار متموج أو معجونه غير مصنفر</td><td>لا قبل التسوية</td><td>السادة الفاتح يكشف كل نتوء تحت الضوء الجانبي</td></tr>
</tbody>
</table>
<h3>كيف تختار اللون والدرجة؟</h3>
<ul>
<li><strong>الفاتح يوسّع والغامق يقرّب.</strong> الأبيض والبيج يريحان الغرفة الصغيرة، والداكن يليق بجدار واحد في غرفة واسعة جيدة الإضاءة.</li>
<li><strong>الداكن السادة أصعب.</strong> يُظهر الغبار وأثر اليد وخط التقاء الشريحتين أكثر من الفاتح.</li>
<li><strong>احكم على اللون في غرفتك.</strong> درجة الشاشة غير درجة الجدار، والبيج نفسه يميل للأصفر تحت إضاءة دافئة وللرمادي تحت البيضاء.</li>
<li><strong>اطلب الكمية كلها مرة واحدة.</strong> فرق الدرجة بين تشغيلتين يُرى على اللون الواحد أوضح مما يُرى على أي نقشة.</li>
</ul>
<p>ولأنه بلا نقشة تُطابَق فهدره أقل ما يكون: اللفة تعطي 5 شرائح حتى ارتفاع 3 م، وغرفة 4 × 4 م تحتاج 4 لفات، والأفضل ألا تخصم الأبواب والنوافذ. راجع <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول اللفات لكل غرفة</a> أو <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>ما يحتاجه الجدار قبل التركيب</h3>
<p>السادة أقل الأنواع تسامحاً مع الجدار. يلزمه معجون مصنفر حتى النعومة، وسطح جاف نظيف، وأساس يوحّد لون الجدار كي لا تشفّ بقعة داكنة من تحت ورق فاتح. يُفرد غراء ورق الجدران بالتساوي، وتتلاقى الشرائح حافة لحافة دون تراكب. التنفيذ متاح عبر <a href="https://texadecore.store/install-services/">خدمات التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>لفة احتياط من التشغيلة نفسها تُحفظ لإصلاح لاحق، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلات</a> تُنهي التقاء الورق بالأرضية. أما الغراء والأساس فاسأل هل يحضرهما فريق التركيب.</p>
<h3>العناية والتنظيف</h3>
<p>الغبار يُزال بقطعة قماش ناعمة جافة. والبقعة تُمسح بقطعة مبللة معصورة جيداً دون فرك ثم تُجفَّف، فالفرك يترك على اللون الواحد لمعة لا تزول.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يكشف نتوءات الجدار وتموجه ولا يسترها.</li>
<li>الخدش والبقعة لا يجدان نقشة يختبئان فيها.</li>
<li>إصلاح جزء تالف يعني تبديل الشريحة كاملة.</li>
<li>لا يعالج الرطوبة، بل ينفصل عن الجدار الرطب.</li>
</ul>
<p>إن كان جدارك غير مثالي ولا تنوي تسويته، أو في البيت صغار يلمسون الجدران، فانظر في <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d9%86%d9%82%d8%b4%d8%a7%d8%aa/">تصاميم النقشات</a> فهي أرحم بأثر الاستعمال اليومي.</p>' ),
	'wp-plain-texture' => array( 'دليل ورق الجدران القماشي والتكستشر', '<h3>ما المقصود بالورق القماشي والتكستشر؟</h3>
<p>ورق لونه واحد كالسادة، لكن سطحه يحمل ملمس نسيج: قماش ناعم، كتان، أو حبيبات خشنة. المقصود مظهر القماش وملمسه على سطح الورق، لا قماشاً حقيقياً ملصوقاً على الجدار. أغلب التصاميم كورية بلفة 15.6 م × 106 سم. وتصاميم «تكستشر MF» أكّد مقاس لفتها قبل أن تحسب الكمية.</p>
<h3>أي ملمس تختار؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">الملمس</th><th scope="col">شكله على الجدار</th><th scope="col">أنسب مكان له</th></tr>
</thead>
<tbody>
<tr><td>قماشي ناعم</td><td>نسيج دقيق متقاطع يُرى من قرب فقط</td><td>غرف النوم، وجدران الغرفة كاملة</td></tr>
<tr><td>كتاني</td><td>خيوط أوضح متفاوتة السماكة</td><td>المجالس وغرف المعيشة والمكاتب</td></tr>
<tr><td>محبب وخشن</td><td>حبيبات ظاهرة تذكّر باللياسة الناعمة</td><td>جدار واحد تمرّ عليه إضاءة جانبية</td></tr>
<tr><td>منقط أو بحافة ممزقة</td><td>ملمس معه أثر زخرفي خفيف</td><td>حين تريد حركة دون نقشة صريحة</td></tr>
</tbody>
</table>
<p>مكانه الجدران الداخلية الجافة: غرف النوم والمجالس والمكاتب وخلف التلفاز. ولا يوضع خلف مغسلة ولا في ممر ضيق تحتكّ به الأكتاف والحقائب، ولا على جدار تلمسه أيدي الصغار كل يوم.</p>
<h3>ما الذي يميزه عن السادة الأملس؟</h3>
<ul>
<li><strong>الضوء يصنع نصف شكله.</strong> قرب نافذة أو كشاف جداري يبرز النسيج ويعطي الجدار عمقاً، وتحت إضاءة سقف مسطحة يقترب من السادة العادي.</li>
<li><strong>أهدأ مع الجدار العادي.</strong> التموج الخفيف جداً أقل لفتاً للنظر عليه من السطح الأملس، لكنه لا يستر شقاً ولا نتوءاً، فالمعجون والصنفرة لازمان في الحالتين.</li>
<li><strong>للخيوط اتجاه.</strong> في الكتاني تُعلَّق الشرائح كلها بالاتجاه نفسه، وإلا ظهر فرق لمعة بين شريحة وجارتها.</li>
<li><strong>الصورة لا تنقل الملمس.</strong> كبّر صور المنتج أو اطلب صورة قريبة قبل أن تقرر.</li>
</ul>
<p>الحساب كحساب السادة: خمس شرائح من اللفة ما دام ارتفاع الجدار 3 م أو أقل، دون خصم للأبواب والنوافذ، والتفصيل في <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">جدول عدد اللفات</a> و<a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>ملاحظات التركيب</h3>
<p>يُجهَّز الجدار كما يُجهَّز لأي ورق: جاف، نظيف، مصنفر، وعليه أساس. الفرق عند اللصق: تُكبس الشريحة بفرشاة أو رولة ناعمة لا بسكين قاسية تسحق الحبيبات، ويُمسح الغراء الزائد عن الوجه فوراً لأنه يعلق بين الخيوط ويجفّ لامعاً. يتولى ذلك فنيو <a href="https://texadecore.store/install-services/">خدمة التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p>لفة إضافية من الدفعة نفسها، و<a href="https://texadecore.store/product-category/%d9%86%d8%b9%d9%84%d8%a7%d8%aa/">نعلة</a> تحمي الحافة السفلية من المكنسة والممسحة.</p>
<h3>تنظيفه</h3>
<p>الغبار يستقر بين الحبيبات، فأزله بفرشاة ناعمة أو بمكنسة كهربائية رأسها ناعم. البقعة تُربَّت بقطعة قماش رطبة ولا تُفرك، وجرّب أولاً في موضع مخفي.</p>
<h3>عيوبه ومتى تتركه</h3>
<ul>
<li>يجمع الغبار أكثر من السطح الأملس.</li>
<li>البقع الدهنية وآثار الأقلام تدخل بين الحبيبات ويصعب إخراجها.</li>
<li>الاحتكاك المتكرر يملّس الحبيبات فتظهر رقعة لامعة.</li>
<li>يُبعد عن المطابخ والحمامات، فالأماكن الرطبة: اسأل قبل الطلب.</li>
</ul>
<p>لممر مزدحم أو جدار خلف طاولة الطعام، <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">السادة الأملس</a> أسهل مسحاً، وباقي الخيارات في <a href="https://texadecore.store/buying-guide/">دليل الشراء</a>.</p>' ),
	'wp-stripe' => array( 'دليل ورق الجدران المقلّم', '<h3>ورق الجدران المقلّم</h3>
<p>خطوط متوازية بطول اللفة، رفيعة أو عريضة، ومعها في المجموعة كاروهات وتقليم تتخلله أوراق نباتية. المنشأ كوري، ومقاس اللفة 106 سم عرضاً و15.6 م طولاً. ولأن اللفة تُعلَّق من السقف إلى الأرض، فالخطوط على جدارك رأسية. وهو أبسط النقشات شكلاً وأدقها تنفيذاً، ويغيّر إحساسك بارتفاع الغرفة وعرضها أكثر مما يغيّره أي لون.</p>
<h3>ماذا يفعل الخط بالغرفة؟</h3>
<table class="txa-family">
<thead>
<tr><th scope="col">نوع التقليم</th><th scope="col">أثره على الإحساس بالمكان</th><th scope="col">يناسب</th><th scope="col">لا يناسب</th></tr>
</thead>
<tbody>
<tr><td>رأسي رفيع بدرجتين متقاربتين</td><td>يرفع السقف قليلاً ويبدو من بعيد كالسادة</td><td>الغرفة كلها، والممرات</td><td>—</td></tr>
<tr><td>رأسي رفيع عالي التباين</td><td>يرفع السقف بوضوح ويُتعب العين عن قرب</td><td>جدار واحد</td><td>غرفة النوم كاملة، وخلف شاشة المكتب</td></tr>
<tr><td>رأسي عريض</td><td>حضور قوي وطابع رسمي، ويضيّق الجدار القصير</td><td>مجلس واسع أو مدخل</td><td>غرفة ضيقة عالية السقف</td></tr>
<tr><td>كاروهات</td><td>يوازن بين الارتفاع والعرض</td><td>مكتب، غرفة شاب</td><td>جدار غير مستوٍ</td></tr>
</tbody>
</table>
<h3>كيف تختاره؟</h3>
<ul>
<li><strong>قِس ارتفاع سقفك أولاً.</strong> التقليم الرأسي علاج للسقف المنخفض. وفي غرفة سقفها عالٍ ومساحتها صغيرة يزيدها شبهاً بالبئر، والسادة هناك أولى.</li>
<li><strong>عرض الخط على قدر الجدار.</strong> الخط العريض على جدار عرضه متران يُظهر أربعة خطوط أو خمسة فقط فيبدو مقطوعاً.</li>
<li><strong>التباين هو مفتاح الهدوء.</strong> بيج على عاجي يُعاش معه، وأسود على أبيض يُنظر إليه دقائق.</li>
<li><strong>الأثاث العالي يقطع الخط.</strong> خزانة أو مكتبة أمام جدار مقلّم تُفسد امتداده، فاختر له جداراً أثاثه منخفض كالسرير والكنبة.</li>
<li><strong>لا تخطيط فوق تخطيط.</strong> ستارة مقلّمة أو سجادة مخططة بجواره تُربك العين.</li>
</ul>
<h3>الكمية</h3>
<p>التقليم الرأسي المنتظم لا يحتاج مطابقة في الارتفاع، فهدره قريب من هدر السادة: خمس شرائح للفة في الجدران التي لا تعلو على 3 م، وأربع لفات لغرفة 4 × 4 م، مع ترك الأبواب والنوافذ بلا خصم. الكاروهات والمقلّم بأوراق لهما تكرار يُطابَق، فاسأل عنه. الجدول في <a href="https://texadecore.store/2026/11/21/wallpaper-rolls-per-room-table/">عدد اللفات لكل غرفة</a>، والحساب في <a href="https://texadecore.store/quantity-calculator/">حاسبة الكميات</a>.</p>
<h3>التركيب: الشاقول قبل كل شيء</h3>
<p>هذا أكثر الأنواع حساسية للميل. انحراف سنتيمتر واحد في أول شريحة يصير خطاً مائلاً تراه العين عند الباب والنافذة والزاوية. فيُرسم خط شاقولي لكل جدار من جديد، ولا يُعتمد على زاوية الغرفة لأنها قلّما تكون قائمة. وعند الفواصل يُراعى أن يبقى تسلسل الخطوط منتظماً فلا يتجاور خطان من اللون نفسه. والجدار يُسوّى ويُؤسَّس كغيره. الخدمة متاحة من <a href="https://texadecore.store/install-services/">فريق التركيب</a>.</p>
<h3>ما يُطلب معه</h3>
<p><a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87/">سادة</a> من لون أحد الخطين لباقي الجدران، ومن <a href="https://texadecore.store/product-category/%d9%88%d8%b1%d9%82-%d8%a7%d9%84%d8%ac%d8%af%d8%b1%d8%a7%d9%86/%d8%aa%d8%b5%d9%85%d9%8a%d9%85-%d8%b3%d8%a7%d8%af%d9%87-%d9%85%d9%82%d9%84%d9%85/">قسم المقلّم</a> تجد درجات أخرى للتصميم نفسه.</p>
<h3>العناية</h3>
<p>يُمسح باتجاه الخطوط من أعلى إلى أسفل بقماشة ناعمة، جافة للغبار ورطبة قليلاً للبقعة.</p>
<h3>عيوبه ومتى لا يناسبك</h3>
<ul>
<li>يُظهر ميل الجدران والأبواب والسقف.</li>
<li>التباين العالي مرهق في غرفة تقضي فيها ساعات، ويتموّج في تصوير الجوال.</li>
<li>اللوحات والرفوف المعلقة فوقه يجب أن تُضبط على خطوطه.</li>
<li>الجدران الرطبة: اسأل قبل الطلب.</li>
</ul>' ),
);
